COLLDATA("asabahur","ur",[[10645,"§۱۲۰۳۶ ۔ ام السائب الغفاریہ\nسائب غفاری، حرف سین میں گزر چکا ہے کہ ان کی والدہ انہیں لے کر نبی صلی اللہ علیہ وسلم کے پاس آئیں، آپ نے ان کا نام عبد اللہ رکھا...... (الحدیث)"],[10646,"§۱۲۰۳۷ ۔ ام السائب النخعیہ\n(1)انہیں شرف صحابیت حاصل ہے، ابو عمر نے اسی طرح ان کا مختصر ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۵۴) الاستيعاب (۳۶۱۲) تجرید (۳۲۱/۲)"}],[10647,"§۱۲۰۳۸ ۔ ام سباع\n(1)عقیقہ کے بارے میں ان کی حدیث محمد بن سعد نے نقل کی ہے۔ بحوالہ عبد اللہ بن ادریس وہ فرماتے ہیں کہ ہم سے اسلم منقری نے بحوالہ عطاء روایت کیا ہے کہ ام سباع نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کیا ہم اولاد کا عقیقہ کریں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"۔","",{"fn":"(1) تجرید (۳۲۱/۲)"}],[10648,"§۱۲۰۳۹ ۔ ام سبرہ\n(1)ابو موسیٰ نے ذیل میں بحوالہ مستغفری ان کا ذکر کیا ہے اور رشدین بن سعد کے طریق سے بحوالہ ابو بکر انصاری، انہوں نے سمرہ سے، انہوں نے اپنی والدہ سے نقل کیا ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس کا وضو نہیں اس کی نماز نہیں، جس نے اللہ کا ذکر نہیں کیا، اس کا وضو نہیں۔\" (الحدیث)(2) فرماتے ہیں: ان کی حدیث کی اسناد میں تردد ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۵۵) تجرید (۳۲۱/۲)\n(2) جامع المسانید والسنن (۲۴۶/۱۶)"}],[10649,"§۱۲۰۴۰ ۔ ام سعد الأنصاریہ\n(1)سعد بن معاذ کی والدہ ہیں، ابو عمر نے ان کا ذکر کیا ہے، حرف کاف میں گزر چکا ہے کہ ان کا نام کبشہ ہے، لیلیٰ بنت خطیم اوسیہ کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۵۶) الاستيعاب (۶۴۱۳) تجرید (۳۲۱/۲)"}],[10650,"§۱۲۰۴۱ ۔ ام سعد بنت زید\nبن ثابت انصاریہ، ابو عمر کا قول ہے: ان سے احادیث مروی ہے، ان میں سے پچھنے لگوانے سے خون کے بارے میں ہے، جو محمد بن زاذان کی ان سے مروی روایت ہے، بعض کا قول ہے: انہوں نے ان سے حدیث نہیں سنی۔ میں کہتا ہوں: ابن ماجہ، حسن بن سفیان، ابو یعلیٰ، ابن مندہ وغیرہ نے اسے موصولاً نقل کیا ہے۔ ابن مندہ نے ایک نسخہ روایت کیا ہے جو کئی احادیث پر مشتمل ہے، فرماتے ہیں: ہمیں علی بن محمد بن نصر نے بتایا، وہ کہتے ہیں کہ ہم سے محمد بن ایوب نے بیان کیا، وہ فرماتے ہیں کہ ہم سے عتبان بن مالک نے روایت کی، وہ فرماتے ہیں کہ ہم سے عنبسہ بن عبد الرحمن نے بحوالہ محمد بن زاذان، انہوں نے ام سعد سے روایت کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم پچھنے لگوانے کے بعد خون کو دفن کرنے کا حکم دیتے تھے۔ ان سے مروی ہے: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی۔ آپ صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کے گھر میں تھے اور پیٹ کی تکلیف سے آہ آہ کر رہے اور یہ کہہ رہے تھے: ہائے میرا پیٹ، اور ان سے مروی ہے، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! کوئی ایسی شے ہے جس کی بیع حلال نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پانی کی بیع حلال نہیں۔\" اس میں ہے: جب رسول اللہ صلی اللہ علیہ وسلم سفر کرتے تو آپ صلی اللہ علیہ وسلم کی کوئی زوجہ اور سرمہ آپ کے ساتھ ہوتے۔ اس میں ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وضو ایک مد پانی سے ہے اور غسل ایک صاع پانی سے ہے، میرے بعد ایسے لوگ آئیں گے جو اسے کم سمجھیں گے، وہ میری سنت کے خلاف کریں گے، میری سنت کو لازم پکڑنے والا جنت میں میرے ساتھ ہوگا۔\"(1) عنبسہ بن عبد الرحمن متروک راوی ہے۔","",{"fn":"(1) جامع المسانید والسنن (۲۴۶/۱۶) اسد الغابہ (۴۵۱/۵)"}],[10651,"§۱۲۰۴۲ ۔ ام سعد بنت سعد\nبن ربیع انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ابو داؤد(1) نے بحوالہ ابو نعیم، ابن اسحاق کے طریق سے، انہوں نے داؤد بن حصین سے ان کی حدیث روایت کی ہے، فرماتے ہیں: میں ام سعد بنت سعد بن ربیع اور ان کے پوتے موسم بن سعد، وہ صدیق اکبر رضی اللہ عنہ کی پرورش میں یتیم تھیں میں نے ان کے سامنے پڑھا: ﴿وَالَّذِينَ عَقَدَتْ أَيْمَانُكُمْ﴾(2) انہوں نے کہا نہیں، بلکہ یہ ہے: ﴿وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ﴾ یہ آیت سیدنا ابو بکر اور عبد الرحمن بن ابی بکر کے بارے میں نازل ہوئی، جب (عبد الرحمن نے) اسلام لانے سے انکار کیا تو سیدنا ابو بکر رضی اللہ عنہ نے قسم کھائی کہ میں اسے وارث نہیں بناؤں گا۔ ابن سعد نے بحوالہ واقدی، انہوں نے ابن ابو زناد سے، انہوں نے ابراہیم بن یحییٰ بن زید بن ثابت سے، انہوں نے ام سعد بنت ربیع سے روایت کیا ہے، فرماتی ہیں: میرے پاس زید بن ثابت آئے اور کہا: اگر تم اپنے والد کی میراث کے بارے میں کچھ کہنا چاہتی ہو تو کہ لو، کیونکہ آج سیدنا عمر رضی اللہ عنہ نے پیٹ کے بچے کو وارث قرار دیا ہے۔ ان کے والد احد میں جب شہید ہوئے تھے تو یہ ماں کے پیٹ میں تھیں۔ ابن سعد کا قول ہے: ان کی والدہ خلادہ بنت انس بن سنان ہیں جو بن ساعدہ سے ہیں، سعد کے قتل کے ایک ماہ بعد ان کی ولادت ہوئی، ان سے زید بن ثابت نے نکاح کیا، جس سے خارجہ، سعد، عثمان، سلیمان اور ام زید کی ولادت ہوئی، خارجہ بن زید بن ثابت نے بحوالہ ام سعد بنت سعد بن ربیع، انہوں نے ابو بکر صدیق رضی اللہ عنہ سے سعد بن ربیع کے مناقب بیان کیے ہیں، ابن سعد نے خارجہ بن زید کے سوانح میں فرمایا، یہ ان کی والدہ ام سعد، جمیلہ بنت سعد بن ربیع ہیں، اسی طرح فرمایا، ام علاء میں ان کا ذکر آئے گا جو ان کے مخالف ہے۔","",{"fn":"(1) ابوداؤد، کتاب الفرائض باب نسخ میراث العقد بمیراث الرحم (۲۹۲۲)\n(2) سورۃ النساء الآیۃ (۳۳)"}],[10652,"§۱۲۰۴۳ ۔ ام أسعد\n(1)بعض کا قول ہے: ام سعید بنت عبد اللہ بن ابو مالک خزرجیہ، عبد اللہ اور جمیلہ کی بہن ہیں، ان کے والد عبد اللہ بن ابی بن سلول ہیں۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ان کی والدہ بنی بنت عبادہ بن نضلہ خزرجیہ ہیں، ان سے جبیر بن ثابت بن ضحاک بن ثعلبہ خزرجی نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۲۲/۲)\n(2) الطبقات الکبریٰ (۲۳۲/۸)"}],[10653,"§۱۲۰۴۴ ۔ ام سعد بنت عقبہ\n(1)بن رافع بن امرئ القیس بن یزید بن عبد الأشہل اشہلیہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ اور فرمایا: ان کی والدہ سلمیٰ بنت عمرو بن خنیس ساعدیہ ہیں، جو محمود بن لبید کی پھوپھی ہیں، ان کی بہن وردہ کے بعد ان سے قیس بن مخرمہ بن عبد المطلب قرشی نے نکاح کیا، جس سے اولاد ہوئی۔","",{"fn":"(1) تجرید (۳۲۲/۲)\n(2) الطبقات الکبریٰ (۲۸۴/۸)"}],[10654,"§۱۲۰۴۵ ۔ ام سعد بنت قیس\n(1)بن حصین بن خالدہ بن مخلد بن عامر بن زریق انصاریہ زرقیہ، ابن سعد(2) نے ان کا ذکر کیا ہے، اور فرمایا: ان کی والدہ خولہ بنت فاکہ بن قیس بن مخلد ہیں، ان سے قیس بن عمرو بن حصین بن خالدہ بن مخلد نے نکاح کیا اس کے بعد مسعود اکبر بن عبادہ بن سعد بن عثمان بن خالدہ بن مخلد نے نکاح کیا، ام سعد اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۳۲۲/۲)\n(2) الطبقات الکبریٰ (۲۸۴/۸)"}],[10655,"§۱۲۰۴۶ ۔ ام سعد\nبعض کا قول ہے: ام سعید، بن مرہ بن عمرو فہریہ، بعض نے کہا: جمحیہ، ابو عمر نے ان کا ذکر کیا ہے اور فرمایا: بنت عمرو۔ بعض نے کہا: عمیر جمحیہ۔ ان سے یتیم کی کفالت کرنے والے کے بارے میں حدیث مروی ہے، اس کی اسناد میں صفوان کے بارے میں اختلاف ہے۔\n\nمیں کہتا ہوں: رجال کے حصے میں حرف میم میں مرہ بن عمرو کے سوانح میں اختلاف کا بیان گزر چکا ہے۔ واللہ الحمد! جملہ اختلاف میں سے یہ بھی ہے جسے ابن مندہ نے محمد بن عمرو کے طریق سے بحوالہ صفوان، انہوں نے ام سعد بنت عمرو جمحیہ سے روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس نے اپنے کسی یتیم یا لوگوں میں سے کسی یتیم کی کفالت کی، میں اور وہ جنت میں ان دو انگلیوں کی طرح ہوں گے۔\"(1) حدیث کا مدار صفوان بن سلیم پر ہو تو میں اسے جائز قرار دوں کہ ام سعید بنت مرہ فہریہ، ام سعید بنت عمرو یا عمیر جمحیہ کے علاوہ ہیں، میں نے اسماء الرجال میں مرہ بن عمرو کے سوانح میں اس کی طرف اشارہ کر دیا ہے۔ ابن سکن، ام سعید بنت عمرو جمحیہ نے ان کا نام اسیرہ لیا ہے اور ابو اسامہ کے طریق سے بحوالہ محمد بن عمر، انہوں نے صفوان بن سلیم سے، انہوں نے ام سعید اسیرہ بنت عمرو جمحیہ سے ان کی حدیث روایت کی ہے۔ فرماتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا...... پھر اسے ذکر کیا، پھر فرمایا، بعض نے کہا: بحوالہ ام سعد بنت مرہ، انہوں نے اپنے والد سے روایت کیا ہے، اس میں بہت سا اختلاف ہے۔ مجھے یہ خدشہ ہے کہ انیسہ مذکورہ کو لفظی غلطی سے اسیرہ لکھا گیا، جیسا کہ مرہ بنت عمرو کے سوانح میں ہے۔ وباللہ التوفیق!","",{"fn":"(1) المعجم الکبیر (۲۵۵/۲۵) مجمع الزوائد (۱۶۳/۱) جامع المسانید والسنن (۲۵۰/۱۶) اسد الغابہ (۴۵۳/۵)"}],[10656,"§۱۲۰۴۷ ۔ ام سعد بنت مسعود\nبن سعد بن قیس بن خلدہ بن مخلد بن عامر بن زریق انصاریہ، زرقیہ، ابن سعد(1) نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرمایا: ان کی والدہ کبشہ بنت فاکہ بن قیس بن مجلل ہیں۔","",{"fn":"(1) الطبقات الکبریٰ (۲۸۶/۶)"}],[10657,"§۱۲۰۴۸ ۔ ام سعد بنت ثابت\nبن عتیک، ان کا نام کبشہ ہے، ان کا ذکر گزر چکا ہے۔"],[10658,"§۱۲۰۴۹ ۔ ام سعید بنت أبی جہل\nبن ہشام مخزومیہ۔ مسند عبد اللہ بن عمرو بن العاص میں ان کے قصے میں ان کا ذکر ہے، اور مسند احمد میں اور معجم کبیر طبرانی میں، یہ ہذیل کے ایک شخص کے طریق سے ہے۔ فرماتے ہیں: میں نے عبد اللہ بن عمرو کو دیکھا...... پھر قصہ ذکر کیا۔ انہوں نے ام سعید بنت ابو جہل کو کمان لٹکائے ہوئے دیکھا، وہ مردوں کی طرح چل رہی تھیں، پھر مردوں کی طرح مشابہت اختیار کرنے والی عورتوں کے بارے میں حدیث ذکر کی، ان کے رجال سوائے ہذلی کے ثقات ہیں، اس کا نام نہیں لیا گیا۔"],[10659,"§۱۲۰۵۰ ۔ ام سعید بنت سہل\nمعاذہ میں ان کا ذکر گزر چکا ہے۔"],[10660,"§۱۲۰۵۱ ۔ ام سعید بنت صخر\nبن حکیم بن امیہ بن حارثہ بن اوقص سلمیہ، مسیب بن حزن مخزومی کی زوجہ اور ان کی اولاد سعید، سائب اور عبد الرحمن کی والدہ ہیں، ان کے والد حالت کفر میں قتل ہوئے اور ان کے شوہر فتح کے دن اسلام لائے، اس سے ان کی اولاد ہوئی، یہ اس قسم میں سے ہیں، زبیر نے ان کا ذکر کیا ہے۔"],[10661,"§۱۲۰۵۲ ۔ ام سعید بنت عبد اللہ بن أبی\nام سعد میں ان کا ذکر گزر چکا ہے۔"],[10662,"§۱۲۰۵۳ ۔ ام سعید بنت مرہ\nام سعد میں ان کا ذکر گزر چکا ہے۔"],[10663,"§۱۲۰۵۴ ۔ ام سعید\nسعید بن زید بن عمرو بن نفیل کی والدہ ہیں، وہ لکھتے ہیں......(1) بیہقی کی سنن کبریٰ میں کتاب الجنائز کے باب الکافور...","",{"fn":"(1) بیاض فی الأصل"}],[10664,"§۱۲۰۵۵ ۔ ام سفیان بنت الضحاک\n(1)ابن مندہ کا قول ہے: صحابہ رضی اللہ عنہم میں ان کا تذکرہ ہے، اور یہ ثابت نہیں، حماد بن سلمہ نے بحوالہ یعلیٰ بن عطاء، انہوں نے موسیٰ بن عبد الرحمن سے ان کی حدیث ذکر کی ہے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے حدیث روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں صلوۃ کسوف پڑھائی تو عذاب قبر سے پناہ مانگی۔ میں کہتا ہوں: اسے عبد اللہ بن احمد نے مسند کی زیادات سے نقل کیا ہے، بحوالہ ہدبہ بن خالد، انہوں نے حماد سے روایت کیا ہے، اس کے الفاظ ہیں، بحوالہ موسیٰ بن عبد الرحمن، انہوں نے ام سفیان سے روایت کیا ہے کہ ایک یہودیہ سیدہ عائشہ رضی اللہ عنہا کے پاس آئی اور بات چیت کرتی تھی، جب وہ جانے لگی تو اس نے کہا: اللہ تمہیں عذاب قبر سے بچائے، جب رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو انہوں نے آپ صلی اللہ علیہ وسلم کو بتایا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس نے جھوٹ کہا، یہ اہل کتاب کے لیے ہے۔\" پھر کسوف شمس ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں عذاب قبر سے اللہ کی پناہ مانگتا ہوں۔\" (الحدیث) طبرانی(2) نے بحوالہ عبد اللہ بن احمد اور ابن ابی عاصم نے بحوالہ ہدبہ اسی طرح نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۶۳) تجرید (۳۲۲/۲)\n(2) المعجم الکبیر (۳۹۱/۲۵)"}],[10665,"§۱۲۰۵۶ ۔ ام سفیان بنت الضحاک السلمیہ\nمنصور بن صفیہ کی نانی ہیں، ابو موسیٰ نے ذیل میں فرمایا: جعفر مستغفری نے ان کا ذکر کیا ہے اور ان کی کوئی حدیث روایت نہیں کی، ابن اثیر نے اس پر اعتماد کیا ہے کہ یہ پہلے والی ہیں اس میں تردد ہے، اس سے فرق کا احتمال ہے۔"],[10666,"§۱۲۰۵۷ ۔ ام سلمہ بنت أبی أمیہ\n(1)بن مغیرہ بن عبد اللہ بن عمرو بن مخزوم قرشیہ مخزومیہ، ام المومنین، ان کا نام ہند ہے، ابو عمر کا قول ہے، بعض نے کہا کہ ان کا نام رملہ ہے۔ اس قول کی کوئی حیثیت نہیں، ان کے والد کا نام حذیفہ ہے۔ بعض کا قول ہے: سہیل۔ ان کا لقب زاد الراکب ہے۔ کیونکہ وہ نہایت سخی تھے، جب وہ سفر کرتے تو زاد راہ میں اپنے رفیقوں کی کفایت کرتے تھے۔ ان کی والدہ عاتکہ بنت عامر بن ربیعہ بن مالک کنانیہ ہیں، جو بنو فراس سے ہیں۔ اپنے چچا زاد ابو سلمہ بن عبد الاسد بن مغیرہ کی زوجہ ہیں جن کی وفات ہوگئی جیسا کہ ان کے سوانح میں گزر چکا ہے۔ پھر آپ صلی اللہ علیہ وسلم نے ۴ھ یا ۳ھ جمادی الثانیہ میں ان سے نکاح کر لیا۔ یہ اور ان کے خاوند بہت پہلے اسلام لا کر حبشہ کی طرف مہاجر ہوئے تھے۔ وہاں سلمہ پیدا ہوئے، پھر دونوں مکہ آئے اور مدینہ کی طرف ہجرت کی، جہاں عمر، درہ اور زینب پیدا ہوئیں، یہ ابن سعد کا قول ہے۔ جبکہ یونس بن بکیر وغیرہ کی بحوالہ ابن اسحاق روایت میں ہے کہ جب ابو سلمہ مدینہ جانے کا ارادہ کر چکے تو اپنا اونٹ تیار کیا، مجھے اس پر بٹھایا اور میرے ساتھ میرے بیٹے سلمہ کو سوار کر دیا اور اپنا اونٹ پکڑ کر چل دیئے۔ بنی مغیرہ کے لوگوں نے آپ کو دیکھا، آکر کہنے لگے: تم اپنی جان کو مصیبت میں ڈالتے ہو تو ڈالو۔ تمہارا کیا خیال ہے کہ ہم تمہاری بیوی کو ایسے ہی شہروں میں چلتا چھوڑ دیں گے؟ اور ان کے ہاتھ سے اونٹ کی مہار چھین لی اور مجھے لے لیا، جس پر بنو عبد الاسد نے ناراض ہو کر سلمہ کو اٹھا لیا اور کہنے لگے: ہم اپنا بیٹا اس کے پاس کیوں چھوڑیں جب تم نے اسے ہمارے شخص سے چھین لیا، اسی چھینا جھپٹی میں سلمہ کا بازو اتر گیا۔ بنو اسد اسے لے کر چل دیئے، ادھر بنو مغیرہ نے مجھے اپنے پاس روک لیا، خیر میرے خاوند ابو سلمہ مدینہ جا پہنچے، یوں مجھ میں، میرے خاوند میں اور میرے بیٹے میں جدائی پڑ گئی۔ میں روزانہ باہر نکل کر بطحاء میں بیٹھتی اور شام تک روتی رہتی۔ ہفتہ عشرہ اسی میں گزرا کہ میرے چچا زادوں میں سے کوئی شخص وہاں سے گزرا، اس نے میری حالت دیکھ کر بنو مغیرہ سے کہا: اس بے چاری کو کیوں نہیں جانے دیتے ہو؟ تم لوگوں نے اسے اس کے خاوند اور اس کے بیٹے سے جدا کر دیا ہے۔ وہ کہنے لگے: اگر چاہتی ہو تو اپنے خاوند کے پاس چلی جاؤ۔ ادھر بنو عبد الاسد کا غصہ ٹھنڈا ہوا تو انہوں نے میرا بیٹا بھی مجھے واپس کر دیا۔ میں نے اپنی سواری کا اونٹ لیا، بیٹے کو گود میں بٹھایا اور اپنے خاوند کے ارادے سے مدینے کی طرف چل نکلی۔ اللہ کی مخلوق میں سے میرے ساتھ کوئی نہ تھا، جو مجھے ملتا، میں کہتی میں پہنچ جاؤں گی یہاں تک کہ میں تنعیم میں پہنچی تو عثمان بن طلحہ، جو بنی عبد الدار کے فرد تھے، وہ مل گئے۔ کہنے لگے: ابو امیہ کی بیٹی! کہاں جا رہی ہو؟ میں نے کہا: اپنے خاوند کے ارادے سے جا رہی ہوں۔ پوچھا: ساتھ کوئی ہے؟ میں نے کہا: اللہ کی قسم! میرے اس بیٹے کے علاوہ کوئی نہیں، کہنے لگے: اللہ کی قسم! تمہیں ایسے نہیں چھوڑا جائے گا، اور پھر اونٹ کی مہار پکڑ کر آگے آگے چل دیئے۔ اللہ کی قسم! میں نے کسی عرب کو ان سے زیادہ شریف نہیں دیکھا، وہ جب کسی جگہ فروکش ہوتے، میرا اونٹ بٹھاتے اور کسی درخت کی اوٹ میں چلے جاتے۔ اس کے نیچے لیٹ جاتے۔ جب کوچ کا وقت ہوتا تو میرے اونٹ کو میرے سامنے لا بٹھاتے، سامان رکھتے اور پیچھے ہٹ جاتے، فرماتے: سوار ہو جاؤ، میں جب اچھے طریقے سے سوار ہو جاتی تو مہار پکڑتے اور چل دیتے، یہاں تک کہ کوئی پڑاؤ آ جاتا، اسی طرح وہ مجھے مدینہ لے آئے، جب انہیں بنی عمرو بن عوف کی بستی قباء میں نظر آئی تو کہنے لگے: تمہارا خاوند اسی بستی میں ہوگا۔ ابو سلمہ وہیں فروکش ہوئے تھے۔ بقول بعض: یہ پہلی خاتون ہیں جو حبشہ ہجرت کر کے نکلی تھیں، اور پہلی مسافر عورت ہیں جو مدینہ آئیں۔ ایک قول ہے کہ لیلیٰ زوجہ عامر بن ربیعہ اس فضیلت میں ان کی شریک ہیں۔ اسی طرح نسائی(2) کی صحیح سند سے بحوالہ ام سلمہ روایت ہے کہ جب ام سلمہ رضی اللہ عنہا کی عدت پوری ہوئی تو ابو بکر نے انہیں پیغام دیا لیکن انہوں نے کوئی جواب نہیں دیا۔ پھر نبی صلی اللہ علیہ وسلم نے پیغام بھیجا، تو انہوں نے کہلوا بھیجا میں غیرت مند عورت ہوں۔ صاحب اولاد ہوں، یہاں میرا کوئی والی وارث بھی نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس سے کہو، تمہاری یہ بات کہ میں غیرت مند ہوں تو میں اللہ سے دعا کروں گا تو اس طرح کی غیرت ختم ہو جائے گی۔ رہی یہ بات کہ میں بچوں والی ہوں تو تمہارے بچوں کی کفایت کر لی جائے گی اور یہ بات کہ تمہارا کوئی والی وارث نہیں، تو تمہارا کوئی والی وارث جو یہاں موجود ہے، اس بات کو نا پسند نہیں سمجھے گا تو انہوں نے اپنے بیٹے عمر سے کہا: جاؤ! رسول اللہ صلی اللہ علیہ وسلم سے نکاح کر دو، چنانچہ انہوں نے نکاح کر دیا۔\n\nنسائی ہی میں صحیح سند سے مروی ہے کہ ام سلمہ رضی اللہ عنہا جب مدینہ آئیں تو انہوں نے بتایا کہ وہ ابو امیہ بن مغیرہ کی بیٹی ہیں، تو وہ کہنے لگے، ملتے جلتے ناموں کی وجہ سے لوگ کتنا جھوٹ بولتے ہیں۔ پھر ان میں سے کچھ لوگ حج کے لیے جانے لگے تو ان سے کہا: کیا تم اپنے گھر والوں کی طرف کوئی خط بھیجنا چاہتی ہو، چنانچہ انہوں نے خط لکھ دیا، جب یہ لوگ واپس آئے تو ان کی تصدیق کرنے لگے یوں ان کی قدر و منزلت اور بھی بڑھ گئی، جب میرے ہاں زینب پیدا ہوئیں تو آپ صلی اللہ علیہ وسلم نے مجھے نکاح کا پیغام بھیجا، میں نے عرض کی مجھ جیسی عورت شادی نہیں کرتی، میرے ہاں اولاد ہونی نہیں ہے، کیونکہ میں بہت غیرت مند اور عیال دار عورت ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں تم سے بھی بڑا ہوں، جہاں تک غیرت کا تعلق ہے تو اللہ اسے ختم کر دے گا، رہے بچے تو یہ اللہ کے رسول صلی اللہ علیہ وسلم کے سپرد ہیں، جب شادی ہوگئی تو آپ تشریف لائے، فرمانے لگے: \"زینب کہاں ہے؟\" ایک دن عمار بن یاسر آئے تو انہیں ساتھ لے گئے۔ ام سلمہ رضی اللہ عنہا انہیں دودھ پلاتی تھیں، عمار کہنے لگے: یہ رسول اللہ صلی اللہ علیہ وسلم کی حاجت برآری میں رکاوٹ ڈالتی ہے۔ چنانچہ ایک دن آپ آئے، پوچھا: زینب کہاں ہے؟ تو اتفاق سے اس دن قریبہ بنت امیہ وہاں تھیں۔ کہنے لگیں: عمار اسے لے گئے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھا! میں رات کے وقت آؤں گا۔\" (الحدیث) دونوں روایتوں کو یوں جمع کیا جا سکتا ہے کہ سیدنا عمر رضی اللہ عنہ کی زبانی نبی صلی اللہ علیہ وسلم کا پیغام پہنچا، یہ بھی کہا جاتا ہے کہ نبی صلی اللہ علیہ وسلم سے ان کا نکاح کرانے والا سلمہ تھا، یہ بات ابن اسحاق نے نقل کی ہے اور سلمہ کے حالات میں بھی گزر چکی ہے۔ ابن سعد رحمہ اللہ کی ایسی سند سے بحوالہ عائشہ رضی اللہ عنہا روایت ہے، جس میں واقدی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے سیدہ ام سلمہ رضی اللہ عنہا سے شادی کی تو مجھے سخت صدمہ ہوا، کیونکہ ہمارے سامنے ان کے حسن و جمال کا تبصرہ ہوا تھا، تو میں چپکے سے انہیں دیکھنے لگی، اللہ کی قسم! جیسا مجھے بتایا گیا تھا، اس سے کہیں بڑھ کر پایا، میں نے حفصہ سے اس کا تذکرہ کیا، وہ کہنے لگیں: ایسی ہی ہے، جیسے لوگ کہتے ہیں۔ چنانچہ انہوں نے بھی دیکھا تو کہنے لگے: واقعی ایسی ہی ہے۔ جیسی تم نے دیکھی اور وہ خوبصورت ہیں۔ فرماتی ہیں: بعد میں میں نے دیکھا تو وہ ویسی ہی ثابت ہوئیں جیسا حفصہ نے کہا تھا، چونکہ میں غیرت کرتی اور ام سلمہ رضی اللہ عنہا بے حد خوبصورت اور بہت عقلمند، درست رائے والی تھیں۔ اور آپ صلی اللہ علیہ وسلم کو انہوں نے حدیبیہ کے روز جو مشورہ دیا تھا، اس سے بھی ان کی درست رائے اور زیادہ عقلمندی کا پتہ چلتا ہے۔ وہ نبی صلی اللہ علیہ وسلم، ابو سلمہ اور فاطمۃ الزہراء رضی اللہ عنہا سے روایت کرتی ہیں، ان سے روایت کرنے والے ان کا بیٹا عمر اور بیٹی زینب، بھائی عامر، بھتیجا مصعب بن عبد اللہ اور مکاتب نبھان، موالی میں سے عبد اللہ بن رافع، نافع، سفینہ، ان کا بیٹا ابو کثیر، خیرہ، حسن کی والدہ شامل ہیں، اور صحابہ رضی اللہ عنہم میں سے صفیہ بنت شیبہ، ہند بنت حارث فراسیہ، قبیصہ بن ذؤیب، عبد الرحمن بن حارث بن ہشام، اکابر تابعین میں سے ابو عثمان نہدی، ابو وائل، سعید بن مسیب، ابو سلمہ اور حمید، صاحبزادگان عبد الرحمن بن عوف، عروہ، ابو بکر بن عبد الرحمن اور سلیمان بن یسار شامل ہیں۔ امام واقدی رحمہ اللہ فرماتے ہیں: ۵۹ھ میں شوال میں فوت ہوئیں، ابو ہریرہ رضی اللہ عنہ نے جنازہ پڑھایا۔ ابن حبان فرماتے ہیں: ۶۱ھ کے اخیر میں فوت ہوئیں جب سیدنا حسین بن علی رضی اللہ عنہما کی شہادت کی اطلاع پہنچی۔ ابن ابی خیثمہ کا قول ہے: خلافت یزید بن معاویہ میں وفات پائی۔\n\nمیں کہتا ہوں: ان کی خلافت ۲۰ھ کے آخر میں تھی۔ ابو نعیم لکھتے ہیں: ۶۲ھ میں فوت ہوئیں اور امہات المومنین رضی اللہ عنہن میں سب سے آخر میں یہی فوت ہوئیں۔\n\nمیں کہتا ہوں: بلکہ ان میں سے سب سے آخر میں فوت ہونے والی ہیں۔ صحیح مسلم میں حارث بن عبد اللہ بن ابی ربیعہ اور عبد اللہ بن صفوان سے مروی ہے کہ وہ دونوں ام سلمہ رضی اللہ عنہا کے پاس خلافت یزید بن معاویہ میں آئے، دونوں نے زمین میں پھنس جانے والے لشکر کے بارے میں پوچھا، انہی ایام میں یزید بن معاویہ نے مسلم بن عقبہ کو شامی لشکر دے کر مدینہ روانہ کیا تھا اور واقعہ حرہ ۶۳ھ میں آیا۔ اس سب تفصیل سے واقدی کے قول کی تردید ہوتی ہے، اور اس کی قلعی بھی کھل جاتی ہے جو ابن عبد البر نے نقل کیا ہے کہ ام سلمہ رضی اللہ عنہا نے وصیت کر رکھی تھی کہ ان کا جنازہ سعید بن زید پڑھائیں، جبکہ ان کا انتقال ۵۰ھ یا ۵۱ھ یا ۵۲ھ میں ہو چکا تھا۔ جس سے یہ لازم آتا ہے کہ وہ اس سے پہلے وفات پا چکی تھیں۔ جب ایسا نہ ہونے پر اتفاق ہے تو اس کی تاویل یوں ممکن ہے کہ انہوں نے بیماری میں اس کی وصیت کی تھی، پھر جانبر ہو گئیں اور سعید ان سے پہلے فوت ہو گئے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۷۴۶۴) تجرید (۳۲۲/۲)\n(2) نسائی (۳۲۵۴)"}],[10667,"§۱۲۰۵۸ ۔ ام سلمہ بنت أبی حکیم\nام سلیمان کے سوانح میں ان کا ذکر آئے گا۔"],[10668,"§۱۲۰۵۹ ۔ ام سلمہ بنت رافع\nان کا نام سعاد ہے، ان کا ذکر گزر چکا ہے۔"],[10669,"§۱۲۰۶۰ ۔ ام سلمہ بنت محمیہ\n(1)بن جزء زبیدی، عدوی نے ذکر کیا ہے کہ یہ وہی ہیں جن سے ابو عامر فضل بن عباس نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۲۲/۲)"}],[10670,"§۱۲۰۶۱ ۔ ام سلمہ بنت مسعود\n(1)بن اوس بن مالک بن سواد بن ظفر۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرمایا: ان کی والدہ شموس بنت عمرو بن حرام نجاریہ ہیں، ان سے اوس بن مالک بن قیس بن محرث نے نکاح کیا، جس سے حارث پیدا ہوئے۔","",{"fn":"(1) تجرید (۳۲۲/۲)\n(2) الطبقات الکبریٰ (۲۴۸/۸)"}],[10671,"§۱۲۰۶۲ ۔ ام سلمہ بنت یزید\n(1)بن سکن، یہ اسماء ہیں جن کا ذکر گزر چکا ہے۔ ترمذی(2) نے بحوالہ عبد بن حمید اپنی سند سے ان کی حدیث روایت کی ہے، بحوالہ شہر بن حوشب، انہوں نے ام سلمہ انصاریہ سے روایت کی ہے، فرماتے ہیں، ایک خاتون نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! وہ کونسی نیکی ہے جس میں ہمیں آپ کی نافرمانی جائز نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نوحہ نہ کرو۔\" (الحدیث) عبد کا قول ہے، ام سلمہ اسماء بنت یزید ہیں۔","",{"fn":"(1) اسد الغابہ (۷۴۶۶) تجرید (۳۲۲/۲)\n(2) ترمذی (الحدیث: ۳۳۰۷)"}],[10672,"§۱۲۰۶۳ ۔ ام سلیط\n(1)ابو عمر کا قول ہے: بیعت کرنے والی صحابیات میں سے ہیں، احد کے دن نبی کریم صلی اللہ علیہ وسلم کے ساتھ حاضر تھیں، سیدنا عمر بن خطاب رضی اللہ عنہ نے فرمایا: یہ ان خواتین میں سے ہیں جو احد کے دن ہمارے لیے مشکیزہ بھر کر لاتی تھیں۔ میں کہتا ہوں: صحیح بخاری(2) میں بحوالہ عمر ان کا ذکر ثابت ہے، سیدنا عمر رضی اللہ عنہ نے ان کے بیٹے سلیط بن ابو سلیط بن ابو حارثہ پر ان کی کنیت رکھی، وہ ام قیس بنت عبید ہیں، ابن سعد(3) نے یہ ذکر کیا ہے جیسا کہ حرف قاف میں آئے گا، بعض کا قول ہے کہ انہوں نے ابو سلیط کے بعد مالک بن سنان سے نکاح کیا جو ابو سعید خدری رضی اللہ عنہ کے والد ہیں، ان سے ابو سعید پیدا ہوئے جو سلیط بن ابو سلیط کے ان کی والدہ کی طرف سے بھائی ہیں۔","",{"fn":"(1) اسد الغابہ (۷۴۶۹) الاستيعاب (۳۶۱۸) تجرید (۳۲۲/۲)\n(2) بخاری (۲۸۸۱)\n(3) الطبقات الکبریٰ (۳۰۶/۸)"}],[10673,"§۱۲۰۶۴ ۔ ام سلیم بنت حکیم\nام سلیمان میں ان کا ذکر آئے گا۔"],[10674,"§۱۲۰۶۵ ۔ ام سلیم بنت خالد\n(1)بن یعیش بن عمرو، بنو غنم بن مالک بن نجار سے ہیں، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرمایا: ان سے قیس بن محمد نے نکاح کیا، جس سے سلیم پیدا ہوئے۔","",{"fn":"(1) تجرید (۳۲۳/۲)\n(2) الطبقات الکبریٰ (۲۳۳/۸)"}],[10675,"§۱۲۰۶۶ ۔ ام سلیم بنت سحیم الغفاریہ\n(1)یہ امتہ یا امتہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۴۷۰) الاستيعاب (۳۶۱۹) تجرید (۳۲۲/۲)"}],[10676,"§۱۲۰۶۷ ۔ ام سلیم بنت عمرو\n(1)بن عباد، ابو یسر کعب بن عمرو سلمی کی بہن ہیں، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرمایا: ان سے نابی بن زید بن حرام نے نکاح کیا، ان کی والدہ نسیبہ بنت قیس بن اسود ہیں۔","",{"fn":"(1) تجرید (۳۲۳/۲)\n(2) الطبقات الکبریٰ (۲۹۷/۸)"}],[10677,"§۱۲۰۶۸ ۔ ام سلیم بنت قیس\n(1)بن عمرو بن عبید بن مالک بن عدی بن عامر بن غنم بن عدی بن نجار، ابن سعد(2) کا قول ہے، محمد بن عمر نے ذکر کیا کہ وہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۳۲۳/۲)\n(2) الطبقات الکبریٰ (۳۰۸/۸)"}],[10678,"§۱۲۰۶۹ ۔ ام سلیم بنت ملحان\nبن خالد بن زید بن حرام بن جندب انصاریہ، ان کے بھائی حرام بن ملحان کے سوانح میں ان کا نسب گزر چکا ہے۔ یہ ام انس ہیں جو رسول اللہ صلی اللہ علیہ وسلم کی خادمہ ہیں، اپنی کنیت سے مشہور ہیں۔\n\nان کے نام میں اختلاف ہے۔ بعض نے کہا: سہلہ، بعض کا قول ہے: رمیلہ، بعض کا کہنا ہے: رمیثہ، ایک قول ہے: ملیکہ، بعض نے کہا: غمیصاء یا رمیصاء، انہوں نے دور جاہلیت میں مالک بن نضر سے شادی کی تھی۔ جن سے جاہلیت میں ہی انس پیدا ہوئے۔ پھر یہ تو اسلام کی طرف پہل کرنے والے انصار کے ساتھ مسلمان ہو گئیں اور مالک ناراض ہو کے شام چلا گیا، جہاں اس کا انتقال ہوا، اس کے بعد انہوں نے ابو طلحہ سے شادی کر لی۔\n\nہم نے مسند احمد میں غیلانیات میں عالی سند سے بطریق عمار بن سلمہ، ثابت سے بحوالہ اسماعیل بن عبد اللہ بن ابی طلحہ، سیدنا انس بن مالک رضی اللہ عنہ کی روایت نقل کی ہے کہ ابو طلحہ نے اسلام لانے سے پہلے ام سلیم کا ہاتھ مانگا، انہوں نے فرمایا: ابو طلحہ! تم جانتے ہو، جس معبود کی تم عبادت کرتے ہو وہ اسی زمین کی پیداوار ہے؟ آپ نے کہا: ہاں! انہوں نے کہا: کیا ایک درخت پوجتے ہوئے تمہیں شرم نہیں آتی؟ اگر تم اسلام لے آؤ تو اس کے علاوہ میں تم سے کوئی مہر نہیں لوں گی۔ تو انہوں نے کہا: مجھے سوچنے کا موقع دو۔ اس وقت تو وہ چلے گئے بعد میں آ کر کہنے لگے: میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ آپ نے فرمایا: انس! ابو طلحہ سے شادی کرا دو۔ انہوں نے ان سے نکاح کرا دیا۔(1) اس حدیث کے متعدد طرق ہیں۔ ابن سعد(2) فرماتے ہیں: ہمیں خالد بن مخلد نے بحوالہ انس بن مالک فرمایا: ابو طلحہ نے ام سلیم کو نکاح کا پیغام دیا، وہ کہنے لگیں: میں اس شخص پر ایمان لائی ہوں، اور گواہی دی کہ وہ اللہ کے رسول ہیں، اگر تم میری پیروی کرو تو تم سے نکاح کرلوں گی۔ انہوں نے کہا: میں تمہارے مذہب پر ہوں۔ تو ان سے ام سلیم نے نکاح کیا، ان کا مہر اسلام تھا۔ اس حدیث میں ہے: ابو طلحہ نے ام سلیم کو نکاح کا پیغام دیا، ام سلیم فرماتی تھیں، میں انس کے بالغ ہونے اور مجلسوں میں بیٹھنے سے پہلے نکاح نہیں کروں گی۔ وہ کہتے تھے: \"اللہ تعالیٰ میرے بارے میں میری ماں کو اچھی جزا دے، کیونکہ انہوں نے ان کی اچھی پرورش کی تھی، ان سے ابو طلحہ نے فرمایا: انس اب محفلوں میں بیٹھنے اور بات چیت کرنے لگا ہے، تو انہوں نے ان سے نکاح کر لیا۔ مسلم بن ابراہیم نے بحوالہ انس بن مالک روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم ام سلیم کی زیارت کے لیے جاتے، تو وہ آپ کو وہ چیز تحفے میں پیش کرتیں جو آپ کے لیے بنائی ہوتی تھی۔ سیدنا انس رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم اپنی ازواج کے علاوہ ام سلیم کے گھر جاتے تھے، کسی نے پوچھا تو آپ نے فرمایا: \"مجھے ان پر ترس آتا ہے، ان کا بھائی اور والد میرے ساتھ شہید ہوئے\"۔ میں کہتا ہوں: آپ صلی اللہ علیہ وسلم کا ام حرام اور ان کی بہن کے گھر جانے کا جواب یہ ہے کہ ام حرام اور ان کی بہن ایک ہی حویلی میں رہتی تھیں، اور رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوے میں شرکت کرتی تھیں، ان کے قصے مشہور ہیں، ان میں سے وہ قصہ بھی ہے جسے ابن سعد رحمہ اللہ نے صحیح سند سے نقل کیا ہے کہ حنین کے دن ام سلیم نے ایک خنجر تیار کیا، ابو طلحہ کہنے لگے: اے رسول اللہ صلی اللہ علیہ وسلم! یہ ام سلیم ہیں۔ ان کے پاس خنجر ہے۔ انہوں نے کہا: میں نے یہ خنجر اس لیے بنایا ہے تا کہ اگر کوئی مشرک میرے پاس پھٹکا تو میں اس کے پیٹ میں گھونپ دوں گی۔\n\nان کا ایک واقعہ جو صحیح میں مذکور ہے، جب ان کا ابو طلحہ سے بیٹا فوت ہوا، فرماتی ہیں: جب ابو طلحہ آئے تو مجھ سے پہلے ابو طلحہ سے اس کا ذکر کوئی نہ کرے۔ چنانچہ جب وہ آگئے تو بچے کے بارے میں پوچھا، یہ کہنے لگیں: پہلے سے سکون ہے۔ ابو طلحہ سمجھے کہ وہ ٹھیک ہو گئے ہیں، چنانچہ وہ اٹھے، کھانا کھایا، پھر انہوں نے ان کے لیے زیب و زینت کر کے خوشبو لگائی، وہ ان کے ساتھ سو گئے، ان سے ہمبستری کی، جب صبح ہوئی تو ان سے کہنے لگیں: اپنے بچے کے بارے میں صبر سے کام لو۔ پھر انہوں نے نبی صلی اللہ علیہ وسلم سے اس کا تذکرہ کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ تم دونوں کو تمہاری اس رات میں برکت دے۔\" چنانچہ ان کے ہاں ایک بیٹا عبد اللہ بن ابو طلحہ پیدا ہوا جو بڑا نیک بخت ثابت ہوا، اسے اللہ تعالیٰ نے کئی اولادیں دیں، ان میں سے دس نے مکمل قرآن پڑھا تھا۔ اسی طرح صحیح میں ہے کہ جب نبی صلی اللہ علیہ وسلم آئے تو ام سلیم نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! یہ انس آپ کی خدمت کرے گا۔ اس وقت ان کی عمر دس سال تھی، چنانچہ نبی صلی اللہ علیہ وسلم کی مدینہ آمد سے لے کر انہوں نے نبی صلی اللہ علیہ وسلم کی خدمت کی اور خادم النبی صلی اللہ علیہ وسلم کے نام سے مشہور تھی۔ سیدہ ام سلیم نبی صلی اللہ علیہ وسلم سے کئی احادیث کی راویہ ہیں۔ ان سے ان کے بیٹے انس، ابن عباس، زید بن ثابت اور ابو سلمہ بن عبد الرحمن روایت کرتے ہیں۔ ابو عمر نے ابن مندہ کی کتاب سے ان کا نسب بعینہ نقل کیا ہے۔ البتہ اس میں یہ لکھا ہے کہ ان کی والدہ کا نام ملیکہ ہے۔ جبکہ ابن سکن کی کتاب میں ان کی والدہ کا نام انیقہ ہے۔ ابن فتحون نے اس سے متنبہ کیا ہے۔ ابو عمر نے یہ قول ابن سعد سے لیا ہے۔ انہوں نے اس بات کا اعتماد ظاہر کیا ہے کہ ان کی والدہ کا نام ملیکہ بنت مالک بن عدی بن زید بن مناة ہے۔","",{"fn":"(1) نسائی، کتاب النکاح باب التزویج علی الإسلام (۳۲۴۰) مصنف عبد الرزاق (۱۰۴۱۷)\n(2) الطبقات الکبریٰ (۳۱۱/۸)"}],[10679,"§۱۲۰۷۰ ۔ ام سلیمان بنت ابی حکیم\n(1)بعض کا قول ہے: سلیمان بن ابو خیثمہ کی والدہ ہیں، پہلے گزر چکا ہے کہ ان کا نام شفاء ہے۔ بعض کا قول ہے، وہ اس کے علاوہ ہیں، ابو عمر کا قول ہے: سلیمان کی والدہ ہیں، بعض کا قول ہے: ام سلیم عدویہ ہیں، بعض نے کہا: ام سلمہ ان سے عبد اللہ بن طیب یا طیب(2) نے روایت کیا کہ وہ فرماتی ہیں: انہوں نے ان خواتین کا زمانہ پایا جو نبی کریم صلی اللہ علیہ وسلم کے ساتھ فرض نماز پڑھتی تھیں۔ میں کہتا ہوں: ابن مندہ نے احمد بن یونس کے طریق سے بحوالہ ام سلیمان بنت ابی حکیم سے موصولاً نقل کیا ہے، پھر اسے ذکر کیا، لیکن اس کے آخر میں فرائض لفظ نہیں کہا۔ فرماتے ہیں: اسے محمد بن عبد الوہاب نے بحوالہ ابن شہاب روایت کیا ہے، فرماتے ہیں: بحوالہ ام سلمہ بنت حکیم۔ میں کہتا ہوں: محمد بن عبد الوہاب کی روایت کو طبرانی نے اوسط میں موصولاً بحوالہ موسیٰ بن ہارون، انہوں نے ان کے حوالے سے روایت کیا ہے، ذہبی رحمہ اللہ نے ابن یونس کی روایت پر اعتماد کیا ہے، انہوں نے قواعد کی تفسیر قواعد ابراہیم سے کی ہے، ایسا نہیں جو ان کا خیال ہے، بلکہ قواعد سے مراد گھروں میں رہنے والی عورتیں ہیں۔ ابو بکر بن ابو شیبہ نے بحوالہ احمد بن یونس اسی طرح روایت کیا ہے، جس میں یہ الفاظ ہیں: جو با جماعت فرض نمازیں نہیں پڑھتیں، ابن ابو لیلیٰ جو محمد ہیں، ان کی وجہ سے سند ضعیف ہے۔ اس کے شیخ عبد الکریم ہیں، جو ابن ابو مخارق ہیں۔ ابن مندہ نے اسی طرح ام سلیمان بن ابو خیثمہ کے سوانح میں ابو حسن بن حصین بن نمیر سے بحوالہ ابن ابی لیلیٰ اسی طرح روایت کیا ہے، فرماتے ہیں: عبد اللہ بن طیب پھر ان کا ذکر کیا، اسے ابو نعیم نے مسند حسن بن سفیان سے بحوالہ ابن ابی لیلیٰ اسی طرح روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۷۲)\n(2) طبرانی المعجم الکبیر (۳۱۵/۲۵) الآحاد والمثانی (۲۳۱۴/۶) مجمع الزوائد (۳۳/۲) (۳۴۱۲)"}],[10680,"§۱۲۰۷۱ ۔ ام سماک بنت ثابت\nان کا نام اذینہ ہے، ان کا ذکر گزر چکا ہے۔"],[10681,"§۱۲۰۷۲ ۔ ام سماک بنت سہل\nان کی والدہ امامہ بنت سماک کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[10682,"§۱۲۰۷۳ ۔ ام سماک بنت فضالہ\n(1)بن عدی انصاریہ جو انس بن فضالہ کی بہن ہیں۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان کی والدہ سودہ بنت سوید بن حرام بن ہیثم بن وہب ہیں۔","",{"fn":"(1) تجرید (۳۲۳/۲)\n(2) الطبقات الکبریٰ (۲۵۱/۸)"}],[10683,"§۱۲۰۷۴ ۔ ام سمرہ\n(1)اسماء الرجال میں سمیجہ کے سوانح میں ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۷۴) تجرید (۳۲۳/۲)"}],[10684,"§۱۲۰۷۵ ۔ ام سنان الاسلمیہ\n(1)مطین نے صحابہ میں ان کا ذکر کیا ہے، اور محمد بن عمر بن صالح کے طریق سے بحوالہ ثبیتہ بنت حنظلہ بحوالہ ان کی والدہ ام سنان اسلمیہ نقل کیا ہے کہ وہ بیعت کرنے والی صحابیات میں سے ہیں۔ فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہا: یا رسول اللہ صلی اللہ علیہ وسلم! میں آپ کے پاس حاجت لے کر آئی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم سوال نہ کرتی تو یہ تمہارے لیے بہتر تھا۔\" بقول ابو عمر: ام سنان اسلمیہ نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور بیعت علی الاسلام کی، آپ صلی اللہ علیہ وسلم نے میرے ہاتھ دیکھ کر فرمایا: \"تمہیں اپنے ناخن رنگین کرنے میں کوئی حرج نہیں۔\"(2) فرماتی ہیں: ہم عورتیں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ اور عیدین کی نماز میں شریک ہوتیں۔ ان سے ثبیتہ بنت حنظلہ روایت کرتی ہیں۔ میں کہتا ہوں: یہی روایت خطیب نے \"الموتلف\"(3) بحوالہ ثبیتہ اور ابن سعد نے بواسطہ واقدی، ثبیتہ بنت حنظلہ کی سند سے بحوالہ ان کی والدہ ام سنان نقل کی ہے۔ نیز یہی روایت صفیہ بنت حیی کے حالات میں بحوالہ ام سنان السلمیہ نقل کی، فرمایا: سیدہ صفیہ رضی اللہ عنہا کی شادی میں میں بھی موجود تھی۔ ہم نے انہیں کنگھی کی، عطر لگایا، وہ بہت بارونق خاتون تھیں، آپ صلی اللہ علیہ وسلم نے ان سے شب باشی کی تو ہم نے (اگلے روز) ان سے پوچھا: وہ کہنے لگیں آپ صلی اللہ علیہ وسلم کو مجھ سے خوشی ہوئی۔ اور اس رات آپ نہیں سوئے بلکہ ان سے باتیں کرتے رہے اور صبح ولیمہ کیا۔ واقدی کی روایت بواسطہ ثبیتہ بحوالہ ان کی والدہ مروی ہے جب رسول اللہ صلی اللہ علیہ وسلم نے خیبر کی طرف جانے کا ارادہ کیا، میں نے عرض کی: اللہ کی قسم! میں بھی آپ کے ساتھ جاؤں گی (جنگی ضروریات میں) مشکیزے سیوں گی اور زخمیوں کی مرہم پٹی کروں گی۔..... (حدیث) اسی میں ہے: تمہاری عمر کی کئی عورتوں کو میں نے اجازت دی ہے جن کا تعلق تمہاری اور دوسری قوم سے ہے، اور فرمایا: \"تم ام سلمہ کے ساتھ رہنا۔\"","",{"fn":"(1) اسد الغابہ (۷۴۷۵) الاستيعاب (۳۶۲۳) تجرید (۳۲۳/۲)\n(2) المعجم الکبیر (۴۲۴/۲۵) مجمع الزوائد (۹۳/۳) جامع المسانید والسنن (۴۲۸/۱۶)\n(3) اسد الغابہ (۴۵۸/۵) الطبقات الکبریٰ (۲۱۴/۸)"}],[10685,"§۱۲۰۷۶ ۔ ام سنان الانصاریہ\n(1)ابن مندہ نے انہیں اسلمیہ کے ساتھ ملا دیا ہے، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، اور حبیب معلم کے طریق سے بحوالہ ابن عباس روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم جب انصار کی ایک خاتون سے جنہیں ام سنان کہا جاتا ہے، ملے تو فرمایا: \"رمضان المبارک میں عمرہ کرنا ایک حج یا میرے ساتھ حج کے برابر ہے۔\"(2) ابن مندہ نے اسے صدیق بن عبد اللہ کے طریق سے بحوالہ ابن عباس روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انصار کی ایک خاتون سے فرمایا: تم ہمارے ساتھ حج کیوں نہیں کرتیں؟ (الحدیث) ابن جریج کا قول ہے: میں نے داؤد بن ابو عاصم سے سنا کہ وہ عطاء سے حدیث بیان کرتے ہیں، بحوالہ ابو بکر بن عبد الرحمن نے اس حدیث کے ساتھ ذکر کیا ہے اور خاتون کا نام ام سنان رکھا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۷۶) تجرید (۳۲۳/۲)\n(2) تجرید (۳۲۳/۲)"}],[10686,"§۱۲۰۷۷ ۔ ام سنبلہ الاسلمیہ\n(1)ابن مندہ کا قول ہے، ان سے سیدہ عائشہ رضی اللہ عنہا نے روایت کیا، ابن سکن کا قول ہے: ان کی حدیث اہل مدینہ سے مروی ہے۔ پھر ابو اویس کی روایت سے بحوالہ عبد الرحمن بن حرملہ، انہوں نے عبد اللہ بن نیار اسلمی سے انہوں نے عروہ سے روایت کیا کہ میں نے سیدہ عائشہ رضی اللہ عنہا سے فرماتے ہوئے سنا: ام سنبلہ اسلمیہ نے رسول اللہ صلی اللہ علیہ وسلم کو دودھ کا ہدیہ دیا، جب وہ آئیں تو آپ صلی اللہ علیہ وسلم موجود نہ تھے، میں نے ان سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے دیہاتیوں کے ہدیہ کو کھانے سے منع فرمایا ہے، اتنے میں رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر رضی اللہ عنہ آگئے، فرمایا: ام سنبلہ! یہ تمہارے پاس کیا ہے؟ عرض کی: دودھ ہے، آپ صلی اللہ علیہ وسلم کو ہدیہ دینے لائی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ام سنبلہ ڈال دو۔ آپ صلی اللہ علیہ وسلم نے نوش فرمایا، سیدہ عائشہ رضی اللہ عنہا کہنے لگیں: اللہ کے رسول صلی اللہ علیہ وسلم! آپ نے تو ہمیں دیہاتیوں کے کھانے سے منع کیا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: عائشہ! یہ اعرابی نہیں، بلکہ ہمارے باہر والے لوگ ہیں اور ہم ان کے شہر والے لوگ ہیں، جب یہ ہماری دعوت کریں گے تو ہم قبول کریں گے، یہ وہ (مشرک) اعرابی نہیں۔ ابن مندہ نے یہ روایت سلیمان بن بلال کے حوالے سے نقل کی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: برتن میں ڈال کر ابو بکر کو دے دو، پھر فرمایا: برتن میں ڈال کر عائشہ کو دے دو۔ پھر فرمایا: برتن میں ڈال کر مجھے دے دو۔ پھر آپ صلی اللہ علیہ وسلم نے نوش فرمایا۔ محمد بن اسحاق نے اس روایت کا مفہوم نقل کیا ہے، ابو نعیم نے ابن اسحاق کی روایت کو موصولاً نقل کیا ہے، جبکہ ابن سعد نے عبد اللہ بن جعفر بن عبد الرحمن بن حرملہ سے طویل نقل کیا ہے۔ اور امام احمد رحمہ اللہ نے فضل بن فضالہ بحوالہ عبد الرحمن بن حرملہ طویل نقل کی ہے۔ نسائی نے کتاب الکنی میں طبرانی اور ابو عروبہ نے عمرو بن قبیلی کے طریق سے ام سنبلہ کی حدیث نقل کی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ہدیہ لے کر آئیں تو آپ کی ازواج نے لینے سے انکار کر دیا۔ اتنے میں آپ آگئے، فرمایا: اس سے لے لو، کیونکہ ام سنبلہ ہمارے دیہات والی اور ہم اس کے شہر والے ہیں۔ طبرانی(2) نے یہ اضافہ نقل کیا ہے کہ آپ نے انہیں کسی علاقے کی پوری وادی بطور جاگیر دے دی تھی، جسے ان لوگوں سے عبد اللہ نے خرید کر اس کے بدلے اونٹ دے دیئے تھے۔ عمرو بن قیطی فرماتے ہیں کہ میں نے اس کا کچھ علاقہ دیکھا ہے۔ ابن مندہ نے اسی سند سے مختصر نقل کیا ہے، فرماتی ہیں کہ میں نبی صلی اللہ علیہ وسلم کے پاس دودھ کا ہدیہ لے کر آئی تو آپ صلی اللہ علیہ وسلم نے اسے قبول کر لیا۔","",{"fn":"(1) اسد الغابہ (۷۴۷۷) الاستيعاب (۳۶۲۴) تجرید (۳۲۳/۲)\n(2) المعجم الکبیر (۳۹۶/۲۵)"}],[10687,"§۱۲۰۷۸ ۔ ام سہل بنت ابی حثمہ\n(1)عبد اللہ بن ساعدہ، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ان کی بہن امیمہ بنت ابی حثمہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ وہ ان کی سگی بہن ہیں۔ ابن سعد کا قول ہے: ان سے یزید بن براء بن عازب بن حارث بن عدی بن بشم نے نکاح کیا جس سے مخلد پیدا ہوئے۔","",{"fn":"(1) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۲۴۱/۸)"}],[10688,"§۱۲۰۷۹ ۔ ام سہل بنت رومی\n(1)بن وقش۔ واقدی رحمہ اللہ نے ذکر کیا ہے کہ وہ اسلام لائیں اور بیعت کی۔ ابن سعد(2) نے یہی کہا ہے، فرماتے ہیں: یہ ام حنظلہ کی بہن ہیں، جن کا ذکر گزر چکا ہے۔ ام سہل، سلمان بن سلامہ کی زوجہ ہے، جس سے اولاد ہوئی۔","",{"fn":"(1) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۲۳۶/۸)"}],[10689,"§۱۲۰۸۰ ۔ ام سہل بنت سہل\n(1)بن عتیک، بعض کا قول ہے: ام ثابت بنت سہل بن عتیک بن نعمان بن عمرو بن مبذول بن مالک بن نجار۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرمایا: امیمہ بنت عقبہ بن عمرو ان کی والدہ ہیں، ان سے سنان بن حارث بن علقمہ نے، ان کے بعد عبد اللہ بن زید بن عاصم نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۲۳۱/۸)"}],[10690,"§۱۲۰۸۱ ۔ ام سہل بنت عمرو\n(1)بن قیس بن مالک بن عدی بن عامر بن غنم بن عدی بن نجار انصاریہ، ابن سعد(2) کا قول ہے: اسلام لائیں اور بیعت کی، ان کی والدہ امیمہ بنت اوس بن عجرہ ہے، ان سے محرز بن عامر بن عدی بن عامر بن غنم بن عدی بن نجار نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۳۰۸/۸)"}],[10691,"§۱۲۰۸۲ ۔ ام سہل بنت مسعود\n(1)بن سعد زرقیہ، ابن سعد(2) نے بھی ان کا ذکر کیا ہے اور فرمایا: ام ثابت اور ام سعد کی سگی بہن ہیں۔","",{"fn":"(1) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۲۸۶/۸)"}],[10692,"§۱۲۰۸۳ ۔ ام سہل بنت نعمان الانصاریہ\n(1)بنو ظفر سے ہیں، قتادہ بن نعمان کی بہن ہیں۔ ابن سعد(2) نے بھی ان کا ذکر کیا ہے، اور فرمایا: ان کی والدہ انیسہ بنت قیس بن عمرو نجاریہ ہیں، ام سہل اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۲۴۷/۸)"}],[10693,"§۱۲۰۸۴ ۔ ام سہلہ الانصاریہ\n(1)عاصم بن عدی انصاری کی زوجہ ہیں، ان سے سہلہ کی خیبر میں ولادت ہوئی۔ یہ واقدی کا قول ہے، ابن دباغ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۷۹) تجرید (۳۲۴/۲)"}],[10694,"§۱۲۰۸۵ ۔ ام سیف\nنبی کریم صلی اللہ علیہ وسلم کے صاحبزادے کو دودھ پلاتی تھیں، ابو سیف قین کی زوجہ ہیں، رجال کی کنیتوں میں ابو سیف کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[10695,"§۱۲۰۸۶ ۔ ام شباث\nثبات میں ان کا ذکر گزر چکا ہے، ام منبع میں ان کا ذکر آئے گا۔"],[10696,"§۱۲۰۸۷ ۔ ام شبیب زوجہ ضحاک\n(1)بن سفیان کلابی، ضحاک نے اپنی بہن کو نبی صلی اللہ علیہ وسلم پر پیش کیا تھا، جیسا کہ زہری نے ذکر کیا، بطریق حجاج بن ابو منیع، انہوں نے اپنی دادی کے حوالے سے، جنہوں نے ان سے روایت کیا کہ ضحاک بن سفیان نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا آپ کو ام شبیب کی بہن کے بارے میں رغبت ہے؟ ابن مندہ نے ان کا ذکر کیا ہے۔ ضحاک نبی صلی اللہ علیہ وسلم کے عامل تھے۔","",{"fn":"(1) اسد الغابہ (۷۴۸۲) تجرید (۳۲۴/۲)"}],[10697,"§۱۲۰۸۸ ۔ ام شرحبیل بنت فروہ\n(1)بن عمرو انصاریہ، بنو بیاضہ سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۸۳) تجرید (۳۲۴/۲)\n(2) المحبر (۴۲۶)"}],[10698,"§۱۲۰۸۹ ۔ ام الشرید\n(1)ابو داؤد(2) نے محمد بن عمر کے طریق سے بحوالہ شرید ان کی حدیث نقل کی ہے کہ ان کی والدہ نے انہیں وصیت کی تھی کہ ان کی طرف سے ایک مسلمان غلام آزاد کر دے اور میرے پاس ایک باندی نوبیہ تھی..... (الحدیث) نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"اسے آزاد کر دو، کیونکہ یہ مسلمان ہے۔\"","",{"fn":"(1) اسد الغابہ (۷۴۸۴) تجرید (۳۲۴/۲)\n(2) ابو داؤد (الحدیث: ۳۲۸۲)"}],[10699,"§۱۲۰۹۰ ۔ ام شریک بنت أنس\n(1)بن رافع بن امرئ القیس بن زید انصاریہ، بنو عبد الاشہل سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا شمار کیا(2) ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۸۵) تجرید (۳۲۴/۲)\n(2) اسد الغابہ (۴۶۰/۵)"}],[10700,"§۱۲۰۹۱ ۔ ام شریک بنت جابر الغفاریہ\n(1)ابو عمر کا قول ہے: احمد بن صالح نے ان ازواج نبی صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے جن کی رخصتی نہیں ہوئی۔ ابن اثیر(2) کا قول ہے: ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۸۶) الاستيعاب (۳۶۲۵) تجرید (۳۲۴/۲)\n(2) اسد الغابہ (۴۶۰/۵)"}],[10701,"§۱۲۰۹۲ ۔ ام شریک بنت خالد\n(1)بن تخنیس بن لوذان بن عبدود بن زید بن ثعلبہ بن خزرج بن ساعدہ انصاری خزرجیہ۔ ابن سعد(2) اور ابن حبیب کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن سعد کا قول ہے: ان کی والدہ ہند بنت وہب بن عمرو بن وقش ہیں، ام شریک نے انس بن رافع بن امرئ القیس بن زید بن عبد اشہل سے نکاح کیا، جس سے حارث بن انس پیدا ہوئے۔","",{"fn":"(1) اسد الغابہ (۷۴۸۷) تجرید (۳۲۴/۲)\n(2) الطبقات الکبریٰ (۲۷۱/۸)"}],[10702,"§۱۲۰۹۳ ۔ ام شریک الانصاریہ\nبعض کا قول ہے: یہ بنت انس ہیں، جن کا ذکر پہلے گزر چکا ہے۔ بعض نے کہا: بنت خالد ہیں، اس سے پہلے جن کا ذکر ہے، بعض کا قول ہے: یہ ان دونوں کے علاوہ کوئی اور ہیں، ایک قول یہ ہے: یہ ام شریک بنت ابو عسکر بن سمی ہیں، ابن ابو خیثمہ نے قتادہ کے طریق سے ان کا ذکر کیا ہے، فرمایا: نبی کریم صلی اللہ علیہ وسلم نے ام شریک انصاریہ نجاریہ سے نکاح کیا اور فرمایا: \"مجھے انصار میں نکاح کرنا پسند ہے۔\" پھر فرمایا: \"مجھے انصار کی غیرت پسند نہیں۔\" ان کی رخصتی نہیں ہوئی۔ میں کہتا ہوں: مسلم کی صحیح حدیث میں فاطمہ بنت قیس کی روایت میں ان کا ذکر ہے۔ جو تمیم داری سے جساسہ کے قصے کے بارے میں مروی ہے۔ اس میں ہے: ام شریک انصار میں سے ایک مالدار خاتون تھیں، اللہ عزوجل کے راستے میں بہت زیادہ خرچ کرتی تھیں، ان کے ہاں مہمان کثرت سے آتے تھے۔ ان کی ایک اور حدیث ہے، جسے ابن ماجہ نے شہر بن حوشب کے طریق سے نقل کیا ہے کہ مجھ سے ام شریک انصاریہ نے روایت کیا، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم نے ہمیں میت پر سورہ فاتحہ پڑھنے کا حکم دیا، بعض کا قول ہے: یہ وہی ہیں کہ فاطمہ بنت قیس کو حکم ملا تھا کہ وہ ان کے پاس عدت گزاریں، پھر ان سے کہا گیا: ابن ام مکتوم کے ہاں عدت گزاریں۔"],[10703,"§۱۲۰۹۴ ۔ ام شریک الدوسیہ\n(1)یونس بن بکیر نے سیرہ کی روایت میں بحوالہ ابو ہریرہ رضی اللہ عنہ ان کا ذکر کیا ہے، فرماتے ہیں: قبیلہ دوس کی ایک خاتون جنہیں ام شریک کہا جاتا تھا، رمضان میں اسلام لائیں، وہ اس تلاش میں تھیں کہ کوئی انہیں نبی کریم صلی اللہ علیہ وسلم کے پاس لے جائے۔ انہیں یہود میں سے ایک شخص ملا، اس نے کہا: اے ام شریک! تمہیں کیا ہوا؟ انہوں نے کہا: میں کسی شخص کو ڈھونڈ رہی ہوں جو مجھے نبی کریم صلی اللہ علیہ وسلم کے پاس لے جائے، اس نے کہا: آؤ! میں تمہارے ساتھ چلوں گا۔.....(2) پھر طویل حدیث ذکر کی۔ ابن سعد(3) نے اسے یحییٰ بن سعید انصاری کے طریق سے مرسل روایت کیا ہے۔ فرماتے ہیں: ام شریک نے ہجرت کی، راستے میں ایک یہودی مل گیا، شام تک وہ روزے سے تھیں۔ یہودی اپنی بیوی سے کہنے لگا، اگر تو نے اس عورت کو پانی پلا دیا تو میں ضرور کچھ کروں گا، تو وہ برابر انکار کرتی رہی یہاں تک کہ جب رات کا آخری پہر ہوا تو ان کے سینے پر ایک ڈول رکھا گیا اور ایک زنبیل پھر تاریکی میں ان لوگوں کو چلنا پڑا۔ یہودی اپنی بیوی سے کہنے لگا: مجھے تو اس عورت کے پانی پینے کی آواز آئی ہے۔ وہ کہنے لگی: نہیں! اللہ کی قسم! تم نے مجھے پانی پلایا ہوگا۔ بعد والی شخصیت میں ان کا دوسرا قصہ بیان ہوگا۔ واقدی رحمہ اللہ فرماتے ہیں: ہمارے ہاں قابل اعتماد بات یہ ہے کہ ہبہ کرنے والی خاتون دوس بن ازد کی تھی۔ جو خوبصورت تھی لیکن عمر رسیدہ تھی۔ اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا، ان کے الفاظ یہ ہیں: \"میں اپنے آپ کو آپ صلی اللہ علیہ وسلم کے لیے ہبہ کرتی ہوں اور اپنی جان کو آپ صلی اللہ علیہ وسلم کے لیے صدقہ کرتی ہوں\" جسے آپ صلی اللہ علیہ وسلم نے قبول کر لیا۔ سیدہ عائشہ رضی اللہ عنہا کہنے لگیں: اس عورت میں کیا بھلائی ہے جو اپنے آپ کو کسی مرد کے لیے ہبہ کر دے۔ وہ کہنے لگیں: میں ہوں۔ جس پر ان کے بارے میں یہ آیت اتری۔","",{"fn":"(1) اسد الغابہ (۷۴۸۸) تجرید (۳۲۴/۲)\n(2) السیر والمغازی (۲۸۴)\n(3) الطبقات الکبریٰ (۱۱۲/۸)"}],[10704,"§۱۲۰۹۵ ۔ ام شریک قرشیہ عامریہ\n(1)بنو عامر بن لوی سے ہیں، ابن کلبی رحمہ اللہ نے ان کا نسب بیان کیا ہے۔ فرمایا: بنت دودان بن عوف بن عمرو بن خالد بن ضباب بن حجیر بن معیص بن عامر، دوسرے راویوں کا قول ہے: عمرو بن عامر بن رواحہ بن حجیر، ابن سعد(2) کا قول ہے: ان کا نام غزیہ بنت جابر بن حکیم ہے، محمد بن عمر فرماتے تھے، وہ بنو معیص بن عامر بن لوی سے ہیں، دوسرے راویوں کا قول ہے: دوسیہ ہیں، قبیلہ ازد سے ہیں، پھر واقدی رحمہ اللہ سے مسنداً روایت کیا ہے، بحوالہ موسیٰ بن محمد بن ابراہیم تیمی، انہوں نے اپنے والد سے ذکر کیا ہے، فرماتے ہیں: ام شریک، بنو عامر بن لوی معیصیہ ہیں، انہوں نے اپنا نفس نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا تھا، نبی کریم صلی اللہ علیہ وسلم نے اسے قبول نہ کیا، انہوں نے وفات تک نکاح نہیں کیا۔ ابو عمر کا قول ہے: ابو بکر بن سمی بن حارث ازدی، دوسی کی زوجہ تھیں، جس سے شریک پیدا ہوئے، بعض کا قول ہے: ان کا نام غزیلہ ہے، بعض نے کہا: غزیہ ہے، ابن مندہ کا قول ہے: ان کے نام میں اختلاف ہے، بعض نے کہا: غزیلہ ہے۔ ابو عمر کا قول ہے، بعض نے کہا کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے نکاح کیا، فرماتے ہیں کہ مکہ میں نکاح کیا۔ یہ عجیب ہے کیونکہ اپنے نفس کو ہبہ کرنے کا قصہ مدینہ میں پیش آیا تھا، اور کئی طریق سے مروی ہے کہ یہ وہی ہیں جنہوں نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کیا تھا۔ ابو نعیم نے محمد بن مروان سدی کے طریق سے جو متروک راوی ہیں اور ابو موسیٰ سے بطریق ابراہیم بن یونس سے بحوالہ ابن عباس روایت کیا ہے، فرماتے ہیں: ام شریک کے دل میں جبکہ وہ مکہ میں تھیں اسلام گھر کر گیا، وہ قریشی خاتون تھیں، بنو عامر بن لوی میں سے تھیں، اور ابو بکر دوسی کی زوجہ تھیں، اسلام لائیں، اور چپکے چپکے قریش کی خواتین کو اسلام کی طرف دعوت دیتیں اور راغب کرتی تھیں، یہاں تک کہ اہل مکہ کو خبر ہوئی، انہوں نے انہیں پکڑ لیا، اور کہنے لگے: اگر تمہاری قوم نہ ہوتی تو ہم تمہارے ساتھ بہت برا سلوک کرتے۔ اب ہم تمہاری قوم کی طرف تمہیں لوٹا دیں گے۔ فرماتی ہیں: انہوں نے مجھے ایک اونٹ پر سوار کرایا جس پر بیٹھنے کی کوئی چیز نہ تھی، پھر مجھے تین دن تک کھانا پینا نہ دیا گیا۔ فرماتی ہیں، تین دن ایسے گزرے کہ میں نے زمین پر کوئی بات نہ سنی، پھر وہ ایک مقام پر اترے، جب وہ اترتے تو مجھے دھوپ میں باندھ دیتے اور خود سائے میں چلے جاتے۔ انہوں نے میرا کھانا پینا بند کر رکھا تھا، پھر وہ روانہ ہوئے۔ اسی اثناء میں مجھے کسی چیز کے آثار نظر آئے جیسے ٹھنڈک کی مجھ پر پڑ رہی ہو، پھر وہ بلند ہوگئی، پھر واپس لوٹی، میں نے اس کو پکڑا۔ وہ ایک ڈول تھا جس میں پانی تھا، میں نے اس میں سے تھوڑا سا پیا، پھر وہ غائب ہو گیا، پھر واپس آیا، میں نے اسے پکڑا، اور اس میں سے تھوڑا سا پیا، پھر وہ بلند ہوا۔ پھر اسی طرح لوٹ آیا، پھر بلند ہوا۔ اس طرح کئی مرتبہ ہوا یہاں تک کہ میں سیراب ہوگئی۔ پھر میں نے باقی پانی اپنے جسم اور کپڑوں پر ڈالا۔ جب وہ بیدار ہوئے تو انہیں پانی کے آثار نظر آئے اور مجھے اچھی صورت میں دیکھا۔ انہوں نے مجھ سے کہا: تم کھل گئی تھی؟ تم نے ہمارا پانی پی لیا اور اس میں سے پیا ہے؟ میں نے کہا: نہیں، اللہ کی قسم! میں نے ایسا نہیں کیا، بلکہ ایسا ایسا واقعہ پیش آیا ہے۔ انہوں نے کہا: اگر تم سچی ہو تو تمہارا دین ہمارے دین سے بہتر ہے، پھر انہوں نے مشکیزوں کو دیکھا، وہ اسی طرح تھے جیسے انہوں نے رکھے تھے۔ بعد میں وہ اسلام لے آئے۔ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور اپنا نفس آپ صلی اللہ علیہ وسلم کے لیے بغیر مہر ہبہ کر دیا۔ آپ صلی اللہ علیہ وسلم نے انہیں قبول فرما لیا، اور رخصتی ہوئی۔ جب آپ صلی اللہ علیہ وسلم نے انہیں بڑی عمر والی پایا تو انہیں طلاق دے دی۔ یہ قصہ بحوالہ ام شریک دوسرے الفاظ میں کسی اور طریق سے خواتین کی کنیتوں میں بنت ابو مکر کے سوانح میں گزر چکا ہے، اس کی سند مرسل ہے۔ اس میں واقدی بھی ہیں۔ ذیل میں ابو موسیٰ نے یہودی کے ساتھ مدینے جانے کا دوسرا قصہ نقل کیا ہے اور اسی طرح ڈول سے پانی پینے کا واقعہ نقل کیا ہے۔ ابو موسیٰ نے بھی دوسرے طریق سے بحوالہ ابن عباس نقل کیا ہے، جو مرسل روایت میں مذکور اس قصے جیسا ہے، اس کا حاصل یہ ہے کہ انہوں نے کلبی سے آگے قصے کے سیاق میں اختلاف کیا ہے۔ جس کا حاصل یہ ہے کہ اگر یہ روایت محفوظ ہے تو ڈول کا قصہ ام شریک کو تین مرتبہ پیش آیا۔ ابن اثیر کا قول ہے: ابو نعیم نے اس قصے سے استدلال کیا ہے کہ عامریہ، دوسیہ ہیں۔ میں کہتا ہوں: اس سے یہ لازم آتا ہے کہ بنو عامر کی طرف ان کی نسبت مجازی ہو، اس کے برعکس کا احتمال بھی ہے کہ قریشیہ، عامریہ نے قبیلہ دوس میں نکاح کیا ہو، اور ان کی طرف منسوب ہوگئی ہوں۔ حمیدی نے اپنی مسند میں مجالد کی روایت سے بحوالہ فاطمہ بنت قیس نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: ام شریک بنت ابو مکر کے ہاں عدت گزارو، یہ اس کے خلاف ہے جو گزر چکا ہے کہ وہ ابو بکر کی زوجہ ہیں، جمع کرنا ممکن ہے۔ ہوسکتا ہے کہ یہ ان کے والد اور شوہر کی کنیت ہو، دونوں جمع ہوگئی ہوں یا بنت، بیت سے بدل گیا ہو، بیوی کو گھر والی کہا جاتا ہے۔ لہذا دونوں روایتوں میں اتفاق ہے۔ میں نے ابو مکر کے سوانح میں ابو عمر کا قول ذکر کیا ہے کہ ابو مکر ان کا بیٹا ہے۔ ام شریک کے حوالے سے تین احادیث مسنداً روایت کی گئی ہیں، کچھ میں ان کا نسب بیان نہیں کیا گیا۔ اور بعض میں ان کی پہلی نسبت کی روایت اختلاف کے ساتھ نسب بیان کیا گیا ہے۔ اسے مسلم نے فتن میں اور ترمذی نے مناقب میں زبیر کی روایت سے بحوالہ ام شریک روایت کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دجال کی وجہ سے لوگ متفرق ہوں گے۔\" ام شریک کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! اس وقت عرب کہاں ہوں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ تھوڑے ہوں گے۔\"(3) ابن ماجہ(4) نے حدیث ابو امامہ میں نبی کریم صلی اللہ علیہ وسلم سے رجال کے ذکر میں نقل کیا ہے، فرماتے ہیں: \"مدینہ کی زمین تین مرتبہ ہلائی جائے گی (یعنی تین مرتبہ زلزلہ آئے گا) اس میں کوئی منافق مرد یا عورت نہ رہے گی بلکہ اس میں سے نکل جائیں گے، اس دن کو یوم کلام کہا جائے گا۔\" ام شریک بنت ابو مکر کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! اس وقت عرب کہاں ہوں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس وقت وہ تھوڑے ہوں گے۔\"(5) اسے طویل حدیث میں ذکر کیا۔ حمیدی وغیرہ نے جو نقل کیا یہ اس کے موافق ہے، بطریق مجالد بحوالہ فاطمہ بنت قیس کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"ام شریک بنت ابو مکر کے ہاں عدت گزارو۔\" اگر یہ روایت محفوظ ہے تو اس سے معلوم ہوتا ہے کہ یہ انصاریہ ہیں جن کا ذکر پہلے گزر چکا ہے، گویا ان کی نسبت مجازی ہے۔ دوسری بات: اسے شیخین نے سعید بن مسیب کی روایت سے بحوالہ ام شریک روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں اوزاغ کے قتل کا حکم دیا، اس روایت میں ان کا نسب بیان نہیں کیا گیا، ابو عوانہ سے بحوالہ سماک کی روایت میں ان کا نسب بیان کیا گیا ہے۔ تیسری بات: اس روایت کو نسائی نے ہشام بن عروہ کی روایت سے بحوالہ ام شریک نقل کیا ہے کہ یہ ان خواتین میں سے تھیں جنہوں نے اپنے نفس نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیئے، اس کے رجال ثقہ ہیں، ان کا نسب بیان نہیں کیا گیا، اسے ابن سعد رحمہ اللہ نے بحوالہ شعبی روایت کیا ہے۔ وہ خاتون جسے رسول اللہ صلی اللہ علیہ وسلم نے چھوڑ دیا تھا، ام شریک انصاریہ ہیں، یہ مرسل روایت ہے، اس کے رجال ثقہ ہیں۔ شریک قاضی اور شعبہ کے طریق سے، شریک بحوالہ علی بن حسین فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ام شریک دوسیہ سے نکاح کیا، لفظ شریک ہے۔ فرماتے ہیں: شعبہ نے اپنی روایت میں فرمایا: وہ خاتون جنہوں نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا تھا، ام شریک ازد کی خاتون ہیں، ابن سعد نے عکرمہ کے طریق سے اور عبد الواحد بن ابو عون کے طریق سے نقل کیا ہے، اس آیت کے بارے میں مومن عورت اگر اپنا نفس نبی صلی اللہ علیہ وسلم کو ہبہ کردے فرماتے ہیں: یہ ام شریک ہیں، اور ان کی سند میں واقدی ہیں، اور ان کا نسب بیان نہیں کیا گیا۔ ان تمام روایتوں کو جمع کرنے سے معلوم ہوتا ہے کہ ام شریک ایک ہیں، ان کی نسبت میں اختلاف ہے کہ انصاریہ ہیں یا قریش میں سے عامریہ ہیں یا قبیلہ دوس سے ازدیہ ہیں۔ ان تینوں انساب کا اجتماع ممکن ہے۔ وہ ان تینوں کی طرف منسوب ہیں۔ پھر انہوں نے انصار میں نکاح کیا، اور ان کی طرف منسوب ہوئیں، یا ان میں نکاح نہیں کیا، بالمعنی الاعم انصار کی طرف منسوب ہوئیں۔","",{"fn":"(1) الاستيعاب (۳۶۲۶)\n(2) الطبقات الکبریٰ (۱۱۰/۸)\n(3) مسلم (۷۳۱۶)\n(4) ابن ماجہ (۴۰۷۷)\n(5) مسند احمد (۴۶۲/۶)"}],[10705,"§۱۲۰۹۶ ۔ ام شہاب الغنویہ\nابن سعد نے مؤتلف میں ان کا ذکر کیا ہے۔ اعرابی کے ترجمہ میں اختلاف ہے، ان کا نام عبد اللہ بن احمد ہے۔ اور ان کی طرف سند چلائی ہے، فرماتے ہیں: ہم سے ماویہ بنت ماجد نے حدیث بیان کی، وہ فرماتے ہیں کہ مجھ سے میری مولاۃ ام شہاب غنویہ نے حدیث بیان کی، میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئی، آپ صلی اللہ علیہ وسلم نے مجھے ایک وسق جو اور کپڑا پہننے کے لیے دیا۔ رشاطی نے ان کا ذکر کیا ہے، اور فرمایا: ابو عمر اور ابن فتحون نے ان کا ذکر نہیں کیا۔"],[10706,"§۱۲۰۹۷ ۔ ام شیبہ الأزدیہ\n(1)ابو عمر کا قول ہے، مکیہ ہیں۔ ان سے عبد الملک بن عمیر نے مجالس کے ادب کے بارے میں حدیث روایت کی، وہ حسن حدیث ہے۔ ابن مندہ(2) کا قول ہے: حماد بن سلمہ کی حدیث میں بحوالہ عبد الملک بن عمیر ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۰) الاستيعاب (۳۶۲۷) تجرید (۳۲۵/۲)\n(2) اسد الغابہ (۴۶۲/۵)"}],[10707,"§۱۲۰۹۸ ۔ ام شدرہ بنت صعصعہ\nبن ناجیہ بن محمد بن سفیان بن مجاشع، غالب بن صعصعہ جو مشہور شاعر ہیں، ان کی بہن ہیں۔ یہ زبرقان بن بدر تمیمی صحابی کی والدہ ہیں۔ انہوں نے نبوت کا زمانہ پایا، حطیئہ شاعر کے ساتھ ان کا قصہ مشہور ہے۔ یہ سیدنا ابو بکر رضی اللہ عنہ کی خلافت کے آخر یا سیدنا عمر رضی اللہ عنہ کی خلافت کے شروع کا قصہ ہے، میں نے عطیہ کے سوانح میں اس کی طرف اشارہ کر دیا ہے۔"],[10708,"§۱۲۰۹۹ ۔ ام شرحبیل\nذی الکلاع کی زوجہ ہیں، تاریخ دمشق میں ان کے شوہر کے سوانح میں ان کا ذکر ہے جو اس پر دلالت کرتا ہے کہ انہیں ادراک حاصل ہے۔"],[10709,"§۱۲۱۰۰ ۔ ام شباث\nیہ ام منبع ہیں۔ ان کے بیٹے شباث کے سوانح میں ان کا ذکر ہے۔ ابو موسیٰ نے ان کا ذکر کیا ہے کہ انہیں استدراک حاصل نہیں، کیونکہ اگر چہ شباث کی والدہ ہیں، لیکن ان کی کنیت کوئی اور مشہور ہے۔ اگر ہر خاتون کی کنیت ہر بچے پر ہوتی تو سیدہ ام المؤمنین ام سلمہ کی کنیت ام عمر، ام زینب، ام ذرہ ہوتی۔ اس سے تو یہ لازم تھا کہ تمام جگہوں میں استدراک میں ان کا ذکر کیا گیا ہے۔ جبکہ ایسا نہیں، کنیتوں میں ان کا ذکر ہوتا ہے، چاہے کنیت مرد پر رکھی جائے یا عورت پر۔"],[10710,"§۱۲۱۰۱ ۔ ام صبیح\nان کا نام عنبہ تھا۔(1) عنقودہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۲)"}],[10711,"§۱۲۱۰۲ ۔ ام صبیہ الجہنیہ\n(1)ابو عمر کا قول ہے، ان کی حدیث اہل مدینہ کے ہاں ہے، یہ خارجہ بن حارث بن رافع بن مکیث کی دادی ہیں، ان سے ابو نعمان سالم بن سرج نے روایت کی جو ابن خربوذ ہیں، اور ان کے بھائی نافع نے ان سے روایت کی، یہ بخاری رحمہ اللہ کی کتاب الادب المفرد، سنن ابو داؤد، ابن ماجہ میں ہے۔ احمد، ابن ابی شیبہ وغیرہ(2) نے ان کی حدیث نقل کی ہے۔ وہ یہ ہے کہ وہ فرماتی ہیں: میں اور رسول اللہ صلی اللہ علیہ وسلم ایک ہی برتن سے وضو فرماتے تھے، ابن مندہ کی کتاب معرفتہ میں یہ حدیث ہمیں عالی سند سے ملی ہے۔ ابن سعد(3) وغیرہ نے بحوالہ خولہ بنت قیس اصبیہ اسے روایت کیا ہے۔ خولہ بنت قیس میں ان کا ذکر گزر چکا ہے، جن کے سوانح پہلے گزر چکے ہیں۔","",{"fn":"(1) الاستيعاب (۳۶۲۸)\n(2) مسند احمد (۳۶۷/۶)\n(3) الطبقات (۲۱۶/۸)"}],[10712,"§۱۲۱۰۳ ۔ ام صخر بنت شریک\nبن انس بن رافع بن امرئ القیس، ان کی والدہ امامہ بنت سماک میں ان کا ذکر گزر چکا ہے۔"],[10713,"§۱۲۱۰۴ ۔ ام الصہباء\nذہبی رحمہ اللہ نے تجرید میں ذکر کیا ہے کہ مسند بقی بن مخلد میں ان کی ایک حدیث ہے۔"],[10714,"§۱۲۱۰۵ ۔ ام صہیب\nمسند ابن ابو عمر میں ان کا ذکر ہے۔ مسند عمر اور عائشہ میں بھی دیکھ لیا جائے۔"],[10715,"§۱۲۱۰۶ ۔ ام صابر بنت نعیم\n(1)بن مسعود اشجعی، ابن مندہ کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، انہوں نے بحوالہ اپنے والد روایت کی ہے۔ ابراہیم بن صابر نے اپنے والد کے حوالے سے، انہوں نے ان سے حدیث روایت کی ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۴۹۱) تجرید (۳۲۵/۲)\n(2) اسد الغابہ (۴۶۳/۵)"}],[10716,"§۱۲۱۰۷ ۔ ام الضحاک بنت مسعود الانصاریہ\n(1)حارثیہ، ابو عمر کا قول ہے، واقدی نے بحوالہ محمد بن عبد الرحمن مدنی، انہوں نے بحوالہ ام ضحاک روایت کیا ہے کہ وہ خیبر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حاضر ہوئیں، آپ صلی اللہ علیہ وسلم نے انہیں ایک مرد جتنا حصہ دیا۔ میں کہتا ہوں: ابن سعد(2) نے طبقات میں بحوالہ واقدی روایت کیا ہے کہ وہ اسلام لائیں، بیعت کی اور بدر میں حاضر ہوئیں، ابن سعد کا قول ہے، انصار کے نسب میں مجھے ان کا ذکر نہیں ملا۔ میں کہتا ہوں: عمر بن شبہ نے ذکر کیا ہے کہ وہ حویصہ اور محیصہ کی بہن ہیں، میں نے کتاب اخبار مدینہ میں ان کی سند سے بحوالہ یزید بن عیاض بن جعدہ جو ضعیف راوی ہیں، پڑھا ہے کہ انہیں خیبر کا حال معلوم ہوا، پھر قصہ ذکر کیا۔ اس میں ہے کہ آپ صلی اللہ علیہ وسلم نے دو خواتین کو جو لڑائی میں حاضر تھیں حصہ دیا، وہ ام ضحاک بنت مسعود حویصہ اور محیصہ کی بہن اور حذیفہ بن یمان کی بہن تھیں، آپ صلی اللہ علیہ وسلم نے ان دونوں کو مرد کے حصہ کے برابر دیا۔ ابن ابو عاصم(3) نے وحدان میں عبد الرحمن امامی کے طریق سے بحوالہ ام ضحاک بنت مسعود حارثیہ روایت کیا ہے۔ فرماتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی پڑوسن اپنی پڑوسن کے ہدیے کو حقیر نہ جانے، اگر چہ وہ بکری کا کھُر ہی کیوں نہ ہو۔\"","",{"fn":"(1) اسد الغابہ (۷۴۹۴) الاستيعاب (۳۶۲۹) تجرید (۳۲۵/۲)\n(2) الطبقات الکبریٰ (۲۴۶/۸)\n(3) الآحاد والمثانی (۲۴۷۶/۶)"}],[10717,"§۱۲۱۰۸ ۔ ام ظہیرہ\n(1)رجال کے تحت حرف ضاد میں ضمیرہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۵) تجرید (۳۲۵/۲)"}],[10718,"§۱۲۱۰۹ ۔ ام طارق\n(1)سعد بن عبادہ انصاری جو خزرج کے سردار ہیں، کی مولاۃ ہیں۔ ان کی حدیث احمد رحمہ اللہ، ابن سعد رحمہ اللہ، ابو بکر بن ابو شیبہ رحمہ اللہ، حسن بن سفیان رحمہ اللہ، ابن ابو عاصم،(2) حسن مروزی نے باب البر والصلۃ کے زیادات میں اعمش کے طریق سے بحوالہ ام طارق مولاۃ سعد نقل کی ہے۔ فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم ہمارے ہاں تشریف لائے اور کئی مرتبہ اجازت طلب کی، ہم نے آپ صلی اللہ علیہ وسلم کے سلام کا جواب نہ دیا، آپ صلی اللہ علیہ وسلم واپس تشریف لے گئے، ایک روایت میں ہے، سیدنا سعد رضی اللہ عنہ تین مرتبہ خاموش رہے، نبی کریم صلی اللہ علیہ وسلم واپس تشریف لے گئے تو سیدنا سعد رضی اللہ عنہ نے مجھے ان کی طرف بھیجا کہ ہم نے آپ کے سلام کا جواب اس لیے نہیں دیا تھا تا کہ آپ زیادہ سے زیادہ ہم پر سلام بھیجیں۔ اس کے الفاظ یہ ہیں، سیدنا سعد رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ اور آپ کو سلام کہو، اور بتاؤ کہ ہم نے سلام کا جواب اس امید کی وجہ سے نہیں دیا تھا کہ آپ صلی اللہ علیہ وسلم ہمیں مزید سلام کہیں گے۔ فرماتی ہیں: جب میں آپ صلی اللہ علیہ وسلم کے پاس گئی اور اجازت طلب کی تو آپ صلی اللہ علیہ وسلم نے پوچھا: \"کون ہے؟\" فرماتی ہیں: میں ام ملدم ہوں۔ (الحدیث) جو تیز سے تیز تر ہے۔ اسے ابن ابو الدنیا نے مرض اور کفارات میں اس طریق سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۶) الاستيعاب (۳۶۳۰) تجرید (۳۲۵/۲)\n(2) الطبقات الکبریٰ (۲۲۲/۸)"}],[10719,"§۱۲۱۱۰ ۔ ام طارق\n(1)ابو موسیٰ نے ان کا ذکر بحوالہ مستغفری کیا ہے، اور ان کی سند کو ابن اسحاق(2) تک لے گئے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے خیبر سے چالیس وسق انہیں دیئے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۷) تجرید (۳۲۵/۲)\n(2) السیرۃ النبویۃ (۲۷۲/۳)"}],[10720,"§۱۲۱۱۱ ۔ ام طالب بنت ابو طالب\n(1)بن عبد المطلب بن ہاشم ہاشمیہ علی اور ان کے بہن بھائیوں کی بہن ہیں، بعض کا قول ہے: ان کا نام ریطہ ہے۔ ابن سعد(2) کا قول ہے: واقدی نے ان لوگوں میں ان کا ذکر کیا ہے جنہیں رسول اللہ صلی اللہ علیہ وسلم نے خیبر سے چالیس وسق کھانے کو دیئے۔ فرماتے ہیں: ہشام بن کلبی نے کتاب النسب میں طالب بن ابو طالب کی اولاد میں ام طالب کا ذکر نہیں کیا، بلکہ ریطہ کا ذکر کیا ہے، شاید وہ ام طالب ہوں۔","",{"fn":"(1) تجرید (۳۲۶/۲)\n(2) طبقات (۲۲/۸)"}],[10721,"§۱۲۱۱۲ ۔ ام طفیل زوجہ ابی بن کعب\n(1)سید القراء ہیں۔ احمد، طبرانی، حسن بن سفیان نے بسر بن سعید کے طریق سے بحوالہ ابی بن کعب روایت کی ہے، فرماتے ہیں: مجھ سے عمر نے اس عورت کے بارے میں بحث کی جس کا خاوند فوت ہو گیا ہو جبکہ وہ حاملہ ہو، میں نے کہا: جب وضع حمل ہو جائے تو نکاح کرے۔ کہنے لگے: ام طفیل جو میرے بیٹوں کی والدہ ہیں، رسول اللہ صلی اللہ علیہ وسلم نے سبیعہ اسلمیہ کو وضع حمل کے بعد نکاح کا حکم دیا تھا، اس کی سند میں ابن لہیعہ ہیں اور نقل کیا ہے۔.....(2) ابو عمر کا قول ہے: ان سے محمد بن ابی بن کعب اور عمارہ بن عمرو بن حزم نے روایت کی۔ میں کہتا ہوں: عمارہ کی روایت کو دار قطنی نے مروان بن عثمان سے ان کے حوالے سے بحوالہ ام طفیل زوجہ ابی بن کعب روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"میں نے خواب میں اپنی والدہ کو دیکھا۔\" (الحدیث) مروان متروک ہے، ابن معین کا قول ہے: مروان کون ہے کہ اس کی تصدیق کی جائے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۸) الاستيعاب (۳۶۳۱) تجرید (۳۲۶/۲)\n(2) مسند احمد (۳۷۵/۶)"}],[10722,"§۱۲۱۱۳ ۔ ام طلیق زوجہ ابو طلیق\n(1)قسم ثالث میں رجال کی کنیتوں میں ابو طلیق کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۴۹۹) تجرید (۳۲۶/۲)"}],[10723,"§۱۲۱۱۴ ۔ ام طلق\nانہوں نے نبوت کا زمانہ پایا، ابن سعد نے ان سے روایت کی ہے۔ فرماتی ہیں: سیدنا عمر رضی اللہ عنہ نے اپنے گورنروں کو لکھا، اپنی عمارتوں کو بلند نہ کرو، تمہارا برا دن وہ ہوگا جس میں تم اپنی عمارتوں کو بلند کرو گے۔"],[10724,"§۱۲۱۱۵ ۔ ام عاصم السوداء\n(1)نبی کریم صلی اللہ علیہ وسلم کے پاس بیعت کرنے کے لیے آئیں، تجرید میں یہی لکھا ہے۔","",{"fn":"(1) تجرید (۳۲۶/۲)"}],[10725,"§۱۲۱۱۶ ۔ ام عامر بنت سعید\nبن سکن، اسماء بنت یزید بن سکن اشہلیہ کی چچا زاد ہیں، ابن مندہ نے ان کا ذکر کیا ہے، اور ان سے حدیث عرق نقل کی جو عنقریب آگے آرہی ہے۔ لیکن اس میں ان کا نسب موجود نہیں، اس میں صرف عن ام عامر ہے۔"],[10726,"§۱۲۱۱۷ ۔ ام عامر بنت سلیم\n(1)بن ضبع بن عامر بن مجدعہ بن جشم بن حارثہ انصاریہ، ان کا نام حبانہ ہے، ناموں میں ان کا ذکر گزر چکا ہے۔ ابن سعد(2) کا قول ہے: اسید بن ساعدہ سے ان کا نکاح ہوا جس سے یزید کی ولادت ہوئی، ابن عمارہ کے قول کے مطابق بیعت کی۔","",{"fn":"(1) تجرید (۳۲۶/۲)\n(2) الطبقات الکبریٰ (۲۴/۸)"}],[10727,"§۱۲۱۱۸ ۔ ام عامر بنت سوید\n(1)ابو موسیٰ نے ذیل میں بحوالہ مستغفری ان کا ذکر کیا ہے، ان سے کوئی روایت مروی نہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۰۲) تجرید (۳۲۶/۲)"}],[10728,"§۱۲۱۱۹ ۔ ام عامر بنت ابو قحافہ\nابو بکر صدیق رضی اللہ عنہ کی بہن ہیں، ام فروہ جن کا ذکر آگے آرہا ہے، ان کی سگی بہن ہیں۔ ابن سعد(1) نے ان کا ذکر کیا ہے، فرماتے ہیں: ان سے عامر بن ابو وقاص نے نکاح کیا، جس سے ضعیفہ کی ولادت ہوئی۔","",{"fn":"(1) طبقات (۱۸۱/۸)"}],[10729,"§۱۲۱۲۰ ۔ ام عامر بنت کعب الانصاریہ\n(1)ان سے لیلیٰ مولاۃ حبیب بن عبد الرحمن نے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"آؤ اور کھاؤ۔\" انہوں نے کہا: میں روزہ سے ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب روزہ دار کے سامنے کھایا جاتا ہے تو فرشتے اس پر درود بھیجتے ہیں۔\"","",{"fn":"(1) اسد الغابہ (۷۵۰۳) الاستيعاب (۳۶۳۴) تجرید (۳۲۶/۲)"}],[10730,"§۱۲۱۲۱ ۔ ام عامر بنت یزید\n(1)بن سکن انصاریہ اشہلیہ، ابو عمر نے ان کا ذکر کیا ہے، فرماتے ہیں: اگر یہ صحیح ہے تو یہ اسماء بنت یزید یا ان کی بہن ہیں۔ میں کہتا ہوں: یہ ان کی بہن ہیں، ابن سکن نے ان کا نام نگیہہ لیا ہے، اسماء میں ان کا ذکر گزر چکا ہے۔ بیعت کرنے والی صحابیات میں سے ہیں۔ جمیلہ بنت ثابت بن ابو الافلح میں ان کا ذکر گزر چکا ہے، اسی طرح حواء بنت یزید بن سکن میں بھی ان کا ذکر گزر چکا ہے۔ حدیث میں ان کی کنیت منقول ہے، جسے امام احمد(2) اور عمر بن شبہ نے عبد الرحمن بن عبد اللہ اشہلی کی روایت سے ان کے حوالے سے نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس گوشت والی ہڈی لے آئیں، آپ صلی اللہ علیہ وسلم نے اسے نوش فرمایا، آپ صلی اللہ علیہ وسلم مسجد میں تھے، پھر آپ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے اور وضو نہیں کیا۔ اسے ابن سعد(3) نے اس طریق سے نقل کیا ہے، فرماتے ہیں: بحوالہ ام عامر بنت یزید بن سکن، بیعت کرنے والی صحابیات میں سے ہیں، پھر اس کا ذکر کیا، فرماتے ہیں: ایک روایت میں ہے؟ وہ مسجد بنو عبد اشہل میں تھے۔ اور بحوالہ عبد الرحمن بن ثابت نقل کیا ہے، فرماتے ہیں: ام عامر بنت یزید بن سکن آئیں، وہ نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں سے ہیں، یہ وہی ہیں جو گوشت کا ٹکڑا لائیں آپ نے اسے نوش فرمایا، پھر نماز پڑھی اور وضو نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۷۵۰۵) تجرید (۳۲۶/۲)\n(2) مسند احمد (۳۷۲۱۶) (۳۷۲/۶)\n(3) طبقات (۲۳۳/۸) (۲۳۴/۸)"}],[10731,"§۱۲۱۲۲ ۔ ام عامر بنت یزید\nبن سکن، ان کا ذکر پہلے گزر چکا ہے، ابن سعد نے ان کا ذکر کیا ہے۔ فرماتے ہیں: ان کا نام فکیہہ ہے۔ بعض نے کہا: اسماء ہے، واقدی کے حوالے سے بحوالہ ام عامر اسماء بنت یزید بن سکن روایت کیا ہے، فرماتی ہیں: میں نے مغرب کے وقت رسول اللہ صلی اللہ علیہ وسلم کو اپنی مسجد میں دیکھا، میں گھر آئی، میں آپ صلی اللہ علیہ وسلم کے پاس گوشت اور چپاتی لے کر گئی، میں نے کہا: رات کا کھانا کھائیں۔ آپ صلی اللہ علیہ وسلم نے اپنے ساتھیوں سے فرمایا: \"کھاؤ۔\" آپ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے ساتھ آئے ہوئے اصحاب نے کھایا، اور گھر میں موجود لوگوں نے بھی کھایا، یہ سب چالیس مرد تھے، اس ذات کی قسم! جس کے قبضے میں میری جان ہے، میں نے دیکھا کہ کچھ گوشت اور زیادہ تر روٹی باقی تھی۔ فرماتی ہیں: آپ نے میرے پاس نیم بریدہ مشک میں پانی پیا، میں نے وہ لے کر تیل لگایا اور لپیٹ لیا۔ ہم اس میں مریضوں کو پلاتے تھے اور برکت کے لیے خود پیتے۔"],[10732,"§۱۲۱۲۳ ۔ ام عامر الاشہلیہ\n(1)ابو عمر کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے پاس گئیں، ان سے ابو سفیان مولیٰ ابن ابو احمد نے واقدی رحمہ اللہ کی حدیث سے روایت کیا ہے۔ میں کہتا ہوں: ان کی حدیث کو، ان کے حوالے سے ابن سعد(2) نے واقدی کے حوالے سے، عبد اللہ بن ابو سفیان سے، ان کے والد کے حوالے سے نقل کیا ہے، میں نے ام عامر اشہلیہ سے سنا، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی تھی، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم جب ہمارے گھروں کو دیکھتے تو فرماتے: \"ان گھروں میں کتنی خیر و برکت ہے، یہ انصار کے بہترین گھر ہیں۔\" واقدی رحمہ اللہ کا قول ہے: ام عامر اشہلیہ خیبر میں حاضر ہوئیں۔","",{"fn":"(1) اسد الغابہ (۷۵۰۰) تجرید (۳۲۶/۲)\n(2) طبقات (۲۳۳/۸)"}],[10733,"§۱۲۱۲۴ ۔ ام عامر الفہریہ\n(1)ابو عبیدہ بن جراح کی والدہ ہیں، خلفہ بن خیاط نے ان کا ذکر کیا ہے، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۰۱) تجرید (۳۲۶/۲)"}],[10734,"§۱۲۱۲۵ ۔ ام عامر\n(1)ابو طفیل بن وائلہ کی والدہ ہیں، ابن ابو عاصم(2) نے ان کا ذکر کیا ہے اور جابر جعفی کے طریق سے بحوالہ ابو طفیل روایت کیا ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کے دن دیکھا، مجھے آپ صلی اللہ علیہ وسلم کے چہرے کی سفیدی کے ساتھ آپ صلی اللہ علیہ وسلم کے سیاہ بال یاد ہیں۔ میں نے اپنی والدہ سے پوچھا: یہ کون ہیں؟ انہوں نے کہا: یہ رسول اللہ صلی اللہ علیہ وسلم ہیں۔ ابو نعیم نے اسے اپنے طریق سے پھر ابو موسیٰ نے اسے نقل کیا ہے، جابر ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۰۴) تجرید (۳۲۶/۲)\n(2) الآحاد والمثانی (۲۴۲۹/۶)"}],[10735,"§۱۲۱۲۶ ۔ ام عبد اللہ بن اسلم\nان کا نام سلمی ہے، ان کا ذکر گزر چکا ہے۔"],[10736,"§۱۲۱۲۷ ۔ ام عبد اللہ بنت اوس الانصاریہ\n(1)شداد بن اوس انصاری کی بہن ہیں، ان کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر کا قول ہے: شامیہ ہیں، ان سے ضمرہ بن حبیب نے روایت کی۔ میں کہتا ہوں: ان کی حدیث احمد(2) نے زہد میں اور طبرانی اور ابن مندہ نے اور معافی بن عمران نے تاریخ موصل میں نقل کی ہے، الفاظ اسی کے ہیں، کئی طریق سے بحوالہ ضمرہ بن حبیب، انہوں نے ام عبد اللہ سے، انہوں نے اخت شداد بن اوس سے روایت کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو ایک پیالے میں افطار کے وقت دودھ بھیجا، آپ صلی اللہ علیہ وسلم روزے سے تھے، جبکہ دن طویل اور گرمی کی شدت تھی، آپ صلی اللہ علیہ وسلم نے ان کی طرف قاصد کو لوٹایا اور پوچھا: \"تمہارے پاس یہ دودھ کہاں سے آیا؟\" انہوں نے کہا: میری بکری کا ہے۔ آپ صلی اللہ علیہ وسلم نے ان کی طرف قاصد کو لوٹایا اور پوچھا: \"تمہارے پاس یہ بکری کہاں سے آئی؟\" انہوں نے کہا: میں نے اسے اپنے مال سے خریدا۔ آپ صلی اللہ علیہ وسلم نے اسے قبول فرما لیا۔ جب دو پہر ہوئی تو ان کے پاس ام عبد اللہ آئیں اور کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! سخت گرمی اور طویل دن کی وجہ سے ترس کھاتے ہوئے آپ کے پاس دودھ بھیجا، آپ نے قاصد کو واپس بھیجا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس لیے کہ رسولوں کو حکم ہے کہ ہم پاکیزہ چیزیں کھائیں اور نیک عمل کریں۔\"","",{"fn":"(1) اسد الغابہ (۷۵۰۵) تجرید (۳۲۶/۲)\n(2) المعجم الکبیر (۴۲۸/۲۵)"}],[10737,"§۱۲۱۲۸ ۔ ام عبد اللہ بنت ابی خیثمہ\nان کا نام لیلیٰ ہے، ان کا ذکر پہلے گزر چکا ہے۔"],[10738,"§۱۲۱۲۹ ۔ ام عبد اللہ بنت حنظلہ\nبن قسامہ، نعیم بن نجام کی زوجہ ہیں، اس کے بعد ان کا ذکر آئے گا۔"],[10739,"§۱۲۱۳۰ ۔ ام عبد اللہ بنت ابی دومی\nابو موسیٰ کی زوجہ ہیں، ان کے بعد ذکر آئے گا۔"],[10740,"§۱۲۱۳۱ ۔ ام عبد اللہ بنت سلمہ\nبنت مخرمہ تمیمیہ، ان کا نام اسماء ہے، پہلے ان کا ذکر گزر چکا ہے۔"],[10741,"§۱۲۱۳۲ ۔ ام عبد اللہ بنت سواد\n(1)بن رزن، بن زید بن ثعلبہ بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاریہ، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ ام حارث بنت نعمان بن خنساء، ابو محمد بن معاذ بن انس نے ان سے نکاح کیا۔","",{"fn":"(1) تجرید (۳۲۷/۲)\n(2) طبقات (۲۹۵/۸)"}],[10742,"§۱۲۱۳۳ ۔ ام عبد اللہ بنت عازب الانصاریہ\n(1)ان کے بھائی براء اور والد کے سوانح میں ان کا ذکر گزر چکا ہے۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: براء کی سگی بہن ہیں، ان کی والدہ ام حبیبہ بنت ام حبیبہ بن حباب نجاریہ ہیں، بعض کا قول ہے: وہ ام خالد بنت ثابت بن سنان بن عبید بن ابجر ہیں، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۳۲۷/۲)\n(2) طبقات (۲۴۷/۸)"}],[10743,"§۱۲۱۳۴ ۔ ام عبد اللہ بنت عدی\nبن خویلد، اسدیہ۔ سیدہ خدیجہ رضی اللہ عنہا انہی کی بھتیجی ہیں۔ حسین بن حارث بن مطلب کی زوجہ ہیں۔ ابن سعد رحمہ اللہ نے حصین کے سوانح میں ان کا ذکر کیا ہے، عبد اللہ بن حصین مذکور کی والدہ ہیں۔"],[10744,"§۱۲۱۳۵ ۔ ام عبد اللہ بنت معاذ\n(1)بن جبل، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن سعد(2) کا قول ہے: اسلام لائیں اور بیعت کی، ان کی والدہ ام عمرو بنت خلاد، ان سے عبد اللہ بن مروان نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۲۷/۲)\n(2) طبقات (۳۰۰/۸)"}],[10745,"§۱۲۱۳۶ ۔ ام عبد اللہ بنت ملحان\n(1)ام سلیم کی بہن ہیں، واقدی رحمہ اللہ نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔ ابن سعد(2) نے اسے بیان کیا ہے۔","",{"fn":"(1) تجرید (۳۲۷/۲)\n(2) طبقات (۳۱۹/۸)"}],[10746,"§۱۲۱۳۷ ۔ ام عبد اللہ بنت نبیہ\n(1)بن حجاج بن حذیفہ سہمیہ، عبد اللہ بن عمرو بن عاص سہمی کی والدہ ہیں۔ حارث بن ابی اسامہ نے اپنی مسند میں عبد اللہ بن قدامہ کے طریق سے بحوالہ عمرو بن شعیب اور وہ عمرو کے بھائی ہیں، اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم پر شفقت کرتی تھیں، آپ صلی اللہ علیہ وسلم ایک دن ان کے پاس آئے اور فرمایا: اے ام عبد اللہ! کیسی ہو؟ انہوں نے کہا: خیریت سے ہوں، عبد اللہ ایسے شخص ہیں جو دنیا چھوڑ چکے ہیں۔.....(2) (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۵۱۴) تجرید (۳۲۷/۲)\n(2) اسد الغابہ (۴۶۹/۵)"}],[10747,"§۱۲۱۳۸ ۔ ام عبد اللہ بنت ولید\nبن عبد شمس بن مغیرہ بن عبد اللہ بن عمرو بن مخزوم مخزومیہ، ان کے والد یمامہ میں شہید ہوئے، جیسا کہ ان کے سوانح میں گزر چکا ہے۔ ان سے سیدنا عثمان بن عفان امیر المومنین نے نکاح کیا، جس سے ولید اور سعید سیدنا عثمان رضی اللہ عنہ کے بیٹے پیدا ہوئے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[10748,"§۱۲۱۳۹ ۔ ام عبد اللہ دوسیہ\n(1)ابن ابو عاصم(2) نے وحدان میں ان کا ذکر کیا ہے اور معاویہ بن یحییٰ کے طریق سے جو ایک ضعیف راوی ہیں، بحوالہ ام عبد اللہ دوسیہ روایت کیا ہے، اور انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ ہر بستی پر واجب ہے، اگرچہ اس میں چار فرد ہوں۔\"","",{"fn":"(1) اسد الغابہ (۷۵۰۹) تجرید (۳۲۷/۲)\n(2) الآحاد والمثانی (۲۴۰۱/۶)"}],[10749,"§۱۲۱۴۰ ۔ ام عبد اللہ\n(1)بسر مازنی کی زوجہ ہیں، یزید بن خمیر کا قول ہے: میں نے عبد اللہ بن بسر کو فرماتے ہوئے سنا: ہمارے ہاں رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، میری والدہ نے آپ صلی اللہ علیہ وسلم کے لیے چادر بچھائی، آپ صلی اللہ علیہ وسلم اس پر بیٹھ گئے، پھر وہ آپ کے پاس کھجوریں لائیں، آپ صلی اللہ علیہ وسلم کھانے لگے۔..... (الحدیث) اس میں ہے: آپ صلی اللہ علیہ وسلم نے ان کے لیے دعا کی، فرمایا: \"اے اللہ! انہیں برکت دے اور انہیں بخش دے اور ان پر رحم کر۔\"(2) سیدنا عبد اللہ فرماتے ہیں: میں اس دعا کی برکت ساری زندگی محسوس کرتا رہا۔ اسے مسلم، اصحاب سنن نے نقل کیا ہے، ہمیں یہ روایت مسند ابو داؤد طیالسی(3) میں عالی سند سے ملی ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۰۸) الاستيعاب (۳۶۳۷) تجرید (۳۲۷/۲)\n(2) مسلم (۵۲۹۶) ابو داؤد (۳۷۲۹) ترمذی (۳۵۷۶)\n(3) مسند ابو داؤد (۱۲۷۵)"}],[10750,"§۱۲۱۴۱ ۔ ام عبد اللہ\nبنو زہرہ کی ایک خاتون ہیں، ابو موسیٰ کا قول ہے: مستغفری نے ان کا ذکر کیا ہے لیکن ان سے کوئی حدیث روایت نہیں کی۔"],[10751,"§۱۲۱۴۲ ۔ ام عبد اللہ\n(1)ابو موسیٰ اشعری کی زوجہ ہیں، مسند میں ان کی حدیث ابراہیم کے طریق سے بحوالہ قرثع کہ انہوں نے ابو موسیٰ اشعری سے سنا کہ ان کی بیوی نے میت پر چیخ و پکار کی، تو انہوں نے ان سے کہا: تمہیں معلوم نہیں رسول اللہ صلی اللہ علیہ وسلم نے کیا فرمایا ہے؟ وہ کہنے لگیں: کیوں نہیں! پھر وہ خاموش ہو گئیں۔ ان سے کسی نے پوچھا: رسول اللہ صلی اللہ علیہ وسلم نے کیا فرمایا ہے؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس عورت پر لعنت کی جو سر منڈائے یا کپڑے پھاڑے یا بدن نوچے۔(2) ان سے عیاض اشعری نے بھی روایت کی ہے جو مسلم میں ہے۔ ان سے یزید بن اوس، عبد الرحمن بن ابو لیلیٰ اور دوسرے لوگوں نے روایت کیا ہے۔ موسیٰ بن ہارون اس روایت میں فرماتے ہیں، جسے ولید نے اپنے فوائد میں ان سے بحوالہ عبد اللہ بن براد اشعری روایت کیا ہے۔ فرماتے ہیں: ابو بردہ کا نام عامر ہے، اور ان کی والدہ ام عبد اللہ بنت دومی ہیں، انہوں نے ابو موسیٰ کے ساتھ ہجرت کی، دوسرے راویوں کا قول ہے: بنت ابی دومی۔","",{"fn":"(1) اسد الغابہ (۷۵۱۳) الاستيعاب (۳۶۳۶) تجرید (۳۲۷/۲)\n(2) مسند احمد (۴۰۵/۴)"}],[10752,"§۱۲۱۴۳ ۔ ام عبد اللہ\n(1)عبد اللہ بن انیس جہنی کی والدہ اور کعب بن مالک انصاری کی زوجہ ہیں، ابن وہب نے بحوالہ عبد اللہ، انہوں نے اپنی والدہ سے روایت کیا ہے۔ وہ کعب بن مالک کی زوجہ تھیں کہ رسول اللہ صلی اللہ علیہ وسلم کعب بن مالک کے پاس آئے اور وہ مسجد نبوی میں اشعار کہہ رہے تھے، جب انہوں نے آپ صلی اللہ علیہ وسلم کو دیکھا تو وہ شرما گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہمیں بھی شعر سناؤ، تو انہوں نے اشعار سنائے۔.....(2) (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۵۰۶) تجرید (۳۲۶/۲)\n(2) اسد الغابہ (۴۶۷/۵) جامع المسانید والسنن (۴۵۴/۱۶)"}],[10753,"§۱۲۱۴۴ ۔ ام عبد اللہ\n(1)نعیم بن نجام کی زوجہ ہیں، ابن مندہ نے ان کا ذکر کیا ہے اور ضحاک بن عثمان کے طریق سے بحوالہ عبد اللہ بن عمر روایت کیا ہے کہ وہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس گئے اور کہا: میں نے بنت نعیم بن نجام کو نکاح کا پیغام دیا ہے اور میں چاہتا ہوں کہ آپ میرے ساتھ چلیں، اور ان سے میرے بارے میں بات کریں۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: میں نعیم کو تم سے زیادہ جانتا ہوں، اس کے پاس ان کا یتیم بھتیجا ہے۔ وہ اسے ہی رشتہ دے گا۔ آپ نے کہا: اس کی والدہ نے مجھے نکاح کا پیغام بھیجا ہے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: اگر تم ضرور جانا چاہتے ہو تو اپنے چچا زید بن خطاب کو ساتھ لے جاؤ۔ وہ کہتے ہیں: وہ دونوں ان کے پاس گئے اور انہوں نے ان سے بات کی، فرماتے ہیں: گویا نعیم نے سیدنا عمر رضی اللہ عنہ کی بات سن لی، اس نے کہا: تمہیں خوش آمدید ہو، تم بڑی منزلت اور شرف رکھتے ہو، پھر کہنے لگے: میرا ایک یتیم بھتیجا ہے، میں بھتیجے کو چھوڑ کر کسی اور کو رشتہ نہیں دوں گا۔ فرماتے ہیں: ان کی والدہ گھر کے کونے سے بولیں: اللہ کی قسم! یہ اس وقت تک نہ ہوگا جب تک رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان فیصلہ نہ کر دیں، کیا تم بن عدی کی لڑکی کو اپنے بے وقوف یا کہنے لگیں کمزور بھتیجے کی وجہ سے روکے رکھو گے۔ پھر وہ چلی گئیں، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، اور آپ صلی اللہ علیہ وسلم کو بتایا، آپ صلی اللہ علیہ وسلم نے نعیم کو بلایا، انہوں نے جو کچھ عبد اللہ بن عمر کو کہا تھا، عرض کر دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"صلہ رحمی کرو، اپنی بیٹی اور اس کی ماں کو راضی رکھو، کیونکہ انہیں ان کے معاملے میں حق ہے\"۔(2) میں کہتا ہوں: زبیر بن بکار نے یہ قصہ مختصر ذکر کیا ہے، اور ام عبد اللہ کا قصہ ذکر نہیں کیا۔ نہ ان کی بات اور مرفوع حدیث کا ذکر کیا، فرماتے ہیں، اس میں ہے: سیدنا عمر رضی اللہ عنہ نے نعیم سے کہا: تمہیں تمہارے بھتیجے نے نکاح کا پیغام دیا تم نے اسے رد کر دیا؟ انہوں نے کہا: میرا ایک کمزور بھتیجا ہے جسے لوگ رشتہ نہیں دیں گے، اگر میں نے اپنا گوشت چھوڑ دیا تو اس کی حفاظت کون کرے گا؟","",{"fn":"(1) اسد الغابہ (۷۵۱۵) تجرید (۳۲۷/۲)\n(2) اسد الغابہ (۴۶۹/۵)"}],[10754,"§۱۲۱۴۵ ۔ ام عبد الحمید\n(1)رافع بن خدیج کی زوجہ ہیں، باوردی نے صحابہ میں ان کا ذکر کیا ہے، عمرو بن مرزوق کے طریق سے بحوالہ یحییٰ بن عبد الحمید بن رافع بن خدیج، انہوں نے اپنی دادی سے جو رافع بن خدیج کی زوجہ ہیں نقل کیا ہے، فرماتی ہیں: اُحد کے دن رافع کو ناف پر تیر لگا۔ نبی کریم صلی اللہ علیہ وسلم تشریف لائے، انہوں نے کہا: تیر کھینچ لو۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم چاہو تو میں تیر اور چادر بھی کھینچ لوں، اور اگر تو چاہے تو تیر کھینچ لوں اور چادر چھوڑ دوں اور میں تمہارے لیے قیامت کے دن گواہی دوں گا کہ تم شہید ہو۔\" انہوں نے کہا: تیر کھینچ لیں اور چادر چھوڑ دیں، اور آپ قیامت کے دن گواہی دیں کہ میں شہید ہوں۔ راوی فرماتے ہیں: انہوں نے ایسا ہی کیا، پھر وہ نبی کریم صلی اللہ علیہ وسلم کی حیات مبارکہ میں اور سیدنا ابو بکر، عمر، عثمان رضی اللہ عنہم کے زمانے تک زندہ رہے، جب سیدنا معاویہ رضی اللہ عنہ کا زمانہ یا اس کے بعد تھا تو ان کا زخم ہرا ہو کر بہہ پڑا جس سے وہ وفات پا گئے۔ اسے ابن مندہ نے باوردی سے اسی طرح روایت کیا ہے۔ طبرانی(2) نے ابو ولید طیالسی کے طریق سے آخرین میں بحوالہ عبد الحمید اسی طرح فرمایا، اور اس کے آخر میں فرمایا: وہ زندہ رہے یہاں تک کہ سیدنا معاویہ رضی اللہ عنہ کی خلافت میں ان کا زخم ہرا ہو کر بہہ پڑا جس سے عصر کے بعد ان کی وفات ہو گئی۔","",{"fn":"(1) اسد الغابہ (۷۵۱۶) تجرید (۳۲۷/۲)\n(2) المعجم الکبیر (۴۲۴۲/۴)"}],[10755,"§۱۲۱۴۶ ۔ ام عبد الرحمن\nابو عمر کا قول ہے: ان سے ایک حدیث مروی ہے جو انہوں نے اہل کوفہ سے روایت کی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے فرماتے ہوئے سنا: کنکریوں کی مقدار رمی جمرات کیا کرو۔ عبد الرحمن بن اذینہ کی والدہ ہیں۔"],[10756,"§۱۲۱۴۷ ۔ ام عبد الرحمن\n(1)طارق بن علقمہ کی زوجہ ہیں، ابن ابو عاصم(2) نے عبد اللہ بن ابو یزید کی روایت سے بحوالہ عبد الرحمن بن طارق، انہوں نے اپنی والدہ سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم دار یعلیٰ میں ایک گھر میں تشریف لاتے تھے، آپ صلی اللہ علیہ وسلم قبلہ رخ ہو کر دعا کرتے، یعلیٰ آپ کے ساتھ نکلتے اور ہم مسلمان خواتین بھی ساتھ ہوتیں۔","",{"fn":"(1) اسد الغابہ (۷۵۱۹) تجرید (۳۲۸/۲)\n(2) الآحاد والمثانی (۳۳۷۸/۶)"}],[10757,"§۱۲۱۴۸ ۔ ام عبد الرحمن\n(1)کعب بن مالک کی زوجہ اور ان کی اولاد عبد الرحمن وغیرہ کی والدہ ہیں، ابو موسیٰ نے بحوالہ جعفر ان کا ذکر کیا ہے اور ان کی کوئی حدیث روایت نہیں کی۔","",{"fn":"(1) اسد الغابہ (۷۵۲۰) تجرید (۳۲۸/۲)"}],[10758,"§۱۲۱۴۹ ۔ ام عبید بنت سراقہ\n(1)بن حارث بن عدی بن مالک بن عدی بن عامر بن غنم بن نجار، ابن سعد(2) نے ان کا ذکر کیا ہے۔ فرماتے ہیں: حارثہ بن سراقہ کی بہن ہیں۔ ان کی والدہ ربیع بنت نضر، سیدنا انس رضی اللہ عنہ کی پھوپھی ہیں، سراقہ کے بعد ان سے تمیم بن غزیہ نے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (۷۵۲۴) تجرید (۳۲۸/۲)\n(2) الطبقات الکبریٰ (۳۰۷/۸)"}],[10759,"§۱۲۱۵۰ ۔ ام عبید بنت صخر\n(1)بن مالک بن عمرو بن غزیہ، اسلت کی زوجہ تھیں، جو فوت ہو گیا۔ اس کے بعد ان سے ابو قیس بن اسلت(2) نے نکاح کیا۔ اسلام نے ان دونوں کے درمیان جدائی کرا دی کیونکہ وہ اس کے باپ کی بیوی تھی، ابو موسیٰ نے اسے محمد بن ثور کے طریق سے بحوالہ ابن جریج روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۲۵) تجرید (۳۲۸/۲)\n(2) اسد الغابہ (۴۷۱/۵)"}],[10760,"§۱۲۱۵۱ ۔ ام عبید بنت حارث\n(1)بن یزید ہذلیہ، جعفر مستغفری نے مختصر ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۲۲) تجرید (۳۲۸/۲)"}],[10761,"§۱۲۱۵۲ ۔ ام عبید بنت سود\n(1)بن قریم بن صاہلہ، ہذلیہ، عبد اللہ بن مسعود کی والدہ ہیں۔ ابن عبد البر نے اسی طرح ان کا نسب بیان کیا ہے، اس میں تردو ہے۔ ابن کلبی رحمہ اللہ کا قول ہے: ام عبد بنت عبدوڈ بن سود بن قریم ہیں، یہ قول قابل اعتماد ہے۔ صاہلہ اور عبد اللہ بن مسعود کے درمیان پانچ آباء ہیں۔ ابن سعد(2) کا قول ہے: اسلام لائیں اور بیعت کی۔ فرماتے ہیں: میری والدہ نے مجھے رات گزارنے کے لیے رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا تھا کہ میں دیکھوں کہ آپ صلی اللہ علیہ وسلم وتر کس طرح ادا کرتے ہیں، میں نے آپ صلی اللہ علیہ وسلم کے پاس رات گزاری، آپ صلی اللہ علیہ وسلم نے جتنی چاہی نماز پڑھی، جب رات کا آخری وقت ہوا اور آپ صلی اللہ علیہ وسلم نے وتر پڑھنے کا ارادہ کیا تو پہلی رکعت میں سورۃ الاعلیٰ پڑھی۔ دوسری رکعت میں سورۃ الکافرون پڑھی، پھر تشہد کیا، پھر کھڑے ہوئے اور سلام کے ساتھ دونوں میں تفریق نہ کی۔ پھر سورۃ ﴿قُلْ هُوَ اللہُ اَحَدٌ﴾ پڑھی، جب یہ پڑھ چکے تو تکبیر کہی، پھر دعائے قنوت پڑھی اس کے بعد دعا کی، پھر تکبیر کہی اور رکوع کیا۔ یہ سند بہت زیادہ ضعیف ہے، ابان اور راوی کی وجہ سے جو ان سے روایت کرتے ہیں۔ سفیان ثوری نے بحوالہ ابراہیم اس سند سے روایت کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم نے وتر میں دعائے قنوت پڑھی۔ وکیع نے بحوالہ مصعب بن یزید روایت کیا ہے، فرماتے ہیں: سیدنا عمر رضی اللہ عنہ نے مہاجر خواتین کو دو ہزار درہم مقرر کیے، ان میں ام عبید بھی ہیں، ابن سعد نے بحوالہ ابو اسحاق اسی طرح روایت کیا ہے، لیکن فرمایا: ہزار درہم، پہلی روایت زیادہ ثابت ہے۔ ابو موسیٰ کا قول ہے: میں ابن مسعود اور ان کی والدہ کو رسول اللہ صلی اللہ علیہ وسلم کے گھر کثرت سے آنے جانے کی وجہ سے نبی کریم صلی اللہ علیہ وسلم کے گھرانے میں شمار کرتا تھا۔ ابن مندہ نے مسعودی کے طریق سے بحوالہ ابو اسحاق سبیعی روایت کیا ہے کہ سیدنا عمر رضی اللہ عنہ ام عبید کے آنے کا انتظار فرما رہے تھے، پھر وہ آئیں اور اپنے بیٹے عقبہ بن مسعود کی نماز جنازہ میں شریک ہوئیں۔","",{"fn":"(1) اسد الغابہ (۷۵۲۱) تجرید (۳۲۸/۲)\n(2) طبقات الکبریٰ (۲۱۲/۸)"}],[10762,"§۱۲۱۵۳ ۔ ام عبیس بنت مسلمہ انصاریہ\n(1)محمد بن مسلمہ کی بہن ہیں، محمد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عبس بن جبر کی زوجہ تھیں، جن سے اولاد ہوئی، اسلام لائیں اور بیعت کی۔ محمد بن سعد(2) کا قول ہے: ان کی والدہ خلیدہ بنت ابو عبید بن وہب بن لوزان ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۲۳) تجرید (۳۲۸/۲)\n(2) طبقات الکبریٰ (۲۴۲/۸)"}],[10763,"§۱۲۱۵۴ ۔ ام عبیس بنت سراقہ\n(1)بن حارث بن عدی انصاریہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا شمار کیا ہے، اگر یہ روایت محفوظ ہے تو یہ ام عبید کی بہن ہیں، جن کا ذکر ابھی گزرا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۲۶) تجرید (۳۲۸/۲)"}],[10764,"§۱۲۱۵۵ ۔ ام عبیس\n(1)یہ ان لوگوں میں سے تھیں جنہوں نے اسلام لانے میں سبقت حاصل کی، اور مشرکین انہیں ایذا دیتے تھے۔ ابو بشر دولابی نے بحوالہ شعبی روایت کیا ہے کہ اسلام لائیں، کریز بن ربیعہ بن حبیب بن عبد شمس کی زوجہ ہیں، ان سے عبیس کی ولادت ہوئی، جس پر ان کی کنیت ہے۔ یونس بن بکیر نے ابن اسحاق(2) نے زیادات مغازی میں بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے روایت کیا ہے کہ ابو بکر صدیق رضی اللہ عنہ نے سات لوگوں کو جنہیں مشرکین ایذا دیتے تھے، آزاد کیا، وہ یہ ہیں: بلال، عامر بن فہیرہ، زنیرہ، بنو مؤمل کی باندی، نہدیہ اور ان کی بیٹی، ام عبس، محمد بن عثمان بن ابو شیبہ نے اپنی تاریخ میں بحوالہ انس روایت کیا ہے، فرماتے ہیں: ام ہانی بنت ابو طالب فرماتی ہیں: سیدنا ابو بکر رضی اللہ عنہ نے سیدنا بلال رضی اللہ عنہ کو آزاد کیا اور ان کے ساتھ چھ اور لوگوں کو آزاد کیا، جن میں ام عبیس شامل ہیں۔ ابو نعیم اور ابو موسیٰ نے اپنے طریق سے اسے نقل کیا ہے۔ زبیر بن بکار کا قول ہے: بنو تیم بن مرہ کی ایک نوجوان عورت اسلام کے ابتدائی زمانے میں اسلام لائی، مشرکین انہیں کمزور سمجھ کر ایذا دیتے تھے۔ سیدنا ابو بکر رضی اللہ عنہ نے انہیں خرید کر آزاد کر دیا، ان کے بیٹے عبیس بن کریز پر ان کی کنیت تھی۔ میں کہتا ہوں: بلاذری کا قول ہے: وہ بنو زہرہ کی باندی تھیں اور اسود بن عبد یغوث انہیں ایذاء دیتا تھا۔","",{"fn":"(1) اسد الغابہ (۷۵۲۷) تجرید (۳۲۸/۲)\n(2) السیر والمغازی (۱۹۱) تجرید (۳۲۸/۲)"}],[10765,"§۱۲۱۵۶ ۔ ام عثمان بنت حثیم خزاعیہ\n(1)مستغفری نے ان کا ذکر کیا ہے اور حسین بن حسن مروزی کے طریق سے بحوالہ وہب بن جریر، انہوں نے اپنے والد سے نقل کیا ہے۔ میں نے قیس بن سعد سے سنا کہ وہ عطاء سے، وہ ام عثمان بنت حیثیم خزاعیہ سے حدیث بیان کرتے ہیں کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے عقیقہ کے بارے میں سوال کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"لڑکے کی طرف سے دو بکریاں بدلے میں اور لڑکی کی طرف سے ایک بکری۔\" ابو موسیٰ(2) اس حدیث کو نقل کرنے کے بعد فرماتے ہیں: یہ حدیث ام کرز کے نام سے معروف ہے۔ میں کہتا ہوں: یہ بھی خزاعیہ ہیں، عنقریب ان کا اور ان کی حدیث روایت کرنے والے کا ذکر آئے گا۔","",{"fn":"(1) ابو داؤد (۲۸۳۴) ابن ماجہ (۳۱۶۲) مسند احمد (۳۸۱/۶) سنن کبریٰ (۳۰۱/۹)\n(2) معجم الکبیر (۳۹۸/۲۵) مسند حمیدی (۳۴۶)"}],[10766,"§۱۲۱۵۷ ۔ ام عثمان بنت خلدہ\n(1)مسند ابو یعلیٰ میں ان کے بیٹے نے ان سے روایت کی، تجرید میں اسی طرح ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۲۸) تجرید (۳۲۸/۲)"}],[10767,"§۱۲۱۵۸ ۔ ام عثمان بنت سفیان\n(1)بنو شیبہ اکابر کی والدہ ہیں، بیعت کرنے والی صحابیات میں سے ہیں۔ یہ ابو عمر کا قول ہے، فرماتے ہیں: عبد اللہ بن مسافع نے اپنی والدہ سے، انہوں نے ان کے حوالے سے روایت کی ہے۔ ابن مندہ کا قول ہے: بنو شیبہ کی والدہ نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، پھر انہوں نے طبرانی اور احمد(2) نے ہشام بن ابو عبد اللہ کے طریق سے بحوالہ ام ولد شیبہ روایت کی، وہ فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو صفا اور مروہ کے درمیان سعی کرتے ہوئے دیکھا، آپ صلی اللہ علیہ وسلم فرما رہے تھے: \"وادی بطحاء کو صرف سفر کر کے ہی پار کیا جا سکتا ہے۔\" ابو نعیم نے اسے ذکر کیا ہے، پھر فرمایا: اسے حماد بن زید نے بحوالہ صفیہ اپنی قوم کی ایک خاتون سے روایت کیا جبکہ اس کا نام نہیں بتایا۔ ابو نعیم نے مسند حسن بن سفیان سے پھر ابن مبارک کی روایت سے بحوالہ ام عثمان بنت سفیان سے روایت کی اور وہ بنو شیبہ اکابر کی والدہ ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، آپ صلی اللہ علیہ وسلم نے شیبہ کو بلایا، بیت اللہ کو کھولا، پھر اس میں داخل ہوئے، جب باہر تشریف لائے تو ان سے فرمایا: \"چھت ڈھانپ دو، کیونکہ بیت اللہ میں نمازی کو غافل کرنے والی کوئی چیز نہیں ہونی چاہیے۔\"","",{"fn":"(1) اسد الغابہ (۷۵۲۹) تجرید (۳۲۹/۲)\n(2) مسند احمد (۴۰۴/۶، ۴۰۵)"}],[10768,"§۱۲۱۵۹ ۔ ام عثمان ثقفیہ\nمشہور صحابی عثمان بن ابو العاص کی والدہ ہیں، عبد اللہ بن عثمان بن ابو سلیمان نے بحوالہ عثمان بن ابو العاص ان کی حدیث روایت کی ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کی ولادت کے وقت حضرت آمنہ کے ہاں موجود تھیں، یہ طویل قصہ ہے جسے ابن مندہ نے روایت کیا ہے۔"],[10769,"§۱۲۱۶۰ ۔ ام عجرد خزاعیہ\n(1)ابو عمر کا قول ہے: مثنیٰ بن صباح کے پاس ان کی حدیث ہے، وہ بہت ضعیف راوی ہیں، بحوالہ عمرو بن شعیب، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا ہے کہ میں نے ام عجرد خزاعیہ کو رسول اللہ صلی اللہ علیہ وسلم سے سوال کرتے ہوئے سنا۔ انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! کچھ کام ہم جاہلیت میں کرتے تھے، کیا ہم انہیں اسلام میں کریں؟ آپ صلی اللہ علیہ وسلم نے پوچھا: \"وہ کیا ہیں؟\" انہوں نے کہا: عقیقہ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"لڑکے کی طرف سے دو بکریاں بدلے میں اور لڑکی کی طرف سے ایک بکری۔\" ام کرز کی(2) حدیث کی طرح ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۳۰) تجرید (۳۲/۲)\n(2) اس کا حوالہ ام عثمان عظیم کے سوانح میں گزر چکا ہے۔"}],[10770,"§۱۲۱۶۱ ۔ ام عصمہ الغوصیہ\n(1)طبرانی نے ان کا ذکر کیا ہے اور ابو مہدی، سعید بن سنان کے طریق سے بحوالہ ام عصمہ عوصیہ جو ابن قیس کی زوجہ ہیں نقل کیا ہے۔ فرماتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی مسلمان گناہ کرتا ہے تو جو فرشتہ اس کے گناہوں کو شمار کرنے پر مقرر ہے وہ تین گھڑیاں رکا رہتا ہے اس دوران اگر وہ اپنے گناہ کی بخشش مانگ لے تو قیامت کے دن اس پر کوئی گناہ نہیں ہو گا\"۔(2) اسے حاکم نے مستدرک میں اس طریق سے نقل کیا، کہتے ہیں: اس کی اسناد صحیح ہیں۔ اسے ابن مندہ نے اس طریق سے نقل کیا ہے، فرماتے ہیں: اسی طرح فرمایا یعنی سعید بن سنان، فرماتے ہیں: دوسرے راویوں کا قول ہے: بن ام عصمہ۔ میں کہتا ہوں: وہ خطا ہے، عوصیہ بنو عوص بن عوف بن عذرہ کی طرف نسبت ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۳۱) تجرید (۳۲۹/۲)\n(2) مسند احمد (۴۰۷/۶) جامع المسانید والسنن (۴۶۲/۱۶)"}],[10771,"§۱۲۱۶۲ ۔ ام عطاء\n(1)زبیر بن عوام کی مولاۃ ہیں، ابو عمر کا قول ہے: انہیں شرف صحابیت اور روایت حاصل ہے۔ میں کہتا ہوں: رہی شرف صحابیت تو وہ انہیں حاصل ہے اور رہی روایت تو انہوں نے اپنے مولا زبیر سے روایت کی ہے، احمد(2) نے ابن اسحاق کے طریق سے بحوالہ عبد اللہ بن عطا جو زبیر بن عوام کے مولیٰ ہیں، انہوں نے اپنی والدہ اور دادی ام عطاء کے حوالے سے روایت کی، فرماتی ہیں: گویا ہم زبیر بن عوام کو دیکھ رہے ہیں، جب وہ ہمارے پاس سفید خچر پر آئے اور کہنے لگے، اے ام عطاء! رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو قربانی کا گوشت تین دن سے زیادہ کھانے سے روکا ہے، وہ کہنے لگیں: جو ہمیں ہدیہ بھیجا گیا ہے اس کا کیا کریں؟ فرمایا: جو تمہیں ہدیہ میں بھیجا گیا ہے اسے استعمال کرو۔","",{"fn":"(1) اسد الغابہ (۷۵۳۲)، تجرید (۳۲۹/۲)\n(2) مسند احمد (۱۶۶/۱) تجرید (۳۲۹/۲)"}],[10772,"§۱۲۱۶۳ ۔ ام عطیہ أنصاریہ\nان کا نام نسیبہ ہے۔ اپنے نام اور کنیت سے مشہور ہیں، بنت حارث ہیں، بعض کا قول ہے: بنت کعب، ابو عمر نے اس کا انکار کیا ہے، کیونکہ نسیبہ بنت کعب ام عمارہ ہیں جن کا ذکر آگے آ رہا ہے۔ ام عطیہ نے نبی کریم صلی اللہ علیہ وسلم اور سیدنا عمر رضی اللہ عنہ سے روایت کی، ان سے سیدنا انس رضی اللہ عنہ، محمد اور حفصہ جو سیرین کی اولاد ہیں، اسماعیل بن عبد الرحمن بن عطیہ، عبد الملک بن عمیر اور دوسرے لوگوں نے روایت کی۔ ان کی حدیث نبی کریم صلی اللہ علیہ وسلم کے برتن دھونے کے بارے میں صحیح میں مشہور ہے۔ علمائے تابعین میں سے ایک جماعت اس حکم کو لیتے ہیں، ابو داؤد میں قتادہ کے طریق سے بحوالہ محمد بن سیرین روایت ہے کہ وہ غسل کرنے کا طریقہ پوچھا کرتے تھے، ام عطیہ سے، یہاں تک کہ میت کو غسل دینے کا طریقہ بھی ان سے پوچھتے، صحیحین میں ان کی ایک حدیث یہ ہے: رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ ہم عیدین کی نماز میں جوان اور باپردہ عورتوں کو نکالیں۔..... (الحدیث) نبی کریم صلی اللہ علیہ وسلم نے بیعت کے وقت ہم سے عہد لیا کہ ہم نوحہ نہ کریں۔..... (الحدیث)، اس کے بعض طرق سے اسناد کا ذکر ہے۔ حدیث: ہم طہر کے بعد مٹیالے اور زرد رنگ کو کچھ شمار نہ کریں۔ ایک حدیث یہ ہے: ہمیں جنازے کے پیچھے جانے سے منع فرمایا اور ہم پر اس بارے میں سختی نہیں کی۔ ایک حدیث ہے: نبی کریم صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کے پاس تشریف لائے اور پوچھا: \"کیا تمہارے پاس کوئی شے ہے؟\" انہوں نے کہا: نہیں، سوائے صدقہ کی بکری کے گوشت کے جو نسیبہ ہمارے پاس لائی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ اپنے مقام پر پہنچ چکا۔\" صحیح مسلم میں ان سے مروی ہے: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سات غزوات میں جہاد کیا، میں ان کے کجاووں کے ساتھ رہتی۔ صحیح میں بھی اسی طرح بحوالہ حفصہ بنت سیرین مروی ہے کہ سیدہ ام عطیہ بصرہ آئیں، اور قصر بنو خلف میں اتریں، ابو سعد کا قول ہے: ہمیں ابو عاصم نبیل نے بحوالہ ام شراحیل مولاۃ ابو عطیہ بتایا، فرماتی ہیں: علی بن ابو طالب ام عطیہ کے ہاں قیلولہ کیا کرتے تھے، میں درس سے ان کی بغلیں چنتی تھی۔"],[10773,"§۱۲۱۶۴ ۔ ام عطیہ أنصاریہ\n(1)حافضہ، ابن مندہ اور مستغفری نے پہلے والی سے الگ ان کا ذکر کیا ہے، ابو موسیٰ فرماتے ہیں کہ یہ پہلے والی ہیں۔ اور ولید بن صالح کے طریق سے بحوالہ عطیہ قبیلی روایت کرتے ہیں، فرماتی ہیں: مدینہ میں ایک خاتون عورتوں کا ختنہ کیا کرتی تھیں، نبی کریم صلی اللہ علیہ وسلم نے اس سے فرمایا: \"اچھی طرح ختنہ کرنا، بالکل نہ کاٹ دینا، کیونکہ اس سے چہرے کو خوشی اور خاوند کے ہاں مرتبہ ملتا ہے\"۔(2) ابو موسیٰ کا قول ہے: اس سند کے بغیر یہ متن مروی ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۳۳) تجرید (۳۲۹/۲)\n(2) ابو داؤد (۵۲۷۱) جامع المسانید (۴۶۴/۱۶)"}],[10774,"§۱۲۱۶۵ ۔ ام عفیف\n(1)بعض کا قول ہے: ام خطیف بنت مسروح ہذلیہ، عمل بن مالک ہذلی کی زوجہ ہیں، ملیکہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۳۶) تجرید (۳۲۹/۲)"}],[10775,"§۱۲۱۶۶ ۔ ام عفیف نہدیہ\n(1)ابو عمر کا قول ہے، ابو عثمان نہدی نے البیعہ میں ان کی حدیث روایت کی ہے۔ میں کہتا ہوں: اسے طبرانی(2) نے صلت بن دینار کے طریق سے بحوالہ ابو عثمان نہدی، انہوں نے ایک خاتون جنہیں ام عفیف کہا جاتا ہے، سے روایت کیا، فرماتی ہیں، جب خواتین نے بیعت کی تو ہم نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، آپ صلی اللہ علیہ وسلم نے ہم سے عہد لیا کہ محرم کے علاوہ مردوں سے بات چیت نہ کرنا اور ہمیں حکم دیا کہ نماز جنازہ میں سورہ فاتحہ پڑھیں۔","",{"fn":"(1) اسد الغابہ (۷۵۳۷)\n(2) المعجم الکبیر (۴۱۰/۲۵)"}],[10776,"§۱۲۱۶۷ ۔ ام عفیف بنت میمونہ\nام المؤمنین، ام حفید میں ان کا ذکر گزر چکا ہے۔"],[10777,"§۱۲۱۶۸ ۔ ام عقیل\n(1)ان سے اسحاق بن عبد اللہ بن ابو فروہ جو ضعیف راوی ہیں، حدیث روایت کی، بحوالہ ام عقیل، فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور عرض کیا: ابو عقیل وفات پا گئے ہیں، اور اس اونٹ کو اللہ کی راہ میں دینے کی وصیت کر گئے ہیں، اور یہ کمزور ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے ام عقیل! عمرہ کرو۔ کیونکہ رمضان المبارک میں عمرہ حج کے برابر ہوتا ہے\"۔(2) اسے ابن مندہ نے فضل بن دکین کے طریق سے بحوالہ اسحاق روایت کیا ہے، ابو نعیم کا قول ہے: صحیح یہ ہے کہ ام معقل ہیں، اسی طرح فرمایا: ابن اثیر(3) رحمہ اللہ نے اسے برقرار رکھا ہے، جبکہ اس میں تامل ہے، کیونکہ دونوں احادیث اور دونوں قصوں کا مخرج مختلف ہے، اور فتویٰ عمرہ کرنے اور اونٹ کے ذکر کے بارے میں ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۳۸) تجرید (۳۲۹/۲)\n(2) مسند احمد (۴۰۵/۶) سنن کبریٰ (۳۴۶/۴) معجم کبیر (۳۷۳/۲۵) جامع المسانید والسنن (۵۵۰/۱۶)\n(3) اسد الغابہ (۴۷۴/۵)"}],[10778,"§۱۲۱۶۹ ۔ ام عکاشہ بنت محصن\nطبقات ابن سعد میں زینب بنت جحش کے سوانح کے آخر میں ان کا ذکر ہے۔"],[10779,"§۱۲۱۷۰ ۔ ام علاء أنصاریہ\n(1)ابو عمر کا قول ہے: بیعت کرنے والی صحابیات میں سے ہیں، اہل مدینہ کے پاس ان کی حدیث ہے۔ میں کہتا ہوں: دوسرے راویوں نے ان کا نسب بیان کیا ہے۔ فرماتے ہیں: بنت حارث بن ثابت بن حارثہ بن نعلبہ بن جلاس بن امیہ بن خدرہ بن عوف بن حارث بن خزرج، بعض کا قول ہے: خارجہ بن زید بن ثابت کی والدہ ہیں، ان کی حدیث کے راوی شیخین ہیں۔ بروایت زہری بحوالہ خارجہ بن زید بن ثابت بحوالہ ام انصاریہ، فرماتی ہیں: جب انصار الگ ہوئے تو سیدنا عثمان بن مظعون نے گھر دینے میں تاخیر کی، پھر سیدنا عثمان بن مظعون کی شہادت کے بارے میں حدیث نقل کی، اس میں ہے: انہوں نے سیدنا عثمان رضی اللہ عنہ کے لیے جاری چشمہ دیکھا، میں نے نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ اس کا عمل ہے۔\" حدیث میں ان کا قول ہے: ابو سائب! میری گواہی تمہارے خلاف ہے، اللہ تعالیٰ نے تمہیں عزت بخشی۔ ابراہیم بن سعد کی روایت میں بحوالہ زہری مروی ہے کہ ام علاء وہ انہی میں سے ایک خاتون ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی تھی، اسی طرح اسحاق بن یحییٰ کلبی کے نسخے میں بحوالہ زہری، ابن سکن سے مروی ہے۔ میں کہتا ہوں: یزید بن ابو حبیب کے طریق سے بحوالہ ام خارجہ بن زید بن ثابت مروی ہے کہ سیدنا عثمان بن مظعون کی جب وفات ہو گئی تو ام حارثہ فرمانے لگیں: ابو سائب! خوشخبری ہو۔..... (الحدیث) اسے احمد(2) اور طبرانی نے نقل کیا ہے۔ اس سے ظاہر ہوتا ہے کہ ام علاء خارجہ مذکور کی والدہ ہیں۔ زہری و تیمیہ کی روایت میں ان کے مبہم ہونے سے یہ لازم نہیں آتا کہ یہ کوئی اور ہیں کیونکہ انسان اپنا ذکر تو چھوڑ دیتا ہے چہ جائیکہ اپنی والدہ۔","",{"fn":"(1) اسد الغابہ (۷۵۳۹) تجرید (۳۲۹/۲)\n(2) مسند احمد (۴۳۶/۶)"}],[10780,"§۱۲۱۷۱ ۔ ام علاء\n(1)حکیم بن حزام انصاری کی پھوپھی ہیں، ابن سکن کا قول ہے، نبی کریم صلی اللہ علیہ وسلم نے ان کی عیادت کی، اہل شام سے ان کی حدیث نقل کی ہے، پھر انہوں نے اور ابن مندہ نے زبیدی کے طریق سے بحوالہ یونس بن سیف اسے نقل کیا ہے کہ حزام بن حکیم نے انہیں بتایا بحوالہ اپنی پھوپھی ام علاء کہ رسول اللہ صلی اللہ علیہ وسلم نے بخار کی وجہ سے ان کی عیادت کی اور انہیں دیکھا کہ بیماری کی شدت سے کانپ رہی ہیں، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"صبر کرو، یہ مومن کے گناہوں کو اس طرح دور کر دیتا ہے جیسے آگ کی میل کچیل کو دور کر دیتی ہے۔\" ابن سکن کا قول ہے: مجھے اس حدیث کے علاوہ ان کی کوئی روایت معلوم نہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۴۰) تجرید (۳۲۹/۲)"}],[10781,"§۱۲۱۷۲ ۔ ام علاء\n(1)ابن سکن رحمہ اللہ کا قول ہے: ان سے عبد الملک بن عمیر نے روایت کی، یہ ان سے پہلی والی نہیں، پھر ابو عوانہ کے طریق سے بحوالہ عبد الملک روایت کیا کہ ایک ام علاء نامی خاتون نے ان سے روایت کی، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے بیماری کی حالت میں میری عیادت کی اور ان سے فرمایا: \"اے ام علاء! خوشخبری ہو، مسلمان کی بیماری سے اللہ تعالیٰ اس کے گناہوں کو دور کر دیتا ہے، جیسا کہ آگ لوہے اور چاندی کی میل کچیل کو دور کر دیتی ہے۔\" میں کہتا ہوں: ابو داؤد(2) نے ابو عوانہ کی روایت سے اسی طرح نقل کیا ہے، دوسرے راویوں کے نزدیک یہ دونوں ایک ہیں، کیونکہ دونوں کی حدیث ایک ہے، اگرچہ ان کے مخرج میں اختلاف ہے، لیکن ابن سکن کے قول کو تقویت ملتی ہے کہ حزام بن حکیم کی پھوپھی نے ان کے بارے میں فرمایا کہ یہ انصاریہ ہیں، حدیث کے سیاق میں ان کا ذکر آیا ہے۔ بحوالہ عبد الملک بن عمیر، انہوں نے ام علاء سے جو انہی میں سے ایک خاتون ہیں، اور عبد الملک تھی، تو یہ تخمیہ ہوں گی، اور جو ان سے قبل گزری ہیں وہ انصاریہ ہیں، اس سے تعدد کو تقویت ملتی ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۴۱) تجرید (۳۳۰/۲)\n(2) ابو داؤد (۳۰۸۹)"}],[10782,"§۱۲۱۷۳ ۔ ام علی بنت خالد\n(1)بن تیم بن بیاضہ بن خفاف بن سعید بن مرہ بن مالک بن اوس انصاریہ اوسیہ۔ ابن اثیر(2) نے بحوالہ ابن دباغ پہلے لکھی گئی کتابوں میں اپنے استدراک میں ان کا ذکر کیا ہے۔ فرماتے ہیں: اذان کا حکم ان کے گھر میں نازل ہوا، یہ ابن کلبی کا قول ہے، عددی کا قول ہے: مجھے معلوم نہیں کہ اہل حجاز اسے جانتے ہوں۔ میں کہتا ہوں: ابن کلبی کے تذکرے میں اس کا ذکر انصار کے نسب کے آخر میں ہے۔ لیکن اس بات کی تصریح نہیں کہ انہیں شرف صحابیت حاصل ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۴۳) تجرید (۳۳۰/۲)\n(2) اسد الغابہ (۴۷۵/۵)"}],[10783,"§۱۲۱۷۴ ۔ ام عمارہ\n(1)نسیبہ بنت کعب بن عمرو بن عوف بن مبذول بن عمرو بن غنم، بنو مازن بن نجار انصاریہ نجاریہ سے ہیں۔ عبد اللہ اور حبیب جو بنو زید بن عاصم سے ہیں، ان کی والدہ ہیں، ابو عمر کا قول ہے: بیعت عقبہ میں شریک ہوئیں اور اپنے شوہر(2) اور ان سے اپنی اولاد کے ساتھ اُحد میں شریک تھیں۔ ابن اسحاق کا قول ہے، بیعت رضوان میں شریک تھیں، پھر یمامہ میں مسلیمہ کے ساتھ لڑائی میں شریک تھیں، اس دن انہیں بارہ(۱۲) زخم آئے، ان کا ہاتھ کٹ گیا اور ان کا بیٹا حبیب شہید ہوا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کئی احادیث روایت کیں، ان سے ان کے بیٹے عباد بن تمیم بن زید اور حارث بن عبد اللہ بن کعب، عکرمہ، لیلیٰ ان کی مولاۃ نے روایت کی۔ ترمذی، نسائی، ابن ماجہ نے شعبہ کے طریق سے بحوالہ حبیب بن زید، انہوں نے اپنی مولاۃ لیلیٰ سے، انہوں نے اپنی دادی ام عمارہ بنت کعب سے ان کی حدیث روایت کی کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس تشریف لائے، وہ آپ صلی اللہ علیہ وسلم کے پاس کھانا لائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کھاؤ۔\" وہ کہنے لگیں: میں روزے سے ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزہ دار کے سامنے جب کھایا جاتا ہے، فرشتے اس کے لیے دعا کرتے ہیں۔\" ابو داؤد نے شعبہ کے طریق سے بحوالہ حبیب انصاری روایت کیا کہ میں نے عباد بن تمیم کو فرماتے ہوئے سنا کہ مجھ سے میری پھوپھی نے اور وہ ام عمارہ ہیں، روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم نے وضو کیا، آپ صلی اللہ علیہ وسلم کے پاس ایک برتن لایا گیا جس میں ایک مد کا دو تہائی پانی تھا۔..... (الحدیث) ابن مندہ نے ایک سند سے جس میں واقدی بھی ہیں اسے وہ حارث بن عبد اللہ بن کعب تک لے گئے ہیں، بحوالہ ام عمارہ بنت کعب روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ وہ کھڑے ہوئے، اپنے اونٹ کو نیزہ سے نحر کر رہے تھے۔..... (الحدیث) ابن سعد رحمہ اللہ کا قول ہے: عبد اللہ بن کعب کی بہن ہیں، وہ اور ابو لیلیٰ بن کعب کی بہن ہیں، جن کا نام عبد الرحمن ہے، ان کی بہن بدر میں شریک تھیں، وہ زیادہ رونے والوں میں سے ایک تھے۔ فرماتے ہیں: زید بن عاصم کے بعد غزیہ بن عمرو نے ان سے نکاح کیا۔ جس سے تمیم اور خولہ کی ولادت ہوئی، وہ عقبہ میں حاضر تھیں اور اس رات بیعت کی، پھر احد، حدیبیہ، خیبر، قفیہ، فتح حنین، یمامہ میں حاضر ہوئیں۔ واقدی نے ابن ابو صعصعہ کے طریق سے مسنداً روایت کیا ہے، ام عمارہ فرماتی ہیں: لیلہ عقبہ میں رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ مبارک پر لوگ بیعت کر رہے تھے، سیدنا عباس رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کا ہاتھ تھامے ہوئے تھے، جب میں اور ام سبیح باقی رہ گئے تو میرے شوہر غزیہ بن عمرو نے پکارا: یا رسول اللہ صلی اللہ علیہ وسلم! یہ دونوں عورتیں ہمارے ساتھ آپ صلی اللہ علیہ وسلم سے بیعت کرنے آئی ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس بات پر میں نے تم سے بیعت لی ہے، میں نے ان سے اسی پر بیعت لے لی ہے، میں عورتوں سے بیعت نہیں کرتا۔\" اس میں فرمایا: ام سعید بنت سعد بن ربیع فرماتی ہیں، میں ان کے پاس آئی، میں نے کہا: مجھے اُحد کے دن کا اپنا واقعہ بتائیں۔ انہوں نے کہا: دن چڑھا تو میں نکلی اور میرے پاس مشکیزے میں پانی تھا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی، آپ صلی اللہ علیہ وسلم اپنے اصحاب میں تھے، مسلمانوں کا پلڑہ بھاری تھا، جب مسلمانوں کو شکست ہونے لگی، تو میں رسول اللہ صلی اللہ علیہ وسلم کی طرف بڑھی اور لڑنے لگی، آپ صلی اللہ علیہ وسلم سے دشمنوں کو تلوار کے ساتھ دور کرنے لگی، کمان سے تیر چلانے لگی، یہاں تک کہ مجھے کئی زخم آئے۔ فرماتی ہیں: میں نے ان کے کندھے پر گہرا گھاؤ دیکھا۔ پھر ابن قمیہ کا قصہ ذکر کیا۔ دوسری سند سے جو عمارہ بن غزیہ تک پہنچتی ہے ذکر کیا کہ انہوں نے اس دن مشرکین کا ایک شہسوار قتل کیا، دوسرے طریق سے بحوالہ عمر مروی ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"میں اُحد کے دن جب بھی دائیں بائیں متوجہ ہوتا، انہیں اپنے سامنے لڑتے ہوئے دیکھتا\"۔(3)","",{"fn":"(1) السیرۃ النبویۃ (۸۳/۲)\n(2) السیرۃ النبویۃ (۶۶/۳)\n(3) مسند احمد (۴۳۹/۶) طبقات کبریٰ (۳۰۴۸) طبقات الکبریٰ (۳۰۱/۸)"}],[10784,"§۱۲۱۷۵ ۔ ام عمارہ أنصاریہ\n(1)ابن مندہ نے پہلی والی خاتون سے علیحدہ ان کا ذکر کیا ہے، سلیمان بن کثیر کے طریق سے بحوالہ ام عمارہ انصاریہ نقل کیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، اور کہنے لگیں: میں دیکھتی ہوں کہ ہر چیز میں مردوں کا ذکر ہے، عورتوں کا کسی حکم میں ذکر نہیں، اس پر یہ آیت \"بے شک مسلمان مرد اور مسلمان عورتیں، مومن مرد اور مومن عورتیں\"۔(2) میں کہتا ہوں: یہ حدیث ابو عمر نے اس سے پہلے والے حالات میں ذکر کی ہے، فرماتے ہیں: عکرمہ نے روایت کیا۔..... پھر اسے ذکر کیا۔ پھر فرماتے ہیں: بعض کا خیال ہے کہ ام عمارہ وہی ہیں جن سے عکرمہ نے روایت کی، یہ پہلی نہیں، جبکہ میرے نزدیک یہ پہلی ہیں۔ صاحب اطراف نے اس کی پیروی کی ہے اور پہلے والی صحابیہ کے سوانح میں ترمذی(3) سے مروی اس طریق اور اس سند کی حدیث نقل کی، فرماتے ہیں: حسن غریب، ہم اس حدیث کو اس طریق سے جانتے ہیں، اسی طرح فرمایا: حدیث ام سلمہ رضی اللہ عنہا میں اس کا مفہوم مروی ہے، اسے نسائی نے محمد بن عمرو کے طریق سے بحوالہ ام سلمہ نقل کیا ہے۔ اس کے کئی طرق ام سلمہ رضی اللہ عنہا سے مروی ہیں۔ سلیمان بن کثیر نے اپنی مسند میں اس کی مخالفت کی ہے۔ بروایت ابو عوانہ بحوالہ حصین، فرماتے ہیں، اس میں ہے: بحوالہ ابن عباس رضی اللہ عنہما فرماتے ہیں: انصار کی ایک خاتون نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، ہاں! سلیمان بن جریر نے بحوالہ حصین متابعت کی ہے۔ اسے ابن مردویہ اور ہشیم نے بحوالہ حصین نقل کیا ہے، ابن مندہ نے اس کا ذکر کیا ہے، گویا ابو عوانہ کی روایت شاذ ہے۔ گویا انہوں نے حسب عادت ایسا کیا ہے۔ کیونکہ عکرمہ، ابن عباس سے بہت زیادہ روایت کرتے ہیں، اسے قابوس بن ابو ظبیان نے بحوالہ ابن عباس رضی اللہ عنہما روایت کیا ہے، فرماتے ہیں: میں نے ازواج مطہرات رضی اللہ عنہن سے کہا۔..... پھر اسی طرح روایت کیا۔","",{"fn":"(1) اسد الغابہ (۷۵۴۲) تجرید (۳۳۰/۲)\n(2) سورۃ الاحزاب (۳۵)\n(3) ترمذی کتاب تفسیر القرآن (۳۲۱۱)"}],[10785,"§۱۲۱۷۶ ۔ ام عمر أنصاریہ\n(1)عمر بن خلدہ کی والدہ ہیں۔ ابن ابو عاصم(2) نے موسیٰ بن عبیدہ کے طریق سے بحوالہ سندر بن جہیم، انہوں نے عمر بن خلدہ سے، انہوں نے اپنی والدہ سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو بھیجا وہ منیٰ میں اعلان کر رہے تھے کہ یہ کھانے، پینے اور عیش کے دن ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۴۴) تجرید (۳۳۰/۲)\n(2) الآحاد والمثانی (۳۳۷۶/۶)"}],[10786,"§۱۲۱۷۷ ۔ ام عمرو بنت سفیان بن عبد اسد مخزومیہ\nابن سعد(1) نے ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ بنت عبد عزی بن ابو قیس ہیں جو بنو عامر بن لوی سے ہیں۔ حویطب بن عبد عزیٰ ان کے ماموں ہیں، ہشام بن کلبی نے کتاب مثالب میں ان کا ذکر کیا ہے۔ فرماتے ہیں: وہ حجۃ الوداع کی رات نکلیں اور قافلے کے اترنے کی جگہ گئیں، اور ان کا ڈول لے لیا، لوگوں نے انہیں پکڑ کر باندھ دیا، پھر نبی کریم صلی اللہ علیہ وسلم کے پاس انہیں لائے، پھر ان کے ہاتھ کاٹنے کا قصہ ذکر کیا۔ اس کے آخر میں فرمایا: عبد اللہ بن سفیان کی بہن ہیں، اور یہ شعر پڑھا: \"ابن سلمیٰ جعدہ کے بیٹے کی بیٹی، قافلوں کے تھیلے چرانے والی، وہ رات بھر اپنے دائیں ہاتھ سے اپنے کپڑے جمع کرنے لگی یہاں تک کہ اس کی حالت یوں ہو گئی کہ اس کے پورے نہ رہے (ہاتھ کٹ گئے)۔\"","",{"fn":"(1) الطبقات (۱۵۳/۸)"}],[10787,"§۱۲۱۷۸ ۔ ام عمرو بنت سلامہ بن وقش\n(1)بن زغبہ بن زعوراء بن عبد اشبل انصاریہ اشہلیہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ سلمیٰ بنت سلمہ بن خالد ہیں، جو سلمہ بن سلامہ بن وقش کی بہن ہیں، عقبہ اور بدر میں حاضر تھیں۔ محمد بن سلمہ سے ان کا نکاح ہوا، جس سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابہ (۷۵۴۷) تجرید (۳۳۰/۲)\n(2) طبقات الکبریٰ (۲۳۵/۸)"}],[10788,"§۱۲۱۷۹ ۔ ام عمرو بنت عمرو بن حدیدہ\n(1)بن عمرو بن سوار بن غنم، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان سے قطبہ بن عامر بن حدیدہ نے نکاح کیا، سلیمان بن عمرو بن حدیدہ کی سگی بہن ہیں۔","",{"fn":"(1) تجرید (۳۳۰/۲)\n(2) طبقات الکبریٰ (۲۸۸/۸)"}],[10789,"§۱۲۱۸۰ ۔ ام عمرو بنت عمرو\n(1)بن حرام انصاریہ خزرجیہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان سے ابو یسر بن کعب نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۳۰/۲)\n(2) طبقات الکبریٰ (۲۹۹/۸)"}],[10790,"§۱۲۱۸۱ ۔ ام عمرو بنت محمود\n(1)بن مسلمہ بن سلمہ بن خالد بن عدی بن مجدعہ بن حارثہ انصاریہ، ان کے والد اور چچا محمد بن مسلمہ کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ اسی طرح ابن سعد(2) کا قول ہے، فرماتے ہیں: ان کی والدہ امامہ بنت بشر بن وقش ہیں، فرماتے ہیں: ان سے عبد اللہ بن محمد بن مسلمہ نے نکاح کیا، اس سے حمید اور عمر کی ولادت ہوئی، اس کے بعد زید بن سعد بن زید بن مالک سے نکاح ہوا۔","",{"fn":"(1) اسد الغابہ (۷۵۴۹) (۳۸۷/۶)\n(2) طبقات الکبریٰ (۲۴۳/۸)"}],[10791,"§۱۲۱۸۲ ۔ ام عمرو بنت مقرم\nبن عبد المطلب ہاشمیہ، ان کی والدہ فلانہ بنت عمرو بن جعونہ ہیں، ان سے مسعود بن معتب ثقفی نے نکاح کیا، ان سے عبد اللہ بن مسعود کی ولادت ہوئی، اس کے بعد ابو سفیان بن حارث بن عبد المطلب نے ان سے نکاح کیا، جس سے عاتکہ کی ولادت ہوئی، یہ ابن سعد سے مروی ہے۔"],[10792,"§۱۲۱۸۳ ۔ ام عمرو\n(1)حریث بن عمرو بن عثمان مخزومی کی زوجہ ہیں، یحییٰ بن یمان کے طریق سے بحوالہ عمرو بن حریث ان کی حدیث منقول ہے۔ فرماتے ہیں: مجھے میری والدہ نبی کریم صلی اللہ علیہ وسلم کے پاس لے گئیں، آپ صلی اللہ علیہ وسلم نے میرے سر پر ہاتھ پھیرا اور میرے لیے رزق کی دعا کی۔(2)","",{"fn":"(1) اسد الغابہ (۷۵۴۵) تجرید (۳۳۰/۲)\n(2) مسند ابو یعلیٰ (۱۴۵۶/۳) الآحاد والمثانی (۷۱۷/۲) مجمع الزوائد (۴۰۵/۹)"}],[10793,"§۱۲۱۸۴ ۔ ام عمرو بنت سلیم\n(1)زرقی، یزید بن ہادی نے ان کی حدیث بحوالہ والدہ عمرو بن سلیم زرقی روایت کی ہے کہ انہوں نے سیدنا علی رضی اللہ عنہ کو منیٰ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پکارتے ہوئے سنا کہ یہ کھانے، پینے اور عیش کے دن ہیں۔(2)","",{"fn":"(1) اسد الغابہ (۷۵۴۸) تجرید (۳۳۰/۲)\n(2) جامع المسانید والسنن (۴۸۶/۱۶)"}],[10794,"§۱۲۱۸۵ ۔ ام عمیس بنت مسلمہ أنصاریہ\n(1)محمد بن سلمہ کی بہن اور ام عمرو کی پھوپھی ہیں، جن کا ذکر اس سے پہلے گزر چکا ہے۔ رافع بن خدیج کی زوجہ ہیں۔ بعض کا قول ہے یہ آیت ﴿وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا﴾(2) ان کے بارے میں نازل ہوئی۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ام عمیس کا ذکر پہلے گزر چکا ہے، مجھے معلوم نہیں کہ لفظی غلطی کی وجہ سے یہ ایک ہیں یا دو۔","",{"fn":"(1) اسد الغابہ (۷۵۴۹) تجرید (۳۳۰/۲)\n(2) سورۃ النساء الآیۃ (۱۲۸)"}],[10795,"§۱۲۱۸۶ ۔ ام عیاش (خادم النبی صلی اللہ علیہ وسلم)\n(1)بعض کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کی صاحبزادی کی باندی ہیں۔ ابن ماجہ وایمیہ نے عبد الکریم بن روح بن عنبہ بن سعید بن ابو عیاش کے طریق سے بحوالہ ام عیاش روایت کیا ہے، وہ رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی رقیہ کی باندی تھیں، فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کو کھڑے ہو کر وضو کراتی تھی، اور آپ صلی اللہ علیہ وسلم بیٹھے ہوتے۔(2) ابن مندہ کی کتاب معرفہ میں ہمیں یہ حدیث عالی سند سے ملی ہے، فرماتے ہیں اور اپنی سند سے بیان کیا ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو موچھیں کم کرتے ہوئے دیکھا ہے۔ اسی سند سے ہے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو بھی خضاب لگاتے ہوئے نہیں دیکھا، یہاں تک کہ آپ صلی اللہ علیہ وسلم کی وفات ہو گئی۔ ابو نعیم نے اس اسناد سے روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"سیدنا عثمان رضی اللہ عنہ نے ام کلثوم سے آسمان کی وحی سے نکاح کیا۔\" ابو عمر کا قول ہے: یہ سند منقطع ہے، عبد الکریم بن روح ضعیف راوی ہے۔ میں کہتا ہوں: ابن ابو عاصم نے ان کی ایک اور حدیث روایت کی اور ابو نعیم نے اپنے طریق سے نقل کی ہے، فرماتے ہیں: ہم سے بد بہ نے بحوالہ ام عیاش روایت کیا اور وہ نبی کریم صلی اللہ علیہ وسلم کی خادمہ تھیں، انہیں اپنی بیٹی کے ساتھ سیدنا عثمان رضی اللہ عنہ کے پاس بھیجا، فرماتی ہیں: میں سیدنا عثمان رضی اللہ عنہ کے لیے صبح کے وقت دودھ بلوتی تھی، جسے وہ شام کے وقت پی لیتے تھے، اور شام کے وقت نبیذ بناتی تھی جسے وہ صبح کے وقت پی لیتے تھے۔ انہوں نے مجھ سے ایک دن پوچھا: \"کیا تم اس میں کوئی چیز ملاتی ہو؟\" میں نے کہا: جی ہاں۔ انہوں نے کہا: \"دوبارہ ایسا نہ کرنا۔\"","",{"fn":"(1) اسد الغابہ (۷۵۵۱) تجرید (۳۳۱/۲)\n(2) ابن ماجہ (۳۹۲) المعجم الکبیر (۲۳۴/۲۵) الآحاد والمثانی (۳۴۷۲/۶)"}],[10796,"§۱۲۱۸۷ ۔ ام عیسیٰ بنت جزار\n(1) انہیں شرف صحابیت حاصل ہے اور عبدالرحمن بن جبلہ کے طریق سے بحوالہ ام فروہ بنت مزاحم عصریہ، وہ اپنی والدہ ام عیسیٰ بنت جزار، وہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتی ہیں، یہ ابن ماکولا(2) کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۵۲) تجرید (۳۳۱/۲)\n(2) الاکمال (۱۸۰/۲)"}],[10797,"§۱۲۱۸۸ ۔ ام عبداللہ\n(1) بنت عامر بن ربیعہ، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، یہ ام عبداللہ بنت ابوہشیمہ ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے، انہیں استدراک میں ذکر کرنے کی کوئی وجہ نہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۱۱) تجرید (۳۲۷/۲)"}],[10798,"§۱۲۱۸۹ ۔ ام عبداللہ بنت عمر\n(1) بن خطاب، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ان کی کنیت ام عبداللہ نہیں، اگر چہ ان کے بیٹے کا نام عبداللہ ہے، وہ اپنے نام اور نسب سے مشہور ہیں، وہ زینب بنت مظعون ہیں، عثمان اور قدامہ کی بہن ہیں جو مظعون کے بیٹے ہیں، اسماء میں صحیح گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۱۲) تجرید (۳۲۷/۲)"}],[10799,"§۱۲۱۹۰ ۔ ام غادیہ\nابوغادیہ کے سوانح میں ان کا ذکر گزر چکا ہے، ابن مندہ اور خطیب نے مؤتلف میں تمام بن بزیع کے طریق سے بحوالہ ام غادیہ روایت کیا، فرماتی ہیں: میں اپنے قبیلے کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے پاس گئی، جب میں واپس آنے لگی تو میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے وصیت کیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'بری باتوں سے بچو'(1)۔","",{"fn":"(1) جامع المسانید والسنن (۴۹۳/۱۶) اسد الغابہ (۴۷۹/۳)"}],[10800,"§۱۲۱۹۱ ۔ ام غطیف ہذلیہ\n(1) حرف غین میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۵۴) تجرید (۳۳۱/۲)"}],[10801,"§۱۲۱۹۲ ۔ ام غیلان دوسیہ\nجاہلیت میں ان کا ذکر ہے، انہوں نے اسلام کا زمانہ پایا، اور عمر بن خطاب رضی اللہ عنہ سے ملاقات کی۔ ابن کلبی، واقدی، اور زبیر بن بکار نے ان کا قصہ ذکر کیا ہے، قبیلہ دوس، مطیر کے حلیف تھے، ہشام بن مغیرہ جو حلیف تھا، انہوں نے ابوازہر دوسی کو قتل کر دیا، وہ ابو سفیان بن حرب کا حلیف تھا۔ دونوں فریقوں کے درمیان فساد پھیل گیا۔ انہوں نے ابوازہر دوسی کے خون کا بدلہ لینا چاہا، تو ابو سفیان نے انہیں منع کیا، تا کہ مسلمان خوش نہ ہوں۔ یہ ہجرت کے بعد کی بات ہے۔ جب اسلام آیا تو ابوازہر کا خون باطل ہو گیا۔ اس پر اتفاق ہے کہ قریش کے لوگ دوس کی سرزمین کی طرف نکلے، انہیں دوس کے لوگوں نے دیکھا، انہوں نے ابوازہر کے بدلے انہیں قتل کرنے کا ارادہ کیا، انہیں قبیلہ دوس کی ایک عورت نے جو عورتوں کا بناؤ سنگھار کرتی تھی، پناہ دی۔ اسے ام غیلان کہا جاتا ہے۔ وہ لوگ اس کی پناہ میں چلے گئے۔ جب سیدنا عمر رضی اللہ عنہ تشریف لائے تو وہ آپ رضی اللہ عنہ کے پاس آئیں اور کہنے لگیں: میرا آپ پر احسان ہے، میں نے آپ کے بھائی کو پناہ دی یعنی ضرار بن خطاب فہری کو۔ یہ ان لوگوں میں سے تھے جنہیں انہوں نے پناہ دی۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: وہ میرے حقیقی بھائی نہیں بلکہ اسلامی بھائی ہیں، پھر ان کی عزت کی۔ ابو عبیدہ نے یہ قصہ ذکر کیا ہے، لیکن فرمایا: ام جمیل ہیں۔"],[10802,"§۱۲۱۹۳ ۔ ام فروہ بنت ابوقحافہ تیمیہ\n(1) ابوبکر صدیق کی بہن ہیں، دارقطنی نے کتاب اخوۃ میں ان کا ذکر کیا ہے، فرماتے ہیں: ان سے ان کے بھائی اشعث بن قیس نے نکاح کیا، اسی طرح ابن سکن نے ذکر کیا ہے، فرماتے ہیں: اس سے ان کے ہاں محمد، اسحاق، وغیرہ پیدا ہوئے ہوئے۔ میں کہتا ہوں: تاریخ کی کتابوں میں ان کے نکاح کا قصہ مشہور ہے۔ ابن سعد رحمہ اللہ کا قول ہے(2): ان کی والدہ ہند بنت نفیل بن بجیر بن عبد بن قصی ہیں، فتح مکہ کے واقعے میں ان کا ذکر ہے، جب ان کا ہار گم ہو گیا تھا، ان سے ان کے بھائی نے ان سے فرمایا: آج امانت لوگوں میں کم ہو گئی ہے۔ ابن اسحاق نے اس کا ذکر کیا ہے، لیکن ان کا نام نہیں لیا، میرا خیال ہے یہ ام فروہ کے علاوہ ہیں، کیونکہ وہ اس قصے کے وقت کم عمر تھیں، اور اشعث سے ان کا نکاح فتح کے تین یا چار برس بعد ہوا۔ قریبہ بنت ابوقحافہ کا ذکر گزر چکا ہے۔ بعض کا قول ہے: یہ وہی ہیں جنہوں نے اول وقت میں نماز کی فضیلت کے بارے میں حدیث روایت کی۔ یہ ابن سکن(3) کا ظاہر فعل ہے، ابن عبدالبر نے اسی کو ترجیح دی ہے، اس میں تردد ہے، راجح یہ ہے کہ یہ اس کے علاوہ ہیں۔ ابن مندہ نے اس کا یقین کیا ہے کہ بنت ابوقحافہ کا ذکر ہے لیکن حدیث مروی نہیں، حدیث صلاۃ کی روایت کرنے والی انصاریہ ہیں۔ حدیث کا مدار قاسم بن غنام پر ہے، یہ ان کی دادی یا پھوپھی ہیں، یا ان کی والدہ ہیں، یا ان کے گھر والوں میں سے ہیں۔ اس بارے میں ان سے مروی حدیث میں راویوں کے اختلاف سے معلوم ہوا کہ کسی طرح بھی یہ ابوبکر صدیق رضی اللہ عنہ کی بہن نہیں، یہ ابن اثیر(4) کا قول ہے۔ میں کہتا ہوں: بخاری میں ابو عمر نے اخت ابوبکر کا ذکر کیا ہے، جب انہوں نے چیخ و پکار کی، کتاب حدود میں اسی طرح تعلیقاً ان کا ذکر کیا ہے۔ اسحاق بن راہویہ نے اپنی مسند میں سعید بن مسیب کے طریق سے موصولاً ان کا ذکر کیا ہے۔ فرماتے ہیں: جب سیدنا ابوبکر رضی اللہ عنہ کی وفات ہوئی تو لوگ روئے، سیدنا عمر رضی اللہ عنہ نے ہشام بن ولید سے فرمایا: کھڑے ہو اور عورتوں کو باہر نکالو۔۔۔۔ (الحدیث) اس میں ہے: تو وہ ایک ایک کر کے خواتین کو باہر بھیجنے لگے، یہاں تک کہ ام فروہ باہر نکلیں، باقی طرق ہشام بن ولید کے سوانح میں گزر چکے ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۵۷) تجرید (۳۳۱/۲)\n(2) طبقات کبریٰ (۱۸۱/۸)\n(3) مسند احمد (۳۷۵/۴) سنن دارقطنی (۲۴۸/۱) مستدرک حاکم (۱۹۰/۱)\n(4) اسد الغابہ (۴۸۱/۵)"}],[10803,"§۱۲۱۹۴ ۔ ام فروہ انصاریہ\n(1) قاسم بن غنام کی پھوپھی ہیں، ابن سعد رحمہ اللہ(2) کا قول ہے: ابوداؤد، ترمذی نے عبداللہ عمری مکبر ضعیف کے طریق سے بحوالہ ام فروہ روایت کیا، یہ روایت ابوداؤد کی ہے، ان کی ایک اور روایت ان کی پھوپھی سے مروی ہے، جنہیں ام فروہ کہا جاتا ہے۔ ترمذی کی روایت میں بحوالہ ان کی پھوپھی ام فروہ سے مروی ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ترمذی کا قول ہے: حدیث عمری کے علاوہ ان سے حدیث مروی نہیں۔ اس حدیث میں اضطراب ہے۔ مسند احمد(3) میں بحوالہ ام فروہ مروی ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم سے پوچھا گیا کہ کون سا عمل سب سے افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اول وقت نماز پڑھنا'۔ اسے ابن سکن نے عبید اللہ بن عمیر ثقفہ کے طریق سے بحوالہ ام فروہ روایت کیا ہے۔ وہ ان لوگوں میں سے ہیں جنہوں نے درخت کے نیچے بیعت کی تھی۔ فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا۔۔۔ پھر ان کا ذکر کیا۔ ابن سکن کا قول ہے: ان دونوں سے اسناد میں اختلاف ہے۔ یہ ترمذی کے اطلاق پر رد ہے۔ دارقطنی، حاکم نے عبید اللہ مصغر کے اس سے نقل کیا ہے۔ قاسم کے بارے میں فرماتے ہیں: ان کی دادی دنیا کے حوالے سے انہوں نے اپنی دادی ام فروہ سے روایت کیا ہے۔ ابن سکن کا کلام عمر بن کے الگ ذکر کرنے میں قاسم کے حوالے سے وہم میں ڈالتا ہے۔ ابن ابوفدیک کی روایت سے بحوالہ قاسم اس پر رد ہوتا ہے لیکن فرمایا: بحوالہ بیعت کرنے والیوں میں سے ایک خاتون، اور ان کا نام نہیں لیا، اسے طبرانی(4) نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۵۶) تجرید (۳۳۱/۲)\n(2) طبقات کبریٰ (۲۲۲/۸)\n(3) مسند احمد (۳۷۴/۶)\n(4) المعجم الکبیر (۲۱۱/۲۵)"}],[10804,"§۱۲۱۹۵ ۔ ام فزار\n(1) ذہبی رحمہ اللہ نے اپنی کتاب تجرید میں ان کا ذکر کیا ہے۔ فرماتے ہیں: زید بن حارثہ نے جذام کے لوگوں کو گرفتار کیا تو ان میں یہ بھی تھیں۔","",{"fn":"(1) تجرید (۳۳۱/۲)"}],[10805,"§۱۲۱۹۶ ۔ ام فضل\n(1) عباس بن عبدالمطلب کی زوجہ ہیں، ان کا نام لبابہ بنت حارث ہلالیہ ہے، یہ لبابہ کبریٰ ہیں، ان کی بہن لبابہ صغریٰ میں ان کا نسب گزر چکا ہے۔ ایک قول کے مطابق ہجرت سے قبل اسلام لائیں، بعض نے کہا: اس کے بعد اسلام لائیں۔ ابن سعد رحمہ اللہ(2) کا قول ہے: ام فضل پہلی خاتون ہیں جو سیدہ خدیجہ رضی اللہ عنہا کے بعد اسلام لائیں، اور نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ان کے بیٹے عبداللہ، تمام اور عمیر بن حارث، ان کے مولیٰ، ان کے بیٹے کے مولیٰ کریب نے اور سیدنا عبداللہ بن عباس نے اور عبداللہ بن حارث بن نوفل اور دوسرے لوگوں نے روایت کی۔ زبیر بن بکار وغیرہ نے ابراہیم بن عقبہ کے طریق سے بحوالہ ابن عباس، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی: 'چار بہنیں ایمان لانے والی ہیں، ام فضل، میمونہ، اسماء اور سلمیٰ۔' سیدہ میمونہ ام المؤمنین اور ام فضل کی سگی بہن ہیں۔ رہیں اسماء اور سلمیٰ تو وہ ان کی باپ شریک بہنیں اور عمیس خثعمیہ کی بیٹیاں ہیں۔ اسے واقدی رحمہ اللہ نے اپنی سند سے بحوالہ کریب ذکر کیا ہے۔ میمونہ اور ام فضل اور ان کی بہنیں بکر، عزہ، اسماء، سلمیٰ کا ذکر ہو تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'بے شک مومن بہنیں ہیں'۔ ابن سعد نے جید سند سے بحوالہ سماک بن حرب نقل کیا ہے کہ ام فضل نے کہا: یا رسول اللہ! میں نے دیکھا ہے کہ آپ کے اعضاء میں سے ایک عضو میرے گھر ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'فاطمہ کے ہاں لڑکا ہو گا تم اسے قثم کے دودھ کے ساتھ دودھ پلاؤ گی۔' سیدہ فاطمہ رضی اللہ عنہا کے ہاں حسین پیدا ہوئے، میں نے انہیں اٹھا لیا، ایک دفعہ آپ انہیں چوم رہے تھے کہ انہوں نے پیشاب کر دیا۔ میں نے چٹکی لگائی تو رو پڑے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میرے بیٹے کی وجہ سے تم نے مجھے تکلیف دی۔ پھر پانی منگوایا اور اچھی طرح بہا دیا۔ قابوس بن مخارق کے طریق سے اسی طرح مروی ہے، اس میں ہے: انہوں نے دودھ پلایا یہاں تک کہ وہ چلنے پھرنے لگا، وہ انہیں لے کر نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور انہیں آپ صلی اللہ علیہ وسلم کی گود مبارک بٹھا دیا، انہوں نے پیشاب کر دیا تو انہوں نے ان کے دونوں کندھوں کے درمیان مارا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'تم نے میرے بیٹے کے بارے میں مجھے تکلیف میں ڈالا، اللہ تم پر رحم کرے۔۔۔' (الحدیث) ام فضل کے بارے میں کہا جاتا تھا، حرشیہ بوڑھی، معزز دامادوں والی ہے۔ سیدہ میمونہ نبی کریم صلی اللہ علیہ وسلم کی زوجہ، عباس نے ان کی سگی بہن لبابہ سے نکاح کیا، سیدنا حمزہ رضی اللہ عنہ نے ان کی بہن سلمیٰ سے نکاح کیا، جعفر بن ابوطالب نے ان کی سگی بہن اسماء سے نکاح کیا، پھر ان سے بعد میں سیدنا ابوبکر صدیق رضی اللہ عنہ نے اور اس کے بعد سیدنا علی رضی اللہ عنہ نے نکاح کیا۔ ابو عمر کا قول ہے: نیک بخت خواتین میں سے تھیں۔ نبی کریم صلی اللہ علیہ وسلم ان کی ملاقات کے لیے تشریف لے جاتے۔ صحیح میں ہے کہ عرفہ کے دن لوگ نبی کریم صلی اللہ علیہ وسلم کے روزے کے بارے میں شک میں تھے، ام فضل نے ایک پیالہ دودھ کا بھیجا، آپ صلی اللہ علیہ وسلم نے موقف میں اسے پیا، تو لوگوں نے جان لیا کہ آپ صلی اللہ علیہ وسلم روزے سے نہیں۔ ابن حبان کا قول ہے: سیدنا عثمان رضی اللہ عنہ کے عہد خلافت میں اپنے شوہر سیدنا عباس رضی اللہ عنہ سے پہلے وفات پا گئیں۔","",{"fn":"(1) اسد الغابہ (۷۵۵۸) تجرید (۳۳۱/۲)\n(2) طبقات کبریٰ (۲۰۲/۸)"}],[10806,"§۱۲۱۹۷ ۔ ام فضل بنت حمزہ\n(1) بن عبدالمطلب بن ہاشم، ابوعمر کا قول ہے: ان سے عبداللہ بن شداد نے روایت کی کہ وہ فرماتی ہیں: ہمارا مولیٰ فوت ہو گیا، اس نے ایک بیٹی اور ایک بہن چھوڑی۔ وہ دونوں نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔ آپ صلی اللہ علیہ وسلم نے نصف بیٹی کو اور نصف بہن کو دیا، اسی طرح ایک قول ہے۔ ابن مندہ نے دو طریق سے حدیث نقل کی ہے۔ بحوالہ حارثہ بن یزید جعفی جو ضعیف راوی ہیں، بحوالہ ام فضل بنت حمزہ، فرماتی ہیں: ان کا ایک آزاد کردہ غلام فوت ہو گیا، اس نے ایک بیٹی کو چھوڑا، نبی کریم صلی اللہ علیہ وسلم نے اس کی میراث ام فضل اور اس کی بیٹی کے درمیان آدھی آدھی تقسیم کر دی۔","",{"fn":"(1) اسد الغابہ (۷۵۵۹) تجرید (۳۳۱/۲)"}],[10807,"§۱۲۱۹۸ ۔ ام فضل بنت عباس\n(1) بن عبدالمطلب ہاشمیہ، مستغفری نے بحوالہ بخاری ذکر کیا ہے کہ انہوں نے بنو ہاشم کی خواتین میں سے نبی کریم صلی اللہ علیہ وسلم سے روایت کرنے والوں میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے جائز قرار دیا ہے کہ وہ ام فضل سیدنا عباس رضی اللہ عنہ کی زوجہ ہیں، جن کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۶۰) تجرید (۳۳۱/۲)"}],[10808,"§۱۲۱۹۹ ۔ ام فروہ\n(1) نبی کریم صلی اللہ علیہ وسلم کو دودھ پلایا، مستغفری نے اس کا ذکر کیا ہے اور اسحاق بن ابو اسرائیل کے طریق سے بحوالہ ام فروہ روایت کیا ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا۔ فرماتی ہیں: مجھ سے نبی کریم صلی اللہ علیہ وسلم نے فرمایا: 'جب تم بستر پر آؤ تو یہ پڑھو ﴿قُلْ یٰۤاَیُّہَا الْکٰفِرُوْنَ﴾(2) یہ شرک سے براءت ہے۔' ابو موسیٰ کا قول ہے: اس حدیث کے راوی کے بارے میں اختلاف ہے۔ بعض کا قول ہے: فروہ، بعض نے کہا: ابوفروہ، کسی نے کہا: نوفل، یہ قول یعنی ام فروہ، یہ سب سے غریب قول ہے۔ میں کہتا ہوں: بلکہ وہ محض غلط ہے، وہ ابوفروہ ہیں۔ گویا بعض راویوں نے جب دیکھا بحوالہ ابوفروہ نبی کریم صلی اللہ علیہ وسلم کے رضاعی والد تو انہوں نے اسے غلط سمجھا۔ صحیح یہ ہے کہ ام فروہ ہیں، انہوں نے اپنے گمان کے مطابق اسے روایت کیا ہے تو انہوں نے خطا کر دی۔ ظئر کا لفظ دودھ پلانے والی عورت کے ساتھ خاص نہیں ہے، بلکہ اس کے شوہر پر بھی اس کا اطلاق ہوتا ہے۔ اسے اصحاب سنن ثلثہ نے کئی طریق سے بحوالہ فروہ بن نوفل انہوں نے اپنے والد سے روایت کیا ہے۔ ان میں سے بعض کا قول ہے: بحوالہ ان کے والد، بعض نے کہا: بحوالہ ابواسحاق، انہوں نے ابوفروہ سے روایت کیا ہے، صحیح یہ ہے: بحوالہ فروہ، انہوں نے اپنے والد سے روایت کیا ہے۔ اسی طرح ابوداؤد، نسائی نے زہیر بن معاویہ کی روایت سے ترمذی، نسائی نے بھی اسرائیل کی روایت سے اسے نقل کیا ہے، دونوں نے بحوالہ ابو اسحاق حروفوں میں نقل کیا ہے، اس میں ابو اسحاق پر اختلاف ہے، یہی قول قابل اعتماد ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۵۵) تجرید (۳۳۱/۲)\n(2) سورۃ الکافرون الآیۃ (۱)"}],[10809,"§۱۲۲۰۰ ۔ ام قاسم بنت ذی الجناحین\nجعفر بن ابوطالب ہاشمیہ، بغوی نے اپنی مسند سے جسے وہ ام نعمان بنت مجمع بن یزید انصاریہ تک لے گئے ہیں، ان کا ذکر کیا ہے۔ فرماتی ہیں: مجھے مجمع بن یزید نے بتایا، فرماتے ہیں: جب ام قاسم بنت ذی الجناحین سیدنا حمزہ رضی اللہ عنہ کی زوجہ بیوہ ہو گئیں، تو انہوں نے ابو بکر بن عبدالرحمن اور قاسم بن محمد اور یزید کے بیٹوں عبدالرحمن اور مجمع قریش کے دو مردوں اور انصار کے دو مردوں کو بلایا، اور انہیں کہنے لگیں: میں بیوہ ہو گئی ہوں، جیسا کہ آپ دیکھ رہے ہیں، مجھے وارثوں سے خدشہ ہے کہ وہ میرا نکاح اس شخص سے کر دیں جسے میں پسند نہیں کرتی، میں تم لوگوں کو گواہ بناتی ہوں کہ جس سے میرا نکاح میری اجازت کے بغیر کر دیا، میں اس پر حرام ہوں اور میں اس کی بیوی نہیں۔ تو ان سے عبدالرحمن اور مجمع نے ان سے کہا: اگر انہوں نے ایسا کیا تو تمہارے لیے جائز نہیں، حالانکہ خنساء بنت خدام کا نکاح ان کے والد نے ان کی مرضی کے خلاف کر دیا تھا۔ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں تو رسول اللہ صلی اللہ علیہ وسلم نے ان کے والد کا کیا ہوا نکاح رد کر دیا، وہ شیب تھیں، جہاں تک ہمیں معلوم ہے۔ میں کہتا ہوں: معجم بغوی میں مجمع بن یزید کے سوانح میں، میں نے اسی طرح لکھا پایا اور حمزہ کا نسب بیان نہیں کیا، مجھے خدشہ ہے کہ فاطمہ بنت قاسم بن محمد بن جعفر کی کنیت ام قاسم ہے، اس روایت میں وہ اپنے جد اعلیٰ جعفر بن ابوطالب کی طرف منسوب ہیں، یہ خیال اس لیے مستند ہے کہ زبیر بن بکار قریش کے نسب جاننے میں سب سے مقدم ہیں۔ انہوں نے جعفر بن ابوطالب کی اولاد میں بیٹی کا ذکر نہیں کیا، جسے ام قاسم کہا جاتا ہو، انہوں نے عبداللہ بن جعفر کی اولاد میں فاطمہ بنت قاسم بن محمد بن جعفر کا ذکر کیا، وہ حمزہ بن عبداللہ بن جعفر کی زوجہ تھیں۔ سیدنا معاویہ رضی اللہ عنہ نے ان ام کلثوم کو اپنے بیٹے یزید کے لیے نکاح کا پیغام دیا، انہوں نے اپنا معاملہ حسین بن علی کے سپرد کر دیا، انہوں نے ان کے چچا زاد قاسم بن محمد بن جعفر سے ان کا نکاح کر دیا، جس سے فاطمہ کی ولادت ہوئی، ان سے حمزہ بن عبداللہ بن زبیر نے اپنے والد کی خلافت میں ان سے نکاح کیا۔ سیدنا زبیر رضی اللہ عنہ نے فرمایا: ان فاطمہ کی حمزہ بن عبداللہ اور باقی اولاد سے نسل چلی۔ میں نے اسے احتمال کی وجہ سے لکھ دیا ہے۔ واللہ اعلم!"],[10810,"§۱۲۲۰۱ ۔ ام قرہ\n(1) دعموص کی زوجہ ہیں، ابن مندہ کا قول ہے ان کا ذکر ہے۔(2) ان کی حدیث گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۶۲) تجرید (۲۳۲/۲)\n(2) اسد الغابہ (۴۸۲/۵)"}],[10811,"§۱۲۲۰۲ ۔ ام قہطم\nفاطمہ بنت علقمہ ہیں، اسماء میں ان کا نام گزر چکا ہے۔"],[10812,"§۱۲۲۰۳ ۔ ام قیس بنت عبید\nبن زیاد بن ثعلبہ بن خنساء بن مبذول، بنو مازن بن نجار سے ہیں۔ ابن سعد نے ان کا ذکر کیا ہے۔(1) فرمایا: ان کی والدہ ام عبداللہ بنت شبیل بن حارث بن عوف ہیں، ان سے ابوسلیط بن ابو حارثہ نے نکاح کیا، جس سے ابوسلیط اور فاطمہ پیدا ہوئے۔ فرماتے ہیں: ام قیس اسلام لائیں اور خیبر وغیرہ میں حاضر ہوئیں۔","",{"fn":"(1) طبقات الکبریٰ (۳۰۶/۸)"}],[10813,"§۱۲۲۰۴ ۔ ام قیس بنت قیس\n(1) انصاریہ۔ بعض کا قول ہے: عدویہ، بعض نے کہا: ان کا نام سلمیٰ ہے۔ تجرید میں ہے کہ انہوں نے دونوں قبلوں کی طرف نماز پڑھی۔","",{"fn":"(1) تجرید (۳۳۲/۲)"}],[10814,"§۱۲۲۰۵ ۔ ام قیس بنت محصن\n(1) اسدیہ۔ عکاشہ بن محصن کی بہن ہیں، اسماء الرجال میں عکاشہ کے سوانح میں ان کا نسب گزر چکا ہے۔ مکہ میں ابتدائی دور میں اسلام لانے والوں میں سے تھیں۔ بیعت ہوئیں اور ہجرت کی۔ بعض کا قول ہے: ان کا نام امیہ ہے، اسے ابو قاسم جوہری نے مسند موطا میں بیان کیا ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی۔ ان سے عبید اللہ بن عبد اللہ بن عتبہ نے روایت کی کہ وہ اپنے چھوٹے بیٹے کو جو ابھی کھانا نہیں کھاتا تھا، لے کر آئیں۔۔۔۔ (الحدیث)(2) بخاری و مسلم دونوں نے اسے صحیحین میں نقل کیا ہے، ان سے مروی ہے کہ وہ اپنے بیٹے کو لے کر آئیں جن کے گلے میں انہوں نے تعویذ لٹکایا ہوا تھا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: تم عورتیں! اپنے بچوں کے بارے میں کیوں خوفزدہ رہتی ہو؟ (الحدیث) ان سے وابصہ بن معبد نے بھی روایت کی، اور ان کے مولیٰ عدی بن دینار اور ان کے مولیٰ ابو حسن نے، ابو عبیدہ بن عبد اللہ بن زمعہ، عمرہ حضرت نافع مولیٰ حمنہ کی بہن وغیرہ نے روایت کی۔ نسائی نے لیث کے طریق سے بحوالہ ام قیس روایت کیا ہے۔ فرماتی ہیں: میرا بیٹا فوت ہو گیا، میں جزع فزع کرنے لگی، اور غسل دینے والے سے کہا: میرے بیٹے کو ٹھنڈے پانی سے غسل نہ دو تم اسے مار دو گے۔ سیدنا عکاشہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اسے کیا ہوا؟ اس کی عمر لمبی ہو'۔ فرماتے ہیں: معلوم نہیں کہ جتنی لمبی ان کی عمر ہوئی، اتنی کسی اور کی عمر ہو۔","",{"fn":"(1) اسد الغابہ (۷۵۶۳) تجرید (۳۳۲/۲)\n(2) ترمذی (۷۱)"}],[10815,"§۱۲۲۰۶ ۔ ام قیس\nبعض کا قول ہے: ام ہانی انصاریہ عقیلی نے ان کا ذکر کیا ہے اور ابن لہیعہ کے طریق سے بحوالہ درہ بنت معاذ نقل کیا ہے کہ انہوں نے ان کو بحوالہ ام قیس انصاریہ بتایا کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، کہنے لگیں: جب ہم مر جائیں کیا ہم آپس میں ملاقات کریں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: روح پرندے کی شکل میں جنت میں بسیرا کرتی ہے: جب قیامت کا دن ہو گا، تو ہر روح اپنے جسم میں داخل کی جائے گی۔ اسے ابن ابو خیمہ نے ابن لہیعہ کے طریق سے نقل کیا ہے، فرماتے ہیں: ام ہانی، ان کا ذکر آگے آئے گا۔"],[10816,"§۱۲۲۰۷ ۔ ام قیس (بے نسبت)\n(1) ابن مندہ اور ابونعیم نے اسماعیل بن عصام بن یزید کے طریق سے نقل کیا ہے، فرماتے ہیں: میں نے اپنے دادا یزید جنہیں حمر کہا جاتا تھا، کی کتاب میں پایا، ہم سے سفیان بن اعمش نے بحوالہ ابن مسعود روایت کیا ہے، فرماتے ہیں: ہمارے خاندان کے ایک شخص نے ام قیس نامی خاتون کو نکاح کا پیغام دیا، انہوں نے نکاح کرنے سے انکار کیا، یہاں تک کہ ہجرت کریں، انہوں نے ہجرت کی اور ان سے نکاح کیا، ہم انہیں مہاجر ام قیس کہا کرتے تھے۔(2) ابن مسعود کا قول ہے: جس نے کسی چیز کے لیے ہجرت کی تو وہ اسی کے لیے ہے۔ ابونعیم کا قول ہے: عبدالملک زماری نے بحوالہ سفیان اس کی پیروی کی ہے۔ اس سے ابوموسیٰ کے اس اشارہ کی تردید ہوتی ہے کہ وہ حمر کے ایک فرد ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۶۴) تجرید (۳۳۲/۲)\n(2) اسد الغابہ (۴۸۳/۵)"}],[10817,"§۱۲۲۰۸ ۔ ام قیس ہذلیہ\n(1) ابوموسیٰ کا قول ہے: جعفر نے ان کا ذکر کیا ہے، ان سے کوئی حدیث روایت نہیں کی۔(2) میں کہتا ہوں: مجھے خدشہ ہے کہ یہ پہلے والی ہوں، کیونکہ ابن مسعود مہاجر ام قیس کے بارے میں فرماتے ہیں: ہم میں سے ایک شخص ہیں اور ابن مسعود ہذلی ہیں، گویا ام قیس جنہیں نکاح کا پیغام دیا گیا تھا وہ بھی ہذلیہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۶۵) تجرید (۳۳۲/۲)\n(2) اسد الغابہ (۴۸۳/۵)"}],[10818,"§۱۲۲۰۹ ۔ ام قرفہ\nام سلمیٰ میں ان کا ذکر گزر چکا ہے۔"],[10819,"§۱۲۲۱۰ ۔ ام قرثع\n(1) ام زفر میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۶۱) تجرید (۳۳۱/۲)"}],[10820,"§۱۲۲۱۱ ۔ ام کبشہ قضاعیہ\n(1) ابن ابو عاصم(2) نے وحدان میں ان کا ذکر کیا ہے۔ ابوبکر بن ابو شیبہ، مطین، طبرانی وغیرہ نے ان کی حدیث نقل کی ہے۔ بطریق اسود بن قیس، بحوالہ سعید بن عمرو قرشی کہ ام کبشہ قضاعہ کی ایک خاتون ہیں، فرماتی ہیں: یا رسول اللہ صلی اللہ علیہ وسلم مجھے فلاں فلاں لشکر کے ساتھ نکلنے کی اجازت دیجئے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'نہیں'۔ کہنے لگیں: میں جہاد میں شرکت نہیں کرنا چاہتی بلکہ میں زخمیوں اور مریضوں کا علاج اور پانی پلانا چاہتی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اگر یہ سنت نہ ہو جاتی اور لوگ کہنے لگتے کہ فلاں جہاد میں نکلی تو میں تمہیں اجازت دے دیتا تم گھر میں قرار پکڑو۔' اسے ابن سعد(3) نے بحوالہ ابن ابوشیبہ روایت کیا ہے، اس کے آخر میں ہے: 'گھر میں ٹھہری رہو، لوگ یہ نہ کہنے لگیں کہ محمد عورت کو ساتھ لے جا کر جہاد کرتے ہیں۔' اس روایت اور جو ام سنان اسلمیہ کے سوانح میں گزری، ان دونوں کو جمع کرنا ممکن ہے کہ یہ اس روایت کے لیے ناسخ ہے، کیونکہ یہ خیبر کا قصہ ہے۔ اس سے پہلے احد میں یہ قصہ گزر چکا ہے جو کہ بروایت براء بن عازب صحیح میں مذکور ہے۔ یہ فتح کے بعد کا قصہ ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۶۶) تجرید (۳۳۲/۲)\n(2) الآحاد والمثانی (۳۲۷۳/۶)\n(3) طبقات الکبریٰ (۲۲۶/۸)"}],[10821,"§۱۲۲۱۲ ۔ ام کثیر بنت زید انصاریہ\n(1) ابونعیم نے ان کا ذکر کیا ہے اور احمد بن سہیل وراق کے طریق سے بحوالہ ام کثیر بنت یزید انصاریہ نقل کیا ہے۔ فرماتی ہیں: میں اور میری بہن نبی کریم صلی اللہ علیہ وسلم کے پاس گئے، میں نے ان سے کہا: میری بہن آپ سے کچھ پوچھنا چاہتی ہے وہ پوچھنے میں حیا کرتی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'اسے پوچھنا چاہیے، کیونکہ علم حاصل کرنا فرض ہے۔' فرماتی ہیں: میں نے آپ صلی اللہ علیہ وسلم سے پوچھا یا آپ صلی اللہ علیہ وسلم سے میری بہن نے پوچھا کہ میرا ایک بیٹا ہے جو حمام میں کھیلتا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'وہ منافقوں کا کھیلنا ہے'(2)۔","",{"fn":"(1) اسد الغابہ (۷۵۶۷) تجرید (۳۳۲/۲)\n(2) جامع المسانید والسنن (۵۱۶/۱۶) اسد الغابہ (۴۸۴/۵)"}],[10822,"§۱۲۲۱۳ ۔ ام کجہ انصاریہ\n(1) واقدی نے بحوالہ کلبی اپنی تفسیر میں ذکر کیا ہے، بحوالہ ابو صالح، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کیا کہ اوس بن ثابت انصاری وفات پا گئے اور تین بیٹیاں اور ایک بیوی ام کجہ چھوڑی، اس شخص کے دو چچا زاد سوید اور عرفجہ نے اس کے مال پر قبضہ کر لیا اور اس کی بیوی اور بیٹیوں کو کچھ نہ دیا، تو ام کجہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، اور آپ صلی اللہ علیہ وسلم سے اس کا ذکر کیا، اس پر میراث کی آیت نازل ہوئی۔(2) یہ روایت طویل مروی ہے اور یہ اس کی تلخیص ہے۔ اختلاف کا بیان ان کے دونوں چچا زادوں کے ناموں میں، اور بن ثابت کے سوانح میں گزر چکا ہے۔ ابونعیم اور ابو موسیٰ نے اپنے طریق سے پھر سفیان کی روایت سے بحوالہ جابر نقل کیا ہے، فرماتے ہیں: ام کجہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! میری دو بیٹیاں ہیں، ان کا باپ فوت ہو چکا ہے، اس کی کوئی چیز نہیں، اللہ تعالیٰ نے آیت نازل فرمائی: ﴿مردوں کے لیے اس ترکے میں سے حصہ ہے جو والدین اور رشتہ دار چھوڑ مریں اور عورتوں کے لیے اس ترکے میں سے حصہ ہے، جو والدین اور رشتہ دار چھوڑ مریں کی۔﴾(3) پھر اللہ تعالیٰ نے یہ ارشاد فرمایا: ﴿اللہ تعالیٰ تمہیں تمہاری اولاد کے بارے میں (وراثت کا یہ حکم دیا ہے کہ) مرد کے لیے عورت سے دو گنا حصہ ہے۔﴾(4) ابو موسیٰ کا قول ہے، ان کے پاس کوئی شے نہیں، اس سے مراد یہ ہے کہ انہیں ان کے والد کی میراث سے کوئی چیز نہیں ملی۔ میں کہتا ہوں: سفیان سے روایت ضعیف ہے، وہ ابراہیم بن ہراسہ ہیں، بشر بن مفضل نے بحوالہ جابر ان کی مخالفت کی ہے۔ اسے ابو داؤد(5) نے اپنے طریق سے نقل کیا ہے۔ فرماتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ باہر نکلے، یہاں تک کہ بازار میں ہم انصار کی ایک خاتون کے پاس پہنچے۔ وہ اپنی دو بیٹیوں کو لے آئیں اور کہنے لگی: یا رسول اللہ صلی اللہ علیہ وسلم! یہ دونوں ثابت بن قیس کی بیٹیاں ہیں جو احد کے دن آپ صلی اللہ علیہ وسلم کے ساتھ شریک تھے اور شہید ہوئے، ان کے چچا نے اس کا سارا مال لے لیا ہے، اور ان کے لیے کچھ بھی نہیں چھوڑا۔ یا رسول اللہ صلی اللہ علیہ وسلم! آپ کی کیا رائے ہے؟ اللہ کی قسم! ان سے کوئی نکاح نہ کرے گا جب تک ان کے پاس مال نہ ہو۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اللہ تعالیٰ اس بارے میں فیصلہ کرے گا'۔ راوی فرماتے ہیں: یہ آیت نازل ہوئی: ﴿اللہ تعالیٰ تمہیں تمہاری اولادوں کے بارے میں وصیت کرتا ہے۔۔۔۔﴾ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'میرے پاس اس عورت اور اس کے رشتہ دار کو بلاؤ'۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'ان دونوں کو دو تہائی دو اور ان کی والدہ کو آٹھواں حصہ دو، اس کے علاوہ باقی تمہارا ہے۔' ابوداؤد نے فرمایا: یہ خطا ہے، کیونکہ وہ دونوں سعد بن ربیع کی بیٹیاں ہیں۔ رہے ثابت بن قیس تو وہ یمامہ میں شہید ہوئے، پھر اسے ابن وہب کے طریق سے نقل کیا ہے، مجھے اہل علم میں سے داؤد بن قیس وغیرہ نے بحوالہ جابر بتایا کہ سیدنا سعد بن ربیع کی زوجہ کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! سعد وفات پا چکے ہیں، اور دو بیٹیاں چھوڑی ہیں۔۔۔ پھر اسی طرح نقل کیا۔ اسے ترمذی اور حاکم نے عبید اللہ بن عمر ورقی کے طریق سے بحوالہ سیدنا جابر رضی اللہ عنہ روایت کیا، فرماتے ہیں: سیدنا سعد بن ربیع کی زوجہ ان کی دو بیٹیوں کو لے کر آئی۔۔۔ پھر اسی طرح ذکر کیا۔ ابو داؤد نے اس کے غلط ہونے پر بھروسہ ظاہر کیا ہے۔ اور اسی کا محدثین کے قواعد احتمال کے ساتھ تقاضا کرتے ہیں۔ فوت ہونے والے شخص کے نام میں اختلاف ہے۔ بعض نے کہا: ثابت بن قیس، بعض کا قول ہے: اوس بن ثابت جیسا کہ پہلے گزر چکا ہے۔ بعض کا قول ہے: اوس بن مالک، جس شخص نے مال جمع کیا تھا، اس کے نام میں بھی اختلاف ہے، جیسا کہ اوس بن ثابت کے سوانح میں گزر چکا ہے۔ جو اختلاف پہلے نہیں گزرا وہ یہی ہے کہ طبری نے بطریق ابن جریج بحوالہ عکرمہ نقل کیا ہے، فرماتے ہیں: یہ ام کجہ اور بنت ام کجہ، ثعلبہ، اوس بن ثابت کے بارے میں نازل ہوئی، وہ انصار میں سے ہیں، ان دونوں میں سے ایک ان کا شوہر ہے اور دوسرا ان کی اولاد کا چچا ہے۔ فرماتی ہیں: یا رسول اللہ صلی اللہ علیہ وسلم! میرا شوہر فوت ہو گیا، ہمیں اس حال میں چھوڑا کہ ہم کسی چیز کے وارث نہیں۔ تو اس کے بچوں کے چچا نے کہا: یہ نہ گھوڑے پر سوار ہو گی، نہ کسی کی امداد کرے گی اور نہ دشمن کا دفاع کرے گی۔ یہ روایت ابن ابی حاتم نے بطریق محمد بن ثور بواسطہ ابن جریج بحوالہ ابن عباس رضی اللہ عنہ نقل کی ہے کہ ام کلثوم، بنت کجہ، ثعلبہ بن اوس اور سوید کے بارے آیت نازل ہوئی پھر اس کا مفہوم ذکر کیا۔ اور بطریق اسباط بحوالہ السدی مروی ہے کہ اہل جاہلیت لڑکیوں اور کمزور مردوں کو وارث نہیں بناتے تھے۔ سیدنا عبدالرحمن جو سیدنا حسان شاعر کے بھائی تھے ان کا انتقال ہوا تو ان کے ورثاء میں ان کی بیوی ام کجہ اور پانچ لڑکیاں تھیں۔ ان کے رشتہ دار آئے اور سارا مال لے گئے۔ ام کجہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کی شکایت کر دی تو اللہ تعالیٰ نے یہ آیت نازل فرمائی: ﴿اگر ورثاء میں دو سے زائد لڑکیاں ہوں تو انہیں ترکے کا دو تہائی دیا جائے﴾۔(6) رہی عورت تو اس کے متعلق کسی کا اختلاف نہیں، وہ ام کجہ ہی ہیں، صرف ابو موسیٰ نے بحوالہ مستغفری ام کحلہ اور جو پہلے ابن جریج کی دونوں روایتوں میں بنت کجہ گزرا ہے۔ لہذا احتمال ہے کہ ان کی کنیت ان کے والد کے نام یا ان کی بیٹی کے نام جیسی ہے۔ ابن جریج کی روایت سے معلوم ہوتا ہے کہ وہ ام کلثوم ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۶۸) تجرید (۳۳۲/۲)\n(2) تفسیر ابن کثیر (۱۹۱/۲) اسد الغابہ (۴۸۵/۵)\n(3) سورۃ النساء الآیۃ (۷)\n(4) سورۃ النساء الآیۃ (۱۱)\n(5) ابوداؤد (۲۸۹۱)\n(6) سورۃ النساء (۱۱)"}],[10823,"§۱۲۲۱۴ ۔ ام کرام سلمیہ\n(1) بقول ابوعمر نبی صلی اللہ علیہ وسلم سے عورتوں کے لیے سونا پہننے کی کراہت والی حدیث نقل کی ہے، ان سے حکم بن جحل نے روایت کی ہے، ان کی حدیث کی سند مضبوط نہیں۔","",{"fn":"(1) اسد الغابہ (۷۵/۷۹) تجرید (۳۳۲/۲)"}],[10824,"§۱۲۲۱۵ ۔ ام کرز خزاعیہ\n(1) ثم کعبیہ۔ بقول ابن سعد(2): مکیہ۔ حدیبیہ کے روز اس وقت مسلمان ہوئیں جب نبی علیہ السلام اپنے جانوروں کا گوشت تقسیم کر رہے تھے۔ عقیقہ کے بارے میں ان کی حدیث ہے جسے سنن اربعہ کے مصنفین نے نقل کیا ہے۔ ان سے ابن عباس(3)، عطاء، طاؤس، مجاہد، سباع بن ثابت، عروہ وغیرہ روایت کرتے ہیں۔ عطا سے آگے ان کی حدیث میں اختلاف ہے، کسی نے قتادہ سے بواسطہ ان کے، ابن عباس رضی اللہ عنہ سے بحوالہ ان کے اور کسی نے ابن جریج اور محمد بن اسحاق اور احمد بن دینار سے بواسطہ عطاء انہوں نے حبیبہ بنت میسرہ بن ابی حبیب بحوالہ ان کے، بقول بعض حجاج بن ارطاۃ عن عطاء عن عبید بن عمیر بحوالہ ان کے اور بقول بعض عن حجاج، عن عطاء عن میسرہ بن ابی حبیب بحوالہ ان کے، ایک قول ہے: عن ابی زبیر و منصور بن زاذان و قیس بن سعد و مطر الوراق چاروں بلا واسطہ عطاء سے روایت کرتے ہیں، حماد بن سلمہ نے عن قیس، عن عطاء، طاؤس اور مجاہد کا اضافہ کیا ہے۔ تینوں ام کرز سے روایت کرتے ہیں۔ واسطے کا ذکر نہیں۔ ایک قول ہے: عن قیس بن سعد عن عطاء عن ام عثمان بن خیثم عن ام کرز۔ ایک قول ہے: عن یزید بن ابی زیاد عن عطاء عن سبیعہ بنت حارث، جیسا کہ حرف سین میں بیان ہوا ہے، ایک قول ہے: عن عبدالکریم بن ابو مخارق عن عطاء عن جابر ایک قول ہے: عن محمد بن ابی حمید عن عطاء عن جابر، ان سب میں مضبوط روایت ابن جریج اور ان کے پیروکاروں کی ہے۔ جسے ابن حبان نے صحیح کہا ہے۔ حماد بن سلمہ کی روایت نسائی نے نقل کی ہے، اور عبید اللہ بن ابی یزید عن صباع بن ثابت والی روایت بحوالہ ان کے اسی مفہوم میں ہے۔ جسے ابوداؤد، نسائی، ابن ماجہ نے نقل کیا ہے۔ میں کہتا ہوں: مسند اسحاق بن راہویہ میں عن ام بنی کرز کعبین ایسا ہی ابن حبان نے ان کے طریق سے نقل کیا ہے، دونوں روایتوں کو یوں جمع کرنا ممکن ہے کہ ان کی کنیت ام کرز تھی اور خاوند کا نام کرز تھا اور کرز کے دونوں بیٹوں سے مراد ان کے پوتے کرز ہیں، جو اپنی اس دادی کی طرف نسبت کیے جاتے ہیں۔ واللہ اعلم ان کی ایک اور حدیث ہے جو بروایت عبید اللہ بن بای یزید عن سباع بن ثابت عن ام کرز ہے، فرماتی ہیں: میں نبی علیہ السلام کے پاس آئی، آپ حدیبیہ میں تھے، میں آپ سے قربانی کے گوشت کے بارے میں پوچھنے لگی، میں نے آپ کو فرماتے سنا: 'پرندوں کو ان کی صفوں میں ٹھہرنے دو'۔ اسے نسائی نے مکمل اور ابو داؤد نے مختصر اسی طرح طحاوی نے نقل کیا، ابن حبان نے اسے صحیح کہا، بعض نے سند میں یہ اضافہ نقل کیا ہے: عن عبداللہ بن ابی یزید عن ابیہ۔ ابن ماجہ نے ان سے اسی سند سے یہ حدیث نقل کی ہے: 'نبوتیں ختم ہو گئیں اور سچے خواب باقی رہ گئے'۔ اسے بھی ابن حبان نے صحیح کہا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۷۰) تجرید (۳۳۲/۲)\n(2) طبقات الکبریٰ (۲۱۵/۸)\n(3) ابوداؤد کتاب اضاحی (۲۸۳۶) (۲۸۳۵) ابن ماجہ (۳۱۶۲) مسند احمد (۴۲۲/۶) (۳۸۱/۶) مستدرک (۲۳۷/۴)"}],[10825,"§۱۲۲۱۶ ۔ ام کعب انصاریہ\n(1) ابونعیم نے ان کا نسب بیان کیا ہے۔ صحیح مسلم(2) میں بروایت عبداللہ بن بریدہ عن سمرہ بن جندب ثابت ہے۔ فرمایا: میں نے نبی علیہ السلام کی اقتداء میں ام کعب کا جنازہ پڑھا جو نفاس میں فوت ہوئی تھیں۔ رسول اللہ صلی اللہ علیہ وسلم ان کی نماز جنازہ پڑھانے کے لیے کھڑے ہوئے۔ اصل حدیث بخاری میں ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۷۱) تجرید (۳۳۲/۴)\n(2) مسلم کتاب الجنائز باب این یقوم الامام من المیت (۲۲۳۲)"}],[10826,"§۱۲۲۱۷ ۔ ام کعب\nعجرہ سالمی کی اہلیہ جو انصار کے بنی سالم میں سے حلیف ہیں یہ کعب بن عجرہ مشہور صحابی کی والدہ ہیں۔ طبرانی میں مسند کعب بن عجرہ میں ان کا ذکر ثابت ہے، چنانچہ ایک ضعیف طریق سے بحوالہ کعب بن عجرہ روایت کی ہے، فرماتے ہیں: میں نبی علیہ السلام کے پاس آیا پھر ایک واقعہ ذکر کیا جس میں ہے، نبی علیہ السلام نے فرمایا: 'کعب کو کیا ہوا؟' لوگوں نے بتایا بیمار ہیں۔ چنانچہ آپ علیہ السلام ان کے پاس تشریف لائے اور فرمایا: 'کعب! بیٹا بشارت ہو'۔ ان کی والدہ جھٹ سے بولیں: کعب! تمہیں جنت مبارک ہو۔ تو نبی علیہ السلام نے فرمایا: 'یہ اللہ کے بارے میں قسمیں کھانے والی کون ہے؟' میں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! میری والدہ ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'تمہیں کیا معلوم شاید کعب نے کبھی کوئی لایعنی بات کی ہو اور کوئی معمولی چیز روک لی ہو'۔"],[10827,"§۱۲۲۱۸ ۔ ام کلثوم بنت سید البشر\n(1) رسول اللہ صلی اللہ علیہ وسلم ہے۔ اس میں اختلاف ہے، آیا یہ چھوٹی ہیں یا سیدہ فاطمہ رضی اللہ عنہا یعنی سیدنا عثمان رضی اللہ عنہ نے ان کی بہن رقیہ کی اپنے ہاں وفات کے بعد ان سے شادی کی تھی۔ بقول ابوعمر بعثت سے پہلے عقبہ بن ابی لہب نے ام کلثوم سے شادی کی تھی۔ نبی علیہ السلام کے مبعوث ہونے تک رخصتی نہیں ہوئی تھی تو اس کے والد نے اسے طلاق کا حکم دے دیا۔ سیدنا عثمان رضی اللہ عنہ نے ۳ ہجری میں ان سے شادی کی تھی اور انتقال ۹ ہجری میں بغیر اولاد کے ہوا تھا۔ ام عطیہ انہی کے غسل و کفن میں شریک تھیں جسے وہ روایت کرتی ہیں۔ میں کہتا ہوں: اس کے متعلق ان کی حدیث میں نے فتح الباری میں بیان کی ہے، محفوظ یہ ہے کہ ام عطیہ کا واقعہ سیدہ زینب رضی اللہ عنہا کے بارے میں ہے جیسا کہ صحیح مسلم میں ہے، یہ بھی احتمال ہے کہ دونوں کے کفن و غسل میں شریک ہوئی ہوں۔ ابن سعد(2) کا قول ہے: جب نبی صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا سمیت اپنے اہل و عیال کے ساتھ مدینہ کی طرف ہجرت کی تو ام کلثوم اپنی بہن کے ساتھ نکلیں۔ سیدنا عثمان رضی اللہ عنہ نے ان کی بہن رقیہ کی وفات کے بعد ربیع الاول ۳ ہجری ان سے نکاح کیا اور شعبان ۹ ہجری بغیر اولاد کے ان کے ہاں فوت ہو گئیں۔ پھر اپنی سند سے بحوالہ اسماء بنت عمیس روایت کی ہے، فرماتی ہیں: میں نے اور صفیہ بنت عبد المطلب نے ام کلثوم کو غسل دیا، اور بطریق عمرو مروی ہے کہ ان کی عورتوں نے انہیں غسل دیا جن میں ام عطیہ بھی شامل تھیں۔ صحیح بخاری اور طبقات ابن سعد میں بحوالہ سیدنا انس مروی ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو ان کی قبر کے پاس دیکھا کہ آپ کی آنکھیں اشکبار تھیں، اور آپ فرمانے لگے: 'تم میں کوئی ایسا شخص ہے جس نے آج ہمبستری نہ کی ہو؟' تو ابوطلحہ نے عرض کی: میں ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: قبر میں اترو۔ واقدی اپنی سند سے فرماتے ہیں: ان کی قبر میں، سیدنا علی، فضل اور اسامہ بن زید اترے تھے۔ عتبہ اور عتیبہ جو ابولہب کے بیٹے تھے، دونوں نے رقیہ اور ام کلثوم بنت رسول اللہ صلی اللہ علیہ وسلم سے شادی کی تھی، جب یہ آیت نازل ہوئی: 'ابولہب کے دونوں ہاتھ ٹوٹ جائیں اور وہ تباہ ہو جائے'(3)، تو ابولہب اپنے بیٹوں سے کہنے لگا: جب تک تم دونوں محمد (صلی اللہ علیہ وسلم) کی بیٹیوں کو طلاق نہیں دے دیتے، میرا تمہارے ساتھ اٹھنا بیٹھنا حرام ہے۔ اور ان دونوں سے ان کی ماں جو ایندھن چنتی تھی، کہنے لگی: رقیہ اور ام کلثوم بے دین ہو چکی ہیں، اس لیے انہیں طلاق دے دو۔ چنانچہ رخصتی سے پہلے ہی انہوں نے طلاق دے دی۔ میں کہتا ہوں: یہ روایت ابوعمر کی اس روایت سے بہتر ہے جو انہوں نے ابن سعد کی متابعت میں نقل کی ہے کہ ابو لہب کے دونوں بیٹیوں نے بعثت سے پہلے رقیہ اور ام کلثوم سے شادی کی تھی۔ اس میں تامل ہے۔ کیونکہ ابوعمر نے اس پر اتفاق نقل کیا ہے کہ آپ کی سب سے بڑی صاحبزادی سیدہ زینب تھی۔ اور ان کے حالات میں بیان ہوا ہے کہ وہ بعثت سے دس سال پہلے پیدا ہوئی تھیں۔ تو جو بعثت سے پہلے دس کی عمر کی تھیں ان سے پہلے چھوٹیوں کی شادی کیسے ہو سکتی ہے؟ ہاں! اگر یہ ثابت ہو جائے تو عقد نکاح رخصتی عمل میں آنے تک تھا، پھر اس سے پہلے جدائی ہو گئی۔ ابن مندہ فرماتے ہیں: عتبہ ام کلثوم سے شب باشی کرنے سے پہلے مر گیا تھا، سلیمان بلال عن یحییٰ بن سعید عن ابن شہاب عن انس روایت کرتے ہیں، انہوں نے ان کلثوم بنت رسول اللہ صلی اللہ علیہ وسلم کی بیٹی ام کلثوم کو دھاری دھار ریشمی کپڑے میں دیکھا۔ اسے ابن مندہ نے نقل کیا، اس کی اصل صحیح میں ہے اور ام عیاش مولاۃ رقیہ کے حالات میں بیان ہو چکا ہے۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: عثمان نے ام کلثوم سے شادی وحی کے مطابق کی۔ ابن مندہ فرماتے ہیں: غریب ہے، صرف اسی سند سے پہچانی جاتی ہے۔ ابن مندہ کی روایت ہے، سیدنا ابو ہریرہ مرفوع نقل کرتے ہیں: اللہ کے رسول صلی اللہ علیہ وسلم کے پاس جبرائیل آکر کہنے لگے: اللہ حکم دے رہا ہے کہ عثمان کا رقیہ کے مہر و حق صحبت کی وجہ سے نکاح کر دو۔(4) فرماتے ہیں: غریب ہے جس میں محمد بن عثمان بن خالد عثمانی منفرد ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۷۳) تجرید (۳۳۳/۲)\n(2) الطبقات الکبریٰ (۲۵/۸)\n(3) سورۃ المسد (تبت) الآیۃ (۱)\n(4) المعجم الکبیر (۱۰۶۳/۲۲) الآحاد والمثانی (۲۹۸۲/۵)"}],[10828,"§۱۲۲۱۹ ۔ ام کلثوم بنت زمعہ قرشیہ\nعامریہ، سیدہ سودہ جو ام المؤمنین ہیں ان کی بہن ہیں، حویطب بن عبد العزیٰ کی زوجہ ہیں، جس سے ابو حکم بن حویطب پیدا ہوئے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[10829,"§۱۲۲۲۰ ۔ ام کلثوم بنت ابوسلمہ\n(1) بن عبد اسد بن عبد عزئی مخزومیہ، رسول اللہ صلی اللہ علیہ وسلم کی پرورش میں تھیں، انہوں نے ام سلمہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کی زوجہ سے روایت کی۔ ان سے ام موسیٰ بن عقبہ نے روایت کی۔ ابو عمر کا قول ہے: ان کی حدیث موسیٰ بن عقبہ کے پاس بحوالہ ان کی والدہ ہے۔ انہوں نے ام کلثوم بنت ابو سلمہ سے روایت کیا ہے۔ میں کہتا ہوں: اسے ابن ابو عاصم(2) نے وحدان میں نقل کیا ہے۔ ہم سے صلت بن مسعود نے روایت کیا، وہ فرماتے ہیں کہ ہم سے مسلم بن خالد نے بحوالہ موسیٰ بن عقبہ، انہوں نے اپنی والدہ سے، انہوں نے ام کلثوم بنت ابو سلمہ سے روایت کیا ہے، فرماتی ہیں: جب نبی کریم صلی اللہ علیہ وسلم نے سیدہ ام سلمہ رضی اللہ عنہا سے نکاح کیا تو ان سے فرمایا: 'میں نے نجاشی کو ہدیہ بھیجا ہے، میرے خیال میں وہ ہمارے پاس واپس آئے گا۔ جو کچھ میں دیکھ رہا ہوں نجاشی فوت ہو گیا ہے، اگر وہ واپس آئے تو تمہارا ہے۔' آپ صلی اللہ علیہ وسلم نے اسے حلہ اور کچھ اوقیہ مشک بھیجا تھا، فرماتی ہیں: ایسا ہی ہوا، جو آپ نے فرمایا تھا، ہدیہ واپس آ گیا۔ آپ صلی اللہ علیہ وسلم نے اپنی زوجہ کے پاس ایک اوقیہ مشک بھیجا اور سیدہ ام سلمہ رضی اللہ عنہا کو حلہ عطا فرمایا۔ اسے مسدد نے بحوالہ مسلم بن خالد روایت کیا ہے لیکن ان کا نسب بیان نہیں کیا۔ اسے ابن مندہ نے اپنے طریق سے نقل کیا ہے۔ فرماتے ہیں: ام کلثوم، بے نسبت، اور اسے ہشام بن عمار نے بحوالہ مسلم بن خالد روایت کیا ہے، اپنی روایت میں فرماتے ہیں: بحوالہ ان کی والدہ، انہوں نے ام کلثوم سے، انہوں نے ام سلمہ رضی اللہ عنہا سے روایت کیا ہے، اسے ابن حبان نے اپنی صحیح میں اپنے طریق سے نقل کیا ہے، اور وہ محفوظ ہے، اس کے سیاق سے پتہ چلتا ہے کہ 'ھی لک' سے مراد حلہ ہے، ہدیہ نہیں۔ اس سے اس اشکال کا جواب مل جاتا ہے کہ 'ھی لک' سے کیا مراد ہے۔ پھر مشک کو اپنی ازواج میں تقسیم کر دیا۔","",{"fn":"(1) اسد الغابہ (۷۵۷۴) تجرید (۳۳/۲)\n(2) الآحاد والمثانی (۳۴۵۹/۶)"}],[10830,"§۱۲۲۲۱ ۔ ام کلثوم بنت سہیل\n(1) بن عمرو قرشیہ عامریہ، ابو جندل کی بہن ہیں۔ ابن اسحاق(2) نے ذکر کیا ہے کہ انہوں نے اپنے شوہر ابوسبرہ بن ابورہم کے ساتھ حبشہ کی طرف ہجرت کی، ابن سعد(3) کا قول ہے: ان کی والدہ فاختہ بنت عامر بن نوفل بن عبد مناف ہیں، مکہ میں ابتدائی دور میں اسلام لائیں، بیعت کی اور حبشہ کی طرف دوسری مرتبہ ہجرت کی، ابوسبرہ سے ان کے ہاں محمد اور عبداللہ پیدا ہوئے۔","",{"fn":"(1) اسد الغابہ (۷۵۷۵) تجرید (۳۳۳/۲)\n(2) السیر والمغازی (۲۲۵)\n(3) طبقات کبریٰ (۱۹۹/۸)"}],[10831,"§۱۲۲۲۲ ۔ ام کلثوم بنت عتبہ\n(1) بن ربیعہ بن عبد شمس عبشمیہ، معاویہ بن ابوسفیان کی خالہ ہیں، عبدالرحمن بن عوف کی زوجہ تھیں، اس سے سالم اکبر کی ولادت ہوئی جو اسلام سے قبل فوت ہو گیا، ابن سعد(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۳۳/۲)\n(2) طبقات کبریٰ (۱۹۹/۸)"}],[10832,"§۱۲۲۲۳ ۔ ام کلثوم بنت عقبہ\n(1) بن ابو معیط امویہ، ان کے بھائی ولید بن عقبہ کے سوانح میں ان کا نسب گزر چکا ہے۔ ان دونوں کی والدہ اروی بنت کریز بن ربیعہ بن حبیب بن عبد شمس ہیں، جو عثمان کی والدہ ہیں، ام کلثوم ابتدائی دور میں اسلام لانے والوں میں سے تھیں، بیعت کی اور مدینہ کی طرف پیدل ہجرت کی، ان کے دونوں بھائی ان کے پیچھے گئے تاکہ انہیں واپس لائیں لیکن وہ واپس نہیں آئیں۔ ابن اسحاق(2) نے مغازی میں نقل کیا ہے، مجھ سے زہری اور عبد اللہ بن ابوبکر بن حزم نے روایت کیا ہے۔ فرماتے ہیں: ام کلثوم بنت عقبہ نے حدیبیہ کے سال ہجرت کی، ان کے بھائی عمارہ اور فلاں جو عقبہ کے بیٹے ہیں، انہیں تلاش کرتے ہوئے آئے تو نبی کریم صلی اللہ علیہ وسلم نے انہیں واپس لوٹانے سے انکار کیا، وہ ہجرت سے قبل غیر شادی شدہ تھیں، جب مدینہ آئیں تو ان سے زید بن حارثہ نے نکاح کیا، سیدنا زید کے شہید ہونے کے بعد ان سے سیدنا زبیر بن عوام نے نکاح کیا، جس سے سیدہ زینب رضی اللہ عنہا کی ولادت ہوئی، انہوں نے ان سے جدائی اختیار کر لی۔ پھر ان سے سیدنا عبدالرحمن بن عوف نے نکاح کیا، جس سے ابراہیم اور حمید پیدا ہوئے۔ ان کی وفات کے بعد سیدنا عمرو بن عاص نے ان سے نکاح کیا، وہ ان کے پاس ایک ماہ رہیں اور وفات پاگئیں۔ ان سے ان کے دونوں بیٹوں حمید بن عبد الرحمن اور ابراہیم نے نکاح کیا، صحیحین اور سنن ثلاثہ میں ان کی حدیث ہے، فرماتی ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم سے خود نہیں سنا کہ آپ صلی اللہ علیہ وسلم لوگوں کو گفتگو میں رخصت دیتے ہیں، تین باتیں جھوٹ نہیں(3)۔۔۔۔ بعض نے اسے مختصر کیا ہے، نسائی نے کبریٰ میں ان کی دوسری حدیث ﴿قُلْ ھُوَ اللہُ اَحَدٌ﴾ کی فضیلت کے بارے میں روایت کی ہے۔ ابن مندہ نے مجمع بن جاریہ کے طریق سے نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے سیدہ ام کلثوم بنت عقبہ جو عبد الرحمن بن عوف کی زوجہ ہیں، فرمایا: کیا تمہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے کہ مسلمانوں کے سردار عبد الرحمن بن عوف سے نکاح کرو؟ کہنے لگیں: جی ہاں! حضرت ابن سعد کا قول ہے، نبی کریم صلی اللہ علیہ وسلم کے بعد مدینہ کی طرف ہجرت کرنے والی پہلی خاتون ہیں، ہمیں معلوم نہیں کہ کسی قریشیہ عورت نے سوائے ام کلثوم کے اپنے والدین کو چھوڑ کر اسلام لانے کے بعد اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی طرف ہجرت کی ہو، وہ مکہ سے تنہا روانہ ہوئیں، اور خزاعہ کے ایک آدمی کے ساتھ سفر کرتی ہوئی مدینہ پہنچیں۔ ان کے پیچھے ان کے بھائی چل پڑے اور ان کے پہنچنے کے دوسرے دن وہ آئے، انہوں نے کہا: یا محمد (صلی اللہ علیہ وسلم)! ہماری شرط پوری کیجئے۔ سیدہ ام کلثوم رضی اللہ عنہا کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! میں عورت ہوں اور عورت کمزور ہوتی ہے، مجھے خوف ہے کہ میرے دین کے بارے میں وہ مجھے آزمائش میں ڈالیں گے اور میں صبر نہ کر سکوں گی، تو اللہ تعالیٰ نے عورتوں کے بارے میں عہد ختم کر دیا، اور آیت امتحان نازل کی، اور اس بارے میں حکم نازل فرمایا جس سے سب راضی ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کا اور ان کے بعد دوسری عورتوں کا امتحان لیا کہ 'تم نے اللہ، اس کے رسول اور اسلام کے لیے ہجرت کی ہے، اپنے شوہر اور مال کے لیے نہیں کی۔' جب وہ یہ کہ لیتیں تو واپس نہیں لوٹائی جاتی تھیں۔ فرماتے ہیں: مکہ میں ان کا کوئی شوہر نہیں تھا، پھر ان سے زید نے، ان کے بعد زبیر نے، ان کے بعد عبدالرحمن بن عوف نے، ان کے بعد سیدنا عمرو بن عاص نے نکاح کیا، وہ ان کے پاس وفات پاگئیں۔","",{"fn":"(1) اسد الغابہ (۷۵۷۷) تجرید (۳۳۳/۲)\n(2) سیرۃ نبوہ (۲۵۳/۳)\n(3) ترمذی (۱۹۳۸)"}],[10833,"§۱۲۲۲۴ ۔ ام کلثوم (بے نسبت)\nبنت ابو امیہ میں ان کا ذکر گزر چکا ہے۔"],[10834,"§۱۲۲۲۵ ۔ ام کلثوم (بے نسبت)\nہوسکتا ہے، ان خواتین میں ان کا ذکر ہو، جن کی کنیت ام کلثوم ہے۔ رجال کے اسماء میں حرف شین میں حدیث شہاب بن مالک میں ان کا ذکر گزر چکا ہے۔"],[10835,"§۱۲۲۲۶ ۔ ام کلثوم بنت عمرو\nبن جرول خزاعیہ، سیدنا عمر بن خطاب رضی اللہ عنہ کی زوجہ تھیں۔ عبید اللہ بن عمر کی والدہ ہیں۔ بخاری میں نام لیے بغیر ان کا تذکرہ ہے کہ سیدنا عمر رضی اللہ عنہ نے انہیں طلاق دے دی تھی، جب یہ آیت نازل ہوئی ﴿تم کافر عورتوں کو روک کر نہ رکھو﴾(1)۔ طبرانی نے ان کا نام لیا ہے، فرماتے ہیں: سیدنا عمر رضی اللہ عنہ کے طلاق دینے کے بعد ان سے ابو جہم بن حذافہ نے نکاح کیا۔","",{"fn":"(1) سورۃ الممتحنۃ الآیۃ (۱۰)"}],[10836,"§۱۲۲۲۷ ۔ ام کلثوم (بے نسبت)\nیہ دوسری خاتون ہیں، ام عطیہ کی حدیث جو نوحہ ترک کرنے پر بیعت کے بارے میں ہے، ان کا ذکر ہے، فرماتی ہیں: اسے میرے سوا اور کسی نے پورا نہیں کیا، ام کلثوم کا ان میں ذکر ہے۔"],[10837,"§۱۲۲۲۸ ۔ ام کلثوم (بے نسبت)\nنسائی میں سیدہ فاطمہ بنت قیس کے قصہ میں ان کا ذکر ہے۔ ام شریک کے بجائے یہ ہے، ام کلثوم کے ہاں عدت گزارو، یہ لکھ لیا جائے۔"],[10838,"§۱۲۲۲۹ ۔ ام کلثوم بنت علی\n(1) بن ابو طالب ہاشمیہ، ان کی والدہ فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم ہیں، نبی کریم صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئیں، ابو عمر کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کی وفات سے قبل پیدا ہوئیں، ابن ابو عمر مقدسی کا قول ہے، مجھ سے سفیان نے بحوالہ محمد بن علی نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے سیدنا علی رضی اللہ عنہ کی طرف ان کی بیٹی ام کلثوم کے لیے پیغام بھیجا، انہوں نے ان کی کم عمری کا ذکر کیا، ان سے کہا گیا، انہوں نے آپ کو لوٹا دیا ہے۔ دوبارہ ان کی طرف جاؤ۔ ان سے سیدنا علی رضی اللہ عنہ نے فرمایا: میں اسے آپ کے پاس بھیجتا ہوں، اگر وہ راضی ہو گئی تو آپ کی زوجہ ہے۔ پھر انہیں بھیجا، انہوں نے ان کی پنڈلی کھولی تو کہنے لگی: رک جائیں! اگر آپ امیر المؤمنین نہ ہوتے تو میں آپ کی آنکھ پھوڑ دیتی۔ ابن وہب نے بحوالہ عبدالرحمن بن زید بن اسلم، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا ہے، سیدنا عمر رضی اللہ عنہ نے ام کلثوم سے چالیس ہزار مہر پر نکاح کیا۔ زبیر کا قول ہے: سیدنا عمر رضی اللہ عنہ کے ان سے دو بچے زید اور رقیہ پیدا ہوئے۔ ام کلثوم اور ان کا بیٹا ایک ہی دن میں فوت ہوئے۔ زید، بنو عدی کے درمیان لڑائی کی صلح کرانے کے لیے نکلے تو اندھیرے میں کسی نے انہیں زخمی کر دیا، کئی دن زندہ رہے، ان کی والدہ بیمار تھیں، دونوں ایک ہی دن فوت ہوئے۔ ابو بشر دولابی نے ذریت طاہرہ میں ابو اسحاق کے طرق سے بحوالہ حسن بن حسین بن علی روایت کیا ہے، فرماتے ہیں: جب ام کلثوم بنت علی سیدنا عمر رضی اللہ عنہ کی وفات کے بعد بیوہ ہو گئیں تو ان کے پاس ان کے بھائی حسن اور حسین آئے اور ان سے کہا۔ اس کے بعد سیدنا علی رضی اللہ عنہ آئے، انہوں نے حمد و ثناء کی، فرمایا: اے بیٹی! اللہ تعالیٰ نے تمہارا معاملہ تمہارے ہاتھ میں رکھا ہے، کیا تم پسند کرتی ہو کہ اپنا معاملہ میرے سر پر کرو؟ انہوں نے کہا: ابا جان! مجھے بھی دوسری عورتوں کی طرح (جوان آدمی سے) نکاح کرنے کی رغبت ہے۔ آپ نے فرمایا: یہ ان دونوں کی کارستانی ہے۔ پھر آپ غصے سے کھڑے ہو گئے، فرمانے لگے: میں ان دونوں میں سے اس وقت تک بات نہیں کروں گا جب تک تم ہاں نہیں کر لیتی، وہ دونوں پھر ان کے پاس آکر پوچھنے لگے۔ انہوں نے ایسا ہی کیا، پھر ان سے عوف بن جعفر بن ابو طالب نے نکاح کیا۔ دار قطنی رحمہ اللہ نے کتاب اخوۃ میں ان کا ذکر کیا ہے کہ عوف انہیں چھوڑ کر وفات پاگئے۔ پھر ان سے ان کے بھائی محمد نے نکاح کیا۔ وہ بھی انہیں چھوڑ کر وفات پاگئے تو ان سے ان کے بھائی عبداللہ بن جعفر نے نکاح کیا، وہ ان کے پاس وفات پاگئیں، ابن سعد نے اسی طرح ذکر کیا ہے، اس کے آخر میں فرمایا، وہ کہا کرتی تھیں: مجھے اسماء بنت عمیس سے حیاء آتی ہے۔ ان کے دو بیٹے میرے پاس فوت ہوئے، مجھے تیسرے کے بارے میں بھی خوف ہے۔ فرماتے ہیں: وہ ان کے پاس وفات پاگئیں، ان میں سے کسی سے اولاد نہیں ہوئی۔ ابن سعد نے بحوالہ جعفر بن محمد، انہوں نے ان کے حوالے سے نقل کیا ہے کہ سیدنا عمر رضی اللہ عنہ نے ام کلثوم کے لیے سیدنا علی رضی اللہ عنہ کے پاس نکاح کا پیغام بھیجا، انہوں نے کہا: میں نے بنو جعفر کے لیے اپنی بیٹیوں کو روکا ہوا ہے۔ انہوں نے کہا: اس کا نکاح مجھ سے کر دیجئے، اللہ کی قسم زمین پر کوئی آدمی ایسا نہیں جو اس کی عزت کا ایسا منتظر ہو جیسا میں ہوں۔ انہوں نے کہا: میں نے کر دیا۔ تو سیدنا عمر رضی اللہ عنہ مہاجرین کے پاس آئے، اور کہا: مجھے شادی کی مبارک باد دو۔ انہوں نے مبارک باد دی۔ انہوں نے پوچھا: آپ نے کس سے نکاح کیا؟ انہوں نے کہا: بنت علی سے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: 'ہر نسب اور تعلق قیامت کے دن ختم ہو جائے گا۔ سوائے میرے نسب اور میرے تعلق کے۔' میں نبی کریم صلی اللہ علیہ وسلم کا سسر ہوں، مجھے یہ بھی پسند ہے۔ عطاء خراسانی کے طریق سے ہے کہ سیدنا عمر رضی اللہ عنہ نے انہیں چالیس ہزار مہر دیا تھا، اور صحیح سند سے نقل کیا ہے کہ سیدنا ابن عمر رضی اللہ عنہ نے سیدہ ام کلثوم اور ان کے بیٹے زید کی نماز جنازہ پڑھی۔ انہیں اپنے قریب رکھا اور چار تکبیریں کہیں۔ اور دوسری سند سے نقل کیا ہے کہ سیدنا سعید بن العاص نے ان دونوں کی نماز جنازہ پڑھی۔","",{"fn":"(1) اسد الغابہ (۷۵۷۸) تجرید (۳۳۳/۲)"}],[10839,"§۱۲۲۳۰ ۔ ام کلثوم بنت عباس\n(1) بن عبد المطلب ہاشمیہ، ابن مندہ کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، پھر دراوردی کے طریق سے بحوالہ ام کلثوم بنت عباس نقل کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'جب اللہ کے خوف سے بندے کے رونگٹے کھڑے ہو جاتے ہیں تو اس کی خطائیں معاف ہوتی ہیں۔'(2) یہ سمویہ کی روایت سے جسے ضرار بن صرد نے ان سے نقل کیا ہے، اسے طبرانی نے بحوالہ ضرار اس سند سے بحوالہ عباس نقل کیا ہے، جو صحیح ہے۔ ابو نعیم کا قول ہے مسند ابن مندہ سے عباس کا نام ساقط ہو گیا۔ میں کہتا ہوں: اسی طرح ثابت نے دلائل میں لیث بن سعد کے طریق سے بحوالہ ام کلثوم بنت عباس، انہوں نے ان سے روایت کیا ہے۔ متنبیہ: ابن اثیر نے اس سے پہلے والے حالات میں نقل کیا ہے کہ ان کی والدہ بنت محمیہ بن جز زبیدی ہیں، اور وہ حسن بن علی کی زوجہ تھیں، ان سے محمد اور جعفر کی ولادت ہوئی، انہوں نے ان سے جدائی اختیار کر لی، تو ابو موسیٰ اشعری نے ان سے نکاح کیا، جس سے موسیٰ کی ولادت ہوئی، وہ انہیں چھوڑ کر وفات پاگئے تو ان سے عمران بن طلحہ نے نکاح کیا، انہوں نے ان سے جدائی اختیار کر لی تو وہ دار ابو موسیٰ لوٹ آئیں، وہیں وفات پائی اور کوفہ کے میدان میں دفن ہوئیں۔ میں کہتا ہوں: یہ سارا قصہ ام کلثوم بنت فضل بن عباس بن عبد المطلب کا ہے، اور صحیح مسلم میں فضل بنت محمیہ کے نکاح کا قصہ ثابت ہے، اور طبقات ابن سعد میں ابو موسیٰ ام کلثوم بنت فضل بن عباس کے نکاح کا قصہ ثابت ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۷۶) تجرید (۳۳۳/۲)\n(2) مجمع الزوائد (۳۱۰/۱۰) جامع المسانید والسنن (۵۲۸/۱۶) اسد الغابہ (۴۸۸/۵)"}],[10840,"§۱۲۲۳۱ ۔ ام کلثوم بنت ابوبکر صدیق تیمیہ\n(1) تابعیہ ہیں، ان کی ولادت سے قبل ان کے والد وفات پا چکے تھے۔ یہ بعد میں پیدا ہوئیں۔ موطا وغیرہ میں ان کا قصہ صحیح روایت میں ہے۔ انہوں نے حدیث مرسل نقل کی ہے۔ اس وجہ سے ابن سکن اور ابن مندہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابراہیم بن طہمان کے طریق سے بحوالہ ام کلثوم بنت ابو بکر نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے عورتوں کو مارنے سے منع فرمایا ہے۔۔۔۔ (الحدیث)(2) پھر فرمایا: اسے لیث نے بحوالہ یحییٰ اسی طرح روایت کیا ہے اور اسے ثوری نے یحییٰ بن حمید کے حوالے سے نقل کیا ہے، فرماتے ہیں: بحوالہ زینب بنت ابوسلمہ۔ میں کہتا ہوں: حسن بن سفیان نے لیث کی حدیث کو دوسرے الفاظ میں بغیر قصہ کے نقل کیا ہے۔ میں کہتا ہوں: ام کلثوم بنت ابوبکر کی دوسری روایت بحوالہ سیدہ عائشہ رضی اللہ عنہا صحیح مسلم میں مروی ہے، ان سے جابر بن عبداللہ انصاری صحابی نے روایت کی، اور ان کی والدہ حبیبہ بنت خارجہ، جنہوں نے ابو بکر کی موت کے بعد ان کو جنا، ان سے اسی طرح جبر بن حبیب، طلحہ بن یحییٰ اور مغیرہ بن حکیم وغیرہ نے روایت کی۔","",{"fn":"(1) اسد الغابہ (۷۵۷۲) تجرید (۳۳۳/۲)\n(2) جامع المسانید والسنن (۵۲۷/۱۶) اسد الغابہ (۴۸۶/۵)"}],[10841,"§۱۲۲۳۲ ۔ ام لیلیٰ بنت رواحہ انصاریہ\n(1) ابولیلیٰ کی زوجہ اور عبدالرحمن بن ابولیلیٰ کی والدہ ہیں، ابوعمر کا قول ہے، بیعت کرنے والی صحابیات میں سے ہیں۔ اہل کوفہ میں ان کی حدیث ان کے گھر والوں کے پاس ہے۔ میں کہتا ہوں: اسے ابن مندہ نے محمد بن عمران بن محمد بن ابولیلیٰ کے طریق سے بحوالہ ان کی پھوپھی حمادہ بنت محمد بن ابولیلیٰ، انہوں نے ان کی دادی ام لیلیٰ سے روایت کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہم سے بیعت لی، جو ہم سے عہد لیا وہ یہ لیا ہے: 'ہم اچھی طرح مہندی لگائیں اور شہد سے بال سنواریں، اپنے ہاتھوں کو مہندی سے خالی نہ رکھیں'۔(2) اور اس اسناد سے ہے، مردوں سے مشابہت اختیار نہیں کرو گی، اور حازم بن محمد غفاری کے طریق سے بحوالہ ان کی والدہ حمادہ بنت محمد بن عبدالرحمن بن ابولیلیٰ روایت ہے، وہ محمد کے سب سے بڑے بیٹے تھے۔ میں نے اپنی پھوپھی کو فرماتے ہوئے سنا، میں نے ام لیلیٰ کا زمانہ پایا، وہ اپنے ہاتھوں اور پاؤں کو مہندی سے رنگ رہی تھیں، اور کہہ رہی تھیں: ہم نے اس بات پر رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔۔۔۔ (الحدیث) طبرانی رحمہ اللہ نے پہلی حدیث اوسط میں نقل کی ہے، فرماتے ہیں: ام لیلیٰ کے حوالے سے اس اسناد سے روایت کی جاتی ہے، محمد بن عمران اس کے روایت کرنے میں منفرد ہیں۔ میں کہتا ہوں: ابن مندہ کی روایت کردہ حدیث اس پر رد ہوگی۔","",{"fn":"(1) اسد الغابہ (۷۵۷۹) تجرید (۳۳۴/۲)\n(2) المعجم الکبیر (۳۳۴/۲۵) مجمع الزوائد (۱۷۱/۵) جامع المسانید والسنن (۵۲۹/۱۶)"}],[10842,"§۱۲۲۳۳ ۔ ام مالک بنت ابی\n(1) بن مالک انصاریہ خزرجیہ، عبد اللہ بن ابی بن سلول کی بہن ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے، فرماتے ہیں: اسلام لائیں اور بیعت کی، ان کی والدہ سلمیٰ بنت مطروف بن حارث بن زید اوسیہ ہیں، ام مالک نے رافع بن مالک بن عجلان سے نکاح کیا۔","",{"fn":"(1) تجرید (۳۳۴/۲)\n(2) طبقات کبریٰ (۲۷۸/۸)"}],[10843,"§۱۲۲۳۴ ۔ ام مالک انصاریہ\n(1) ابن ابو عاصم(2) نے وحدان میں اور ابن ابو خیثمہ نے عطاء بن سائب کے طریق سے بحوالہ یحییٰ بن جودہ، انہوں نے ایک آدمی سے، جنہوں نے ان سے روایت کیا کہ ام مالک انصاریہ فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس ایک کپی گھی لے کر آئی، رسول اللہ صلی اللہ علیہ وسلم نے سیدنا بلال کو حکم دیا کہ اس کو نچوڑ لیں، پھر اسے واپس کر دیا تو وہ بھری ہوئی تھی، وہ آئیں اور کہنے لگیں: کیا میرے بارے میں کوئی حکم نازل ہوا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا حکم؟ انہوں نے کہا: آپ نے میرا ہدیہ واپس کر دیا ہے۔ تو آپ صلی اللہ علیہ وسلم نے سیدنا بلال رضی اللہ عنہ کو بلایا اور ان سے پوچھا، انہوں نے کہا: اس ذات کی قسم! جس نے آپ کو حق کے ساتھ بھیجا ہے، میں نے اسے اتنا نچوڑا کہ مجھے شرم آنے لگی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'تمہیں خوشخبری ہو، اے ام مالک! یہ برکت ہے، اللہ تعالیٰ نے تمہیں جلد اس کا ثواب دے دیا'۔ پھر انہیں سکھایا کہ وہ ہر نماز کے بعد کہیں: 'سبحان اللہ دس بار، الحمد للہ دس بار، اللہ اکبر دس بار'۔ یہ ابن ابو عاصم کے الفاظ ہیں۔ ابن ابو خیثمہ نے اس دوسرے پر اکتفا کیا ہے، حرف زاء میں ام سلیم کا اس سے ملتا جلتا قصہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۸۰) تجرید (۳۳۴/۲)\n(2) الآحاد والمثانی (۳۴۰۵/۶)"}],[10844,"§۱۲۲۳۵ ۔ ام مالک انصاریہ\nمسلم نے اپنی صحیح میں معقل کے طریق سے بحوالہ جابر نقل کیا ہے کہ ام مالک انصاریہ نے نبی کریم صلی اللہ علیہ وسلم کے لیے ایک کپی گھی کا ہدیہ بھیجا کرتی تھیں۔ ان کے بیٹے آتے اور کبھی مانگتے، ان کے پاس کچھ بھی نہ ہوتا، تو وہ اس کپی میں دیکھتیں جس میں وہ نبی علیہ السلام کے پاس گھی بھیجا کرتی تھیں، اس میں گھی ہوتا، بہت عرصہ تک اس میں سے گھی کھاتے رہے، حتیٰ کہ انہوں نے اسے نچوڑ لیا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا 'اگر تم اسے اسی طرح چھوڑ دیتی تو اسی طرح گھی کھاتے رہتے'۔ استیعاب کے ذیل میں فرماتے ہیں: مجھے معلوم نہیں یہ وہی ہیں، ابو عمر نے ان کا ذکر کیا ہے یا اس کے علاوہ ہیں؟ میں نے کہا: ابن مندہ کے کلام سے ظاہر ہوتا ہے کہ یہ ایک ہیں، کہ انہوں نے فرمایا: ان سے جابر اور عبد الرحمن بن سابط اور عیاض بن عبد اللہ بن ابو سرح نے روایت کیا، پھر عمرو بن مرہ کے طریق سے بحوالہ ام مالک انصاریہ روایت کیا، فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، بخار سے میرے جبڑے کانپ رہے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'اے ام مالک! تمہیں کیا ہوا؟' انہوں نے کہا: مجھے بخار ہے، اللہ اس کا برا کرے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اسے برا بھلا نہ کہو، کیونکہ اس سے اللہ تعالیٰ بندوں کے گناہ کم کرتا ہے، جیسے درخت کے پتے جھڑتے ہیں۔'(1)","",{"fn":"(1) جامع المسانید والسنن (۵۳۰/۱۶) اسد الغابہ (۴۹۱/۵)"}],[10845,"§۱۲۲۳۶ ۔ ام مالک البہزیہ\n(1) ابو عمر کا قول ہے، ان سے طاؤس نے بحوالہ ام مبشر، مجاہد کی حدیث کی طرح روایت کی۔ میں کہتا ہوں: اسے ترمذی(2) نے محمد بن حمادہ کے طریق سے بحوالہ ام مالک بہزیہ روایت کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فتنے کا ذکر کیا اور اسے قریب کر کے بیان کیا، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا اس وقت لوگوں میں سب سے بہتر کون ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: 'وہ آدمی جو اپنے جانوروں کی زکوۃ دیتا ہو اور اپنے رب کی عبادت کرتا ہو، اور ایسا آدمی جو اپنے گھوڑے کی لگام پکڑے ہو وہ دشمنوں کو ڈرائے اور دشمن اس کو ڈرائیں۔' ترمذی کا قول ہے: اس طریق سے یہ غریب ہے اسے لیث بن ابوسلیم نے بحوالہ مالک روایت کیا ہے۔ میں کہتا ہوں: لیث کی روایت کو طبرانی نے عبدالواحد بن زیاد کے طریق سے ان کے حوالے سے نقل کیا ہے، ابن مندہ نے بھی اسی طرح نقل کیا ہے، فرمایا: اسے جریر نے آخرین میں لیث کے حوالے سے نقل کیا ہے، فرماتے ہیں: اسے محمد بن حمادہ نے ایک شخص کے حوالے سے بعض کا قول ہے کہ وہ لیث ہے نقل کیا ہے۔ فرماتے ہیں: نعمان بن منذر نے بحوالہ ام مالک روایت کیا ہے۔ میں کہتا ہوں: طبرانی کی مسند شامی میں نعمان کی یہ روایت ہے، فرماتے ہیں کہ اس میں ہے: بحوالہ ام مالک بہزیہ فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: لوگوں میں سب سے زیادہ اجر والا کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: 'وہ شخص جو اپنے گھوڑے کی لگام پکڑے دشمن کے سامنے ہو، وہ ان کو ڈرائے اور وہ اس کو ڈرائیں۔'","",{"fn":"(1) اسد الغابہ (۷۵۸۱) تجرید (۳۳۴/۲)\n(2) ترمذی (۲۱۷۷)"}],[10846,"§۱۲۲۳۷ ۔ ام مالک\nشجاع بن حارث سدوسی کی زوجہ ہیں، شجاع کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[10847,"§۱۲۲۳۸ ۔ ام مبشر بنت براء\n(1) بن معرور انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ام مبشر بنت براء میں ان کا ذکر گزر چکا ہے۔ ابن اسحاق نے بحوالہ ام بشر بنت براء بن معرور روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: 'کیا میں تمہیں لوگوں میں سب سے بہتر شخص کے بارے میں بتاؤں؟' کہنے لگے: کیوں نہیں! یا رسول اللہ صلی اللہ علیہ وسلم! آپ صلی اللہ علیہ وسلم نے فرمایا: 'وہ شخص جو نماز قائم کرے اور زکوۃ دے، وہ لوگوں کے شر سے بچ گیا۔'(2) دوسری حدیث میں ان کا ذکر ہے، اسے ابو داؤد نے زہری کے طریق سے بحوالہ ابن کعب بن مالک، انہوں نے اپنے والد سے نقل کیا ہے کہ ام بشر نبی کریم صلی اللہ علیہ وسلم کی مرض وفات میں آپ صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! قتل کی تہمت کس پر ہے؟ میں اپنے والد کے قتل کی تہمت اس زہر زدہ بکری پر لگاتی ہوں جو انہوں نے آپ کے ساتھ کھائی۔ (الحدیث) اسے دوسرے طریق سے بحوالہ عبدالرحمن بن عبد اللہ بن کعب بن مالک، انہوں نے اپنے والد سے نقل کیا ہے۔ انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، ان سے جابر بن عبد اللہ انصاری نے روایت کی، مسلم اور نسائی نے حجاج بن محمد کے طریق سے بحوالہ ام مبشر ان کی حدیث روایت کی کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو سیدہ حفصہ رضی اللہ عنہا کے ہاں فرماتے ہوئے سنا: 'ان شاء اللہ! بیعت رضوان کے شرکاء میں سے کوئی جہنم میں داخل نہیں ہوگا'۔ (الحدیث) اسے ابن ماجہ نے ابو معاویہ کے طریق سے بحوالہ حفصہ رضی اللہ عنہا نقل کیا ہے، اور عبد اللہ بن ادریس نے اس کی مخالفت کی ہے، فرماتے ہیں: بحوالہ ام مبشر کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو سیدہ حفصہ رضی اللہ عنہا کے گھر فرماتے ہوئے سنا۔ اسے احمد رحمہ اللہ نے ان کے حوالے سے نقل کیا ہے، اور ان کے لیے یہ عنوان قائم کیا ہے: ام مبشر انصاریہ زوجہ زید بن حارثہ، ان کی ایک اور حدیث ہے جسے مسلم نے بھی بحوالہ ام مبشر روایت کیا ہے، یہ عمار بن محمد کی روایت ہے۔ اسی طرح ابو معاویہ کی روایت میں ہے، ابوکریب کی روایت میں ان سے مروی ہے، اسحاق رحمہ اللہ ان کے حوالے سے فرماتے ہیں: کبھی کبھار وہ فرماتے ہیں: بحوالہ ام مبشر اور کبھی ایسا نہیں فرماتے۔ ابن فضیل نے اپنی روایت میں فرمایا: بحوالہ زوجہ زید بن حارثہ اور ان کا نام نہیں لیا۔ اسے بحوالہ اعمش بھی نقل کیا ہے، لیکن ام مبشر کا ذکر نہیں کیا۔ اسی طرح اسے ابن جریج کی روایت سے بحوالہ جابر انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، اور لیث کے طریق سے بحوالہ جابر کہ نبی کریم صلی اللہ علیہ وسلم ام مبشر کے ہاں ان کے کھجوروں کے باغ میں تشریف لائے اور پوچھا: 'یہ کھجوروں کا باغ مسلمان نے لگایا ہے یا کافر نے؟' انہوں نے کہا: بلکہ مسلمان نے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'مسلمان جو بھی درخت اگاتا ہے۔۔۔۔'(3) (الحدیث) ان کی ایک اور حدیث ہے جسے احمد نے بحوالہ ام مبشر نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم میرے ہاں تشریف لائے اور میں انصار کے باغ میں تھی۔ حدیث عذاب قبر کے بارے میں ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۸۲) تجرید (۳۳۴/۲)\n(2) الآحاد والمثانی (۳۳۵۸/۶) المعجم الکبیر (۲۷۱/۲۵) مجمع الزوائد (۳۰۴/۱۰) جامع المسانید والسنن (۵۳۶/۱۶)\n(3) مسند احمد (۱۹۲/۳)"}],[10848,"§۱۲۲۳۹ ۔ ام مبشر انصاریہ\nدوسری خاتون ہیں، وہ براء بن معرور کی زوجہ ہیں اور پہلے والی کی والدہ ہیں۔ مبشر بن براء مذکور کی والدہ ہیں۔ حمیدی نے اپنی مسند میں فرمایا: ہم سے سفیان نے بحوالہ ابن کعب بن مالک، انہوں نے اپنے والد سے نقل کیا ہے کہ وہ ان کے پاس وفات کے وقت تھیں، تو ان سے ام مبشر نے کہا: مبشر کو میری طرف سے سلام کہو۔ انہوں نے کہا: اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'مومن کی روح سبز پرندے میں جنت کے پھل کھاتی ہے'۔ وہ اس سے پہلے یا بعد زید بن حارثہ کے پاس تھیں، انہوں نے روایت بھی کی۔"],[10849,"§۱۲۲۴۰ ۔ ام محجن\n(1) یہ وہی ہیں جو مسجد میں جھاڑو دیا کرتی تھیں، مجنہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۸۴) تجرید (۳۳۴/۲)"}],[10850,"§۱۲۲۴۱ ۔ ام محمد انصاریہ\n(1) ان سے حدیث مروی ہے جسے ابو موسیٰ نے حفص بن ابو داؤد کے طریق سے اور وہ حفص بن سلیمان قاری ہیں جو حدیث کے ایک ضعیف راوی ہیں، بحوالہ ام محمد انصاریہ فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: 'جو اپنے کھانے اور پینے کے وقت یہ پڑھے: بسم اللہ خیر الأسماء بسم اللہ رب الارض والسماء بسم اللہ الذی لا یضر مع اسمہ شیء لم یضرہ ما أکل و شرب۔(2)","",{"fn":"(1) اسد الغابہ (۷۵۸۵) تجرید (۳۳۴/۲)\n(2) جامع المسانید والسنن (۵۳۸/۱۶) اسد الغابہ (۴۹۳/۵)"}],[10851,"§۱۲۲۴۲ ۔ ام محمد\n(1) حاطب بن حارث کی زوجہ ہیں، وہ ام جمیل ہیں، حرف جیم میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۷۶) تجرید (۳۳۴/۲)"}],[10852,"§۱۲۲۴۳ ۔ ام محمد\n(1) یہ خولہ بنت قیس ہیں، حرف خاء میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۸۷) تجرید (۳۳۵/۲)"}],[10853,"§۱۲۲۴۴ ۔ ام مرثد اسلمیہ\n(1) بعض کا قول ہے: غنویہ، ابوعمر کا قول ہے، فتح کے دن اسلام لائیں اور نبی صلی اللہ علیہ وسلم سے بیعت کی، ان سے ام خارجہ نے جو زید بن ثابت کی زوجہ ہیں، روایت کی۔ میں کہتا ہوں: ام حارثہ کے سوانح میں ان کی حدیث گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۸۸) تجرید (۳۳۵/۲)"}],[10854,"§۱۲۲۴۵ ۔ ام مسطح قریشیہ تیمیہ\n(1) بعض کا قول ہے: مطلبیہ، یہ ابو ہم کی بیٹی ہیں، انیس بن عبد المطلب بن عبد مناف، بعض کا قول ہے: بنت صحر بن عامر بن کعب بن تیم بن مرہ۔ میں کہتا ہوں: اسی طرح ابو موسیٰ نے بیان کیا ہے، اور وہ غلط ہے۔ یہ سلمیٰ ام خیر کا نسب ہے جو ابو بکر کی والدہ ہیں، وہ بنت صحر ہیں، پھر اس کے آخر تک بیان کیا، دوسرے راویوں کا قول ہے: وہ ابوبکر صدیق رضی اللہ عنہ کی خالہ کی بیٹی ہیں، ان کا نام رائطہ بنت صحر ہے۔ الخ۔ اسی طرح ابن سعد کا قول ہے، بعض کا قول ہے: ان کا نام سلمیٰ ہے، بعض کا قول ہے: ریطہ ہے۔ اسے ابن امین نے ابن بشکوال کے حوالے سے روایت کیا ہے۔ ابن حزم نے جمہرہ میں اس پر یقین کیا ہے، وہ اپنی کنیت سے مشہور ہیں۔ صحیحین میں قصہ افک میں ان کا ذکر ثابت ہے، جب سیدہ عائشہ رضی اللہ عنہا کے ساتھ قضائے حاجت کے لیے نکلیں، ان کا پاؤں لڑکھڑایا، انہوں نے کہا: مسطح ہلاک ہو، ان سے سیدہ عائشہ رضی اللہ عنہا نے فرمایا: کیا تم بدر میں شریک شخص کو برا بھلا کہہ رہی ہو؟ انہوں نے کہا: کیا تمہیں معلوم نہیں جو اس نے کہا ہے؟ پھر افک کا قصہ ذکر کیا، مسطح ان لوگوں میں سے تھے جنہوں نے اس بارے میں بات کی، ان کے سوانح میں ان کا ذکر گزر چکا ہے۔ ابن سعد کا قول ہے: ام مسطح اسلام لائیں، اس کا اسلام سنور گیا، وہ سب لوگوں سے زیادہ مسطح کے خلاف ہو گئی تھیں جب انہوں نے تہمت لگانے والوں کی ہاں میں ہاں ملائی۔","",{"fn":"(1) اسد الغابہ (۷۵۸۹) تجرید (۳۳۵/۲)"}],[10855,"§۱۲۲۴۶ ۔ ام مسعود انصاریہ\n(1) حکم بن ربیع بن عامر زرقی کی زوجہ ہیں۔ بعض کا قول ہے: ان کا نام اسماء ہے، بعض کا قول ہے: حبیبہ بنت شریق ہیں۔ ان سے ان کے بیٹے مسعود بن حکم نے روایت کی، نسائی نے ابن اسحاق کے طریق سے بحوالہ مسعود بن حکم کی والدہ ان کی حدیث نقل کی ہے کہ انہوں نے روایت کیا گویا میں نے علی بن ابو طالب کو رسول اللہ صلی اللہ علیہ وسلم کے سفید خچر پر انصار کی گھاٹی میں دیکھا، وہ کہہ رہے تھے: 'اے لوگو! یہ کھانے پینے کے دن ہیں،(2) یعنی منی کے ایام۔'","",{"fn":"(1) اسد الغابہ (۷۵۹۰) تجرید اسماء الصحابہ (۳۳۵/۲)\n(2) الآحاد والمثانی (۳۴۴۵/۶)"}],[10856,"§۱۲۲۴۷ ۔ ام مسلم اشجعیہ\n(1) انہیں شرف صحابیت حاصل ہے، اہل کوفہ کے ہاں ان کی حدیث ہے۔ اسے ثوری نے روایت کیا ہے، یہ ابوعمر کا قول ہے۔ میں کہتا ہوں: اسے ابن سکن نے ثوری کے طریق سے بحوالہ ام مسلم اشجعیہ روایت کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے، میں چمڑے کے ایک قبے میں تھا: 'یہ اچھا ہے اگر اس میں مردار نہ ہو۔'(2) اسے ابن مندہ نے دو طریق سے نقل کیا ہے، ان میں سے ایک عالی سند سے ثوری تک پہنچتا ہے۔ فرماتے ہیں: اسے قیس بن ربیع نے اسے بحوالہ ام مسلم اشجعیہ اسے روایت کیا ہے، اسے ابن سعد نے بحوالہ ثوری روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۹۱) تجرید (۳۳۵/۲)\n(2) مسند احمد (۴۳۷/۶)"}],[10857,"§۱۲۲۴۸ ۔ ام مسلم\n(1) سیدہ صفیہ رضی اللہ عنہا کی خادمہ ہیں، صحابہ رضی اللہ عنہم میں ان کا ذکر ہے۔ ان کا صحابیہ ہونا معروف نہیں(2) کہ یہ ابن مندہ کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۴۹۵/۵)\n(2) اسد الغابہ (۷۵۹۰) تجرید (۳۳۵/۲)"}],[10858,"§۱۲۲۴۹ ۔ ام مسیّب انصاریہ\nسیدنا جابر رضی اللہ عنہ نے بخار اور اسے برا بھلا کہنے کے بارے میں ان کی حدیث روایت کی ہے۔ ام سائب میں ان کا ذکر گزر چکا ہے۔"],[10859,"§۱۲۲۵۰ ۔ ام مُطاع اسلمیہ\n(1) ابو عمر کا قول ہے، مدنیہ ہیں، عطاء بن ابو مروان کے پاس بحوالہ ان کے والد ان سے مروی حدیث ہے، ان سے مروی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خیبر میں حاضر تھیں، آپ صلی اللہ علیہ وسلم نے ان کے لیے ایک مرد کے برابر حصہ مقرر کیا، اس میں تردد ہے، خیبر میں ان کا شریک ہونا صحیح ہے۔ ابن مندہ نے اپنے قول 'ام مطاع' پر اضافہ نہیں کیا۔ عطاء بن ابو مروان نے بحوالہ ان کے والد ان کی حدیث روایت کی ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۹۴) تجرید (۳۳۵/۲)"}],[10860,"§۱۲۲۵۱ ۔ ام معاذ (بے نسبت)\nابو بشر دولابی نے کنیتوں میں ان کی حدیث روایت کی ہے۔ بطریق یحییٰ بن معتقل اور سیدنا انس رضی اللہ عنہ کے حوالے سے، فرماتے ہیں: مجھے ام معاذ نے نبی کریم صلی اللہ علیہ وسلم کے پاس بھیجا، میں نے کہا: یا رسول اللہ! مجھے ام معاذ نے بھیجا ہے کہ آپ اللہ تعالیٰ سے ان کے لیے دعا کریں، آپ نے فرمایا: 'اے اللہ! ام معاذ اور معاذ کی مغفرت فرما۔' آپ نے یہ تین مرتبہ فرمایا، مجھے یہ حدیث عالی سند سے ابن صاعد کی چھٹی حدیث میں ابو وقت کے طریق سے ملی ہے۔"],[10861,"§۱۲۲۵۲ ۔ ام معاذ انصاریہ\n(1) حدیث ام عطیہ میں جو نوحے کی ممانعت پر بیعت کے بارے میں ہے، ان کا ذکر ہے، فرماتی ہیں: ہم میں سے ام سلیم، ام علاء اور ام معاذ کے علاوہ کوئی فوت نہیں ہوئی، مستغفری نے اس طرح نقل کیا ہے، اور وہ ابن سعد کے ہاں ایوب کی روایت سے بحوالہ ام عطیہ مروی ہے۔ صحیح(2) میں ایوب کے طریق سے بحوالہ ام عطیہ مروی ہے، اس میں یہ الفاظ ہیں: ام سلیم اور ام علاء اور ابو سبرہ کی بیٹی جو معاذ کی زوجہ ہے...... (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۵۹۵) تجرید (۳۳۵/۲)\n(2) بخاری (۷۲۱۵) مسلم (۱۱۶۱)"}],[10862,"§۱۲۲۵۳ ۔ ام معاذ انصاریہ\n(1) ابن مندہ کا قول ہے، محمد بن اسحاق نے بحوالہ سالم ابو نضر ان کی حدیث روایت کی ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم اپنے بعض فوت شدہ اصحاب کے پاس گئے، تو انصار کی ام معاذ نامی خاتون کہنے لگیں: اے ابو سائب! تمہیں جنت کی خوشخبری ہو.... (الحدیث)(2) اس میں ارسال ہے۔ ام علاء کے لیے یہ قصہ معروف ہے، جیسا کہ گزر چکا ہے، یہ صحیح میں ان کی حدیث سے موصول ہے، ابو سائب عثمان بن مطعون ہیں، شاید یہ کہنے والی زیادہ ہیں یا ان کی دو کنیتیں ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۹۶) تجرید (۳۳۵/۲)\n(2) المعجم الکبیر (۳۵۲/۲۵) مجمع الزوائد (۱۹/۳) جامع المسانید والسنن (۵۴۲/۱۶)"}],[10863,"§۱۲۲۵۴ ۔ ام معاذ بنت عبد اللہ\n(1) بن عمرو بن حرام انصاری، جابر بن عبداللہ کی بہن ہیں۔ ابن سعد(2) نے بحوالہ واقدی ذکر کیا ہے کہ وہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۴۱۱/۲)\n(2) طبقات کبریٰ (۲۸۸/۸)"}],[10864,"§۱۲۲۵۵ ۔ ام معبد خزاعیہ\n(1) یہ وہی ہیں جن کے ہاں نبی کریم صلی اللہ علیہ وسلم نے ہجرت کر کے پڑاؤ کیا، یہ اپنی کنیت سے مشہور ہیں۔ ان کا نام عاتکہ بنت خالد ہے، ان کے بھائی خنیس بن خالد کے سوانح میں حرف خاء میں ان کا ذکر گزر چکا ہے۔ وہ نبی کریم صلی اللہ علیہ وسلم کی مدینہ ہجرت کے بعد ان کے پاس ٹھہرنے کا قصہ بیان کرنے والے ایک راوی ہیں، ان کے سوانح میں اس کی طرف اشارہ گزر چکا ہے، اسے ابو عمر نے بحوالہ عبد الوارث بن سفیان نقل کیا ہے کہ انہوں نے ان کو لکھوایا، فرماتے ہیں کہ ہم سے قاسم بن اصبغ نے بحوالہ ابو ہشام محمد بن سلیمان بن حکم انہوں نے میرے دادا ایوب بن حکم سے، انہوں نے حزام بن ہشام سے، انہوں نے اپنے والد خنیس بن خالد جو رسول اللہ صلی اللہ علیہ وسلم کے صحابی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب مکہ سے ہجرت کر کے مدینہ آئے، آپ صلی اللہ علیہ وسلم کے ساتھ سیدنا ابو بکر صدیق رضی اللہ عنہ اور ان کے غلام عامر بن عامر بن فہیرہ تھے۔ ان کو راستہ دکھانے والے عبداللہ بن اریقط تھے۔ وہ ام معبد خزاعیہ کے خیمے کے پاس سے گزرے، وہ بڑے ڈیل ڈول والی تھیں، وہ کعبہ کے صحن میں کھانا کھلاتی اور پانی پلاتی تھیں۔ انہوں نے ان سے گوشت اور کھجور خریدنا چاہا لیکن اس کے پاس کچھ نہ تھا۔ وہ لوگ بھوکے تھے، خیمہ کے کونے میں بکری تھی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'اے ام معبد! کیا اس کا دودھ ہے؟' وہ کہنے لگیں: یہ بھوکی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'کیا میں اس کا دودھ دوہ لوں؟' انہوں نے کہا: ہاں جی! اگر اس میں آپ کو دودھ ملتا ہے۔ آپ صلی اللہ علیہ وسلم نے اس کے تھنوں پر ہاتھ پھیرا، بسم اللہ پڑھی اور ان کی بکری کے لیے دعا کی تو اس کے تھن دودھ سے بھر گئے، اور وہ جگالی کرنے لگی۔ آپ صلی اللہ علیہ وسلم نے برتن منگوایا جس میں دودھ دوہا یہاں تک کہ اس کے اوپر جھاگ چڑھ آیا۔ پھر ام معبد کو پلایا تو وہ سیر ہو گئیں۔ پھر اپنے صحابہ رضی اللہ عنہم کو پلایا، وہ بھی سیر ہو گئے، آخر میں خود پیا۔ پھر اسی برتن میں دوبارہ دودھ دوہا اور وہ دودھ ان کے پاس چھوڑ دیا اور وہ بکری ان سے خرید لی۔ اور یہ لوگ وہاں سے روانہ ہو گئے۔ پھر لمبی حدیث ذکر کی۔ ابن سکن نے خود ام معبد کے حوالے سے حدیث نقل کی ہے، اسے ابن اشعث حفص بن بیٹی کے طریق سے نقل کیا ہے کہ ہم سے حزام بن ہشام نے بحوالہ خنیس روایت کیا، فرماتے ہیں: میں نے اپنے والد کو بحوالہ ام معبد بنت خالد جو ان کی پھوپھی ہیں، حدیث نقل کرتے ہوئے سنا کہ نبی کریم صلی اللہ علیہ وسلم اور ابو بکر ان کے ہاں اترے، وہ دونوں ایک سواری پر تھے، جب آپ صلی اللہ علیہ وسلم مدینے کی طرف روانہ ہوئے، ام معبد نے ان کی طرف ایک بکری بھیجی۔ آپ صلی اللہ علیہ وسلم نے قریب کر کے اس کے تھنوں کو دیکھا اور فرمایا: 'اللہ کی قسم! اس بکری کے دودھ ہے۔' فرماتے ہیں: وہ بیٹھی ہوئی اپنا چبوترہ ٹھیک کر رہی تھیں، عرض کرنے لگیں: بکری واپس کر دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں! ایسی بکری بھیجو جس کے دودھ نہ ہو۔ فرماتی ہیں: میں نے ایک جوان میمنی بھیج دی، جسے آپ صلی اللہ علیہ وسلم نے قبول کر لیا۔ آپ صلی اللہ علیہ وسلم نے جب بکری کو دیکھا تو فرمایا: مجھے لگتا ہے یہ بکری ہمیں اور ہماری جماعت کے سالن کے لیے کافی ہو گی۔ پھر بطریق ابو النضر بحوالہ ام معبد روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کے ہاں فروکش ہوئے، انہوں نے ہدیہ ایک بکری خدمت میں بھیجی۔ آپ صلی اللہ علیہ وسلم نے اسے قبول کرنے سے انکار کر دیا جو ان کے لیے بڑا شاق تھا۔ لوگوں نے کہا: آپ صلی اللہ علیہ وسلم نے یہ بکری اس لیے واپس کر دی ہے کیونکہ یہ دودھیا تھی۔ تو انہوں نے ایک میمنہ بھیجا جسے آپ صلی اللہ علیہ وسلم نے قبول کر لیا۔ واقدی نے ام معبد کے واقعہ میں اس بکری کا واقعہ نقل کیا جس کے تھنوں پر رسول اللہ صلی اللہ علیہ وسلم نے دست مبارک پھیرا تھا کہ وہ بکری یوم الرمادہ قحط کا مشہور سال تک زندہ رہی۔ فرماتی ہیں: ہم صبح و شام اس کا دودھ دوہتے جبکہ آس پاس میں کہیں دودھ نہ ملتا تھا۔ ابن سعد بحوالہ واقدی وہ حزام بن ہشام سے اس کا مفہوم روایت کرتے ہیں جس میں یہ اضافہ ہے، ام معبد ان دنوں مسلمان تھیں۔ واقدی رحمہ اللہ فرماتے ہیں: ان کے علاوہ کا قول ہے: وہ اس کے بعد آئیں، مسلمان ہوئیں اور بیعت کی۔ پھر واقدی ہی کے حوالہ سے نقل کیا ہے کہ اہل مکہ کو معلوم نہ ہو سکا کہ رسول اللہ صلی اللہ علیہ وسلم کس طرف گئے ہیں، یہاں تک کہ انہیں مکہ کے بالائی حصہ میں بچوں اور غلاموں کی آواز سنائی دی جو آپ کے پیچھے جا رہے تھے اور آپ کی شخصیت نظر نہیں آ رہی تھی۔ وہ کہہ رہے تھے، اللہ تعالیٰ جو تمام لوگوں کا رب ہے، اپنا بہترین بدلہ ان دو دوستوں کو عطا فرمائے، جنہوں نے ام معبد کے خیمے میں آرام کیا۔ بنو کعب کی عورت کا مکان کس قدر مبارک ہے اور اس کے بیٹھنے کی جگہ مسلمانوں کے لیے گھات ہے۔ عمر بن شبہ نے کتاب مکہ میں لکھا ہے کہ ام معبد بنت اشعر آئیں، ان کا سراقہ بن جعشم کے ساتھ پیش آمدہ واقعہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۷۵۹۷) تجرید (۳۳۵/۲)"}],[10865,"§۱۲۲۵۶ ۔ ام معبد بنت عبد اللہ\n(1) بن عمرو بن حرام انصاریہ، جابر بن عبداللہ کی بہن ہیں۔ واقدی نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۳۵/۲)"}],[10866,"§۱۲۲۵۷ ۔ ام معبد (قرطہ کی مولاۃ ہیں)\n(1) بن کعب انصاریہ۔ ابن مندہ کا قول ہے: ان کے صحابی ہونے میں اختلاف ہے۔ موسیٰ بن محمد انصاری نے بحوالہ ام معبد قرطہ کی مولاۃ روایت کیا ہے، فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے صحابہ رضی اللہ عنہم کو کئی کا نبیذ پلاتی تھیں، جن میں معاذ بن جبل بھی تھے، کسی نے ان سے کہا کہ تارکول ملا برتن کا نبیذ جس کا ذکر کیا جاتا ہے، وہ کہاں تھا؟ انہوں نے فرمایا: اللہ تعالیٰ کے حلال کردہ کو حرام سمجھنے والا ایسا ہی ہے جیسے اس کے حرام کردہ کو حلال سمجھنے والا۔ رہا دبا تو وہ کدو ہے، اور حفتم تو وہ مٹکے ہیں جو عجم کی زمین میں ہوتے ہیں اور نقیر وہ کھجوروں کی جڑیں ہیں، ان سے نبی علیہ السلام نے روکا تھا۔ ابن سکن کو تردد ہے آیا یہ ام معبد وہی ہیں جو دعا کی حدیث روایت کرتی ہیں، جن کا عنقریب ذکر ہو گا یا کوئی اور ہیں۔","",{"fn":"(1) اسد الغابہ (۷۵۹۸) تجرید (۳۳۵/۲)"}],[10867,"§۱۲۲۵۸ ۔ ام معبد زوجہ کعب\n(1) بن مالک، محمد بن اسحاق نے بحوالہ معبد بن کعب بن مالک انہوں نے اپنی والدہ سے حدیث روایت کی ہے، انہوں نے دونوں قبلوں کی طرف نماز پڑھی۔ فرماتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'کھجور اور کشمش کی اکٹھی نبیذ نہ بناؤ، ہر ایک کی علیحدہ نبیذ بناؤ۔'(2) اسے احمد، طبرانی اور ابن مندہ نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۵۹۹) تجرید (۳۳۵/۲)\n(2) مسند احمد (۱۸۱۶) المعجم الکبیر (۳۵۴/۲۵) جامع المسانید والسنن (۳۵۴/۱۶)"}],[10868,"§۱۲۲۵۹ ۔ ام معبد (بے نسبت)\n(1) بعض کا قول ہے: انصاریہ ہیں، عبد الرحمن بن زیاد بن انعم نے بحوالہ ام معبد ان کی حدیث روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم دعا کر رہے تھے: 'اے اللہ! میرے دل کو نفاق سے، میرے عمل کو ریا کاری سے، میری زبان کو جھوٹ سے، میری آنکھ کو خیانت سے پاک کر دے، تو آنکھوں کی خیانت کو جانتا ہے، اور جو کچھ دلوں میں مخفی ہے۔'(2) اسے ابو نعیم نے نقل کیا ہے اور خزاعیہ سے علیحدہ اس کا ذکر کیا ہے۔ ابو موسیٰ نے اس کی پیروی کی ہے، رہے ابن سکن تو انہوں نے اسماء میں عاتکہ میں خزاعیہ کے سوانح میں حدیث کا ذکر کیا ہے۔ فرماتے ہیں: ام معبد کے مولیٰ نے ام معبد سے دعا کے بارے میں حدیث ذکر کی، پھر کنیتوں میں فرمایا: ام معبد انصاریہ، دو خیموں والی یعنی خزاعیہ نہیں، پھر اسی سند اور متن سے دوسرے شیخ سے حدیث بیان کی۔ پھر فرمایا: ان ام معبد کی اس حدیث کے علاوہ مجھے کوئی اور روایت نہیں کی۔ اس کی اسناد میں تردد ہے، ایسا ہی ہے جیسا کہ انہوں نے کہا، وہ فرج بن فضالہ کی روایت بحوالہ ابن انعم ہے، وہ دونوں ضعیف راوی ہیں، پھر فرمایا: بحوالہ ابن حارث، انہوں نے ام معبد مولاۃ قرطہ سے ظروف کے بارے میں حدیث روایت کی، مجھے معلوم نہیں کہ یہ وہی ہیں یا اس کے علاوہ ہیں۔ باوجود یکہ وہ مضبوط حافظے والے ہیں لیکن اس سلسلے میں ان کی بات قابل اعتراض ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۰۰) تجرید (۳۳۶/۲)\n(2) جامع المسانید والسنن (۵۴۵/۱۶) اسد الغابہ (۴۹۷/۵)"}],[10869,"§۱۲۲۶۰ ۔ ام معبد\nام مغیث میں ان کا ذکر آئے گا۔"],[10870,"§۱۲۲۶۱ ۔ ام معقل اسدیہ\n(1) ابو معقل کی زوجہ ہیں، بعض کا قول ہے: اشجعیہ ہیں، بعض نے کہا: انصاریہ ہیں۔ اصحاب سنن ثلاثہ میں ان کی حدیث مروی ہے۔ اس کا مفصل بیان رجال کی کنیتوں میں ان کے شوہر کے سوانح میں گزر چکا ہے، ان کی حدیث کی سند میں اختلاف کا ذکر ہے۔ 'رمضان میں عمرہ کرنا حج کے برابر ہے۔' بعض کا قول ہے: صحیح میں حدیث ابن عباس رضی اللہ عنہما میں جن خاتون کا ذکر ہے، ان سے مراد یہی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے انصار کی ایک خاتون سے فرمایا: 'تمہیں ہمارے ساتھ حج کرنے سے کس نے روکا؟' فرماتی ہیں: ہمارا ایک اونٹ تھا، اس پر ابو فلاں اور ان کے شوہر کی بیٹی اور ان کا بیٹا سوار ہوئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'جب رمضان کا مہینہ آئے تو عمرہ کرو، کیونکہ رمضان میں عمرہ کرنا حج کے برابر ہے۔' لیکن مسلم میں ثابت ہے کہ یہ ام سنان ہیں، اگر چہ ان کی کنیت میں اختلاف ہو یا بہت سے قصے ہوں، وہ زیادہ مناسب ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۰۱) تجرید (۳۳۷/۲)"}],[10871,"§۱۲۲۶۲ ۔ ام مغیث\n(1) ابن مندہ کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ پھر سعید بن ابو مریم کے طریق سے بحوالہ ام مغیث حدیث روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم کو انہوں نے دو شریکوں سے منع فرمایا ہے۔ میں کہتا ہوں: فرماتے ہیں: وہ کھجور اور کشمش ہیں، طبرانی نے اضافہ کیا ہے کہ ام مغیث ربیعہ بن ابو عبد الرحمن کی دادی ہیں، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں دونوں قبلوں کی طرف نماز پڑھی۔ ابو عمر کا قول ہے، اہل مدینہ میں ان کا شمار ہے۔ عبد اللہ بن یوسف کے ہاں بحوالہ ان کے والد، ان سے مروی حدیث ہے، دو شریکوں اور نشہ آور چیز کے حرام ہونے کے بارے میں، بعض کا قول ہے یہ ام ابن ابو عبد الرحمن کی والدہ ہیں، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ دونوں قبلوں کی طرف نماز پڑھی۔ ابن فرضی نے ذکر کیا ہے کہ ابن وہب نے مذکورہ حدیث روایت کی کہ محمد بن وضاح نے اس کا تعاقب کیا ہے۔ پھر اسے بحوالہ حرملہ بیان کیا ہے کہ ابن وہب نے اس میں خطا کی، فرماتے ہیں: ام مغیث، وہ ام معبد ہیں۔ میں کہتا ہوں: گویا اس دعوے پر مجبور کرنے والی چیز متن کا اتحاد ہے۔ اس کا وصف یہ ہے کہ انہوں نے دونوں قبلوں کی طرف نماز پڑھی، اس میں تردد ہے، کیونکہ دونوں حدیثوں کا مخرج مختلف ہے۔ ایک ہی حدیث کی روایت پر دونوں صحابہ رضی اللہ عنہم کا اتفاق ہے۔ ان کا ایک ہی صفت پر اجتماع بعید نہیں، ابن وہب پر اس کے حفظ کے ساتھ وسعت روایت کا حکم مردود ہے۔ اگر یہ ابو مغیث کے قول کے ساتھ متفرد ہے تو وہ متفرد نہیں، بلکہ سعید بن ابو مریم نے اس سے موافقت کی، جیسا کہ آپ دیکھ رہے ہیں۔ ابن عبد البر نے ام معبد کے سوانح ام مغیث کے بعد نقل کیے ہیں، فرماتے ہیں: دو شریکوں کے بارے میں روایت کی۔ ان سے معبد بن کعب نے روایت کی، پھر میں نے خطیب کی مؤتلف میں پایا، ام مغیث، پھر ابن عبد الحکم کے طریق سے بحوالہ ابن وہب پوری حدیث روایت کی، پھر خطیب نے فرمایا: پھر میں نے حدیث کو دوسرے طریق سے پایا، فرماتے ہیں کہ اس میں ام معبد ہیں، پھر اسے بکر بن یونس بن بکیر کے طریق سے بحوالہ عبد الجبار اسے روایت کیا۔ میں کہتا ہوں: یہ اس کی تحریر میں تیسرا اختلاف ہے، اور اسحاق بن ابو فروہ بہت ضعیف ہیں۔","",{"fn":"(1) اسد الغابہ (۷۶۰۲) تجرید (۳۳۶/۲)"}],[10872,"§۱۲۲۶۳ ۔ ام مغیرہ بنت نوفل\n(1) بن حارث بن عبد المطلب ہاشمیہ، کنیتوں میں تمیم داری کے مولیٰ ابو براء کے سوانح میں ان کا ذکر گزر چکا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے تمیم سے ان کے والد کی اجازت سے ان کا نکاح کرا دیا، تجرید میں اس کی اصل کی اتباع میں لکھا ہے، ام مغیرہ بن نوفل، بحوالہ ابو موسیٰ نقل کیا ہے۔ وہ لفظی غلطی ہے صحیح یہ ہے: بنت نوفل جیسا کہ میں نے ذکر کیا، اسی طرح ابو موسیٰ کے ذیل میں ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۰۳) تجرید (۳۳۶/۲)"}],[10873,"§۱۲۲۶۴ ۔ ام مکتوم\nفاکہی کی کتاب اخبار مکہ کی جلد ثانی کے آخر میں اس کا ذکر ہے، عطاء کی روایت میں بحوالہ فاطمہ بنت قیس ان کا ذکر ہے۔"],[10874,"§۱۲۲۶۵ ۔ ام منذر بنت قیس\n(1) بن عمرو بن عبید بن عامر بن غنم بن عدی بن نجار انصاریہ نجاریہ۔ طبرانی کا قول ہے: ان کا نام سلمیٰ بنت قیس ہے۔ سلیط بن قیس کی بہن ہیں، بنو مازن بن نجار سے ہیں۔ میرے نزدیک وہ اس کے علاوہ ہیں، سلمیٰ بنت قیس کی حدیث بیعت میں گزر چکی ہے، ام منذر کی حدیث کو ابوداؤد(2) اور ترمذی، ابن سعد، ابن ماجہ نے فلیح بن سلیمان کے طریق سے بحوالہ ام منذر بنت قیس انصاریہ نقل کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم میرے پاس آئے اور آپ صلی اللہ علیہ وسلم کے ساتھ سیدنا علی رضی اللہ عنہ تھے اور سیدنا علی رضی اللہ عنہ بیمار تھے، ان کے پاس کھجوروں کے خوشے لٹکے ہوئے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کھانے لگے، آپ صلی اللہ علیہ وسلم نے فرمایا: 'اے علی! رک جاؤ، تم بیمار ہو۔' یہاں تک کہ سیدنا علی رضی اللہ عنہ رک گئے۔ فرماتی ہیں: میں نے آپ کے لیے جو چقندر تیار کیے تھے وہ لے کر آئی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: 'اے علی! اس میں سے کھاؤ، یہ تمہارے لیے اچھا ہے۔' الفاظ ابوداؤد کے ہیں، ترمذی کا قول ہے: حسن غریب ہے، ہم اسے حدیث فلیح کے علاوہ نہیں جانتے۔ اس بات کا تعاقب کیا ہے کہ وہ ابن ابو فدیک کے طریق سے بحوالہ یعقوب اسی طرح مروی ہے۔ میں کہتا ہوں: فلیح بن سلیمان اسلمی، ان کی کنیت ابو یحییٰ اور ابن محمد ہے، جو بخاری کے رجال میں سے ہیں اور ابن ابو فدیک، ان کے ساتھیوں میں سے ہیں، گویا انہوں نے ان کے حوالے سے اسے محمول کیا ہے، ان کے بیٹے کا نام کم سنی کی وجہ سے صاف نہیں لیا۔ محمد بن اسحاق کا قول ہے: محمد بن ابو یحییٰ جو ابراہیم شافعی رحمہ اللہ کے شیخ کے والد ہیں کے ساتھ مل گیا، وہ ان سے ملے نہیں، بلکہ فلیح کی طرف خبر راجع ہو گی، جیسا کہ ترمذی کا قول ہے۔ ابن سعد رحمہ اللہ کا قول ہے(3)، ان کی والدہ رغیبہ بنت زرارہ بن عبید بن عدس نجاریہ ہیں، ان سے قیس بن صعصعہ بن وہب نے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (۷۶۰۴) تجرید (۳۳۶/۲)\n(2) ابوداؤد (۳۸۵۶)\n(3) طبقات الکبریٰ (۳۰۸/۸)"}],[10875,"§۱۲۲۶۶ ۔ ام منظور بنت محمد\n(1) بن سلمہ انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن اثیر(2) نے ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، یہ ابن حبیب کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۰۵)\n(2) اسد الغابہ (۴۹۸/۵)"}],[10876,"§۱۲۲۶۷ ۔ ام منظور بنت محمود\n(1) بن سلمہ انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ یہ ہند کی سگی بہن ہیں، جن کا ذکر گزر چکا ہے۔ ابن سعد رحمہ اللہ نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے، پہلی والی میں ان کا ذکر نہیں کیا، فرماتے ہیں: ان سے لبید فقیہ کی ولادت ہوئی، انہوں نے اس کا نام اپنے والد کے نام پر رکھا، اسی طرح ان سے منظور بن لبید کی ولادت ہوئی جس پر ان کی کنیت ہے، وہ محمود سے بڑے ہیں۔","",{"fn":"(1) تجرید (۳۳۶/۲)"}],[10877,"§۱۲۲۶۸ ۔ ام منیع، شباث کی والدہ\n(1) بعض کا قول ہے: یہ اسماء بنت عمرو ہیں، حرف الف میں جن کا ذکر گزر چکا ہے۔ ابن سعد(2) نے واقدی کے حوالے سے اپنی مسند سے جسے وہ ام عمارہ تک لے گئے ہیں نقل کیا ہے۔ فرماتی ہیں: بیعت عقبہ کی رات مرد رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ پر اپنا ہاتھ رکھتے تھے۔ سیدنا عباس رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کا ہاتھ پکڑے ہوئے تھے۔ جب میں اور ام منبع باقی رہ گئیں تو میرے شوہر غزیہ بن عمرو نے پکارا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا یہ دو عورتیں ہمارے ساتھ آپ صلی اللہ علیہ وسلم سے بیعت کرنے حاضر ہوئی ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'میں نے تم دونوں سے بیعت لے لی، میں عورتوں سے مصافحہ نہیں کرتا۔' ابن سعد رحمہ اللہ نے اسی طرح فرمایا: ان کی والدہ اپنے شوہر خدیج بن سلامہ کے ساتھ عقبہ میں اور خیبر میں بھی حاضر تھیں۔","",{"fn":"(1) اسد الغابہ (۷۶۰۶) تجرید (۳۳۶/۲)\n(2) طبقات الکبریٰ (۲۹۸/۸)"}],[10878,"§۱۲۲۶۹ ۔ ام منہال\nمالک بن نویرہ تمیمی کی زوجہ ہیں، ان کے شوہر کے سوانح میں ان کا ذکر ہے۔"],[10879,"§۱۲۲۷۰ ۔ ام مہاجر رومیہ\nسیدنا عثمان رضی اللہ عنہ کے زمانے میں اسلام لائیں، بخاری رحمہ اللہ نے ادب المفرد میں فرمایا: ہم سے موسیٰ نے بیان کیا، وہ فرماتے ہیں کہ ہم سے عبدالواحد نے، وہ فرماتے ہیں کہ ہم سے ایک بوڑھی خاتون ثوبیہ جو علی بن غراب کی دادی ہیں، وہ فرماتی ہیں کہ مجھ سے ام مہاجر نے روایت کی، فرماتی ہیں کہ میں اور چند رومی لڑکیاں قیدی بنائی گئیں، ان پر سیدنا عثمان رضی اللہ عنہ نے اسلام پیش کیا۔ میرے اور ایک اور لڑکی کے علاوہ کسی نے اسلام قبول نہیں کیا۔ انہوں نے کہا: ان دونوں کا ختنہ کرو اور انہیں پاک کرو۔ میں سیدنا عثمان رضی اللہ عنہ کی خدمت کرتی تھی۔"],[10880,"§۱۲۲۷۱ ۔ ام موسیٰ لخمیہ\nنصیر نعمی کی زوجہ ہیں، جو موسیٰ بن نصیر کے والد ہیں۔ یہ مشہور امیر ہیں جنہوں نے اندلس فتح کیا، انہوں نے نبوت کا زمانہ پایا۔ رشاطی نے ذکر کیا ہے کہ وہ اپنے شوہر کے ساتھ یرموک میں حاضر تھیں تو انہوں نے اس وقت ایک کافر کو قتل کیا اور اس کا سامان اتار لیا، عبد العزیز بن مروان ان سے یہ واقعہ سنتے تو وہ ان سے بیان کرتیں، کہتیں: ہم عورتوں کی جماعت میں تھیں، اچانک مردوں نے حملہ کیا تو مجھے ایک کافر کسی مسلمان کو گھسیٹتے ہوئے نظر آیا۔ میں نے جلدی سے خیمے کا کھونٹا لے کر قریب ہو کر اس کا سر کچل دیا اور اس کا سامان لینے لگی تو وہی مسلمان مرد میری مدد کرنے لگا۔"],[10881,"§۱۲۲۷۲ ۔ ام محمد بن حاطب\nیہ ام جمیل ہیں، جس نے ام محمد کے استدراک میں ان کا ذکر کیا ہے، اسے وہم ہوا ہے کیونکہ ان کا ایک بیٹا ہے جس کا نام محمد ہے، حرف عین کے آخر میں، میں نے اس کے فساد کا ذکر کر دیا ہے۔"],[10882,"§۱۲۲۷۳ ۔ ام معبد\nقسم اول میں ان کے بارے میں قول گزر چکا ہے۔"],[10883,"§۱۲۲۷۴ ۔ ام معتب\nابن وضاح کے دعوے کے شروع میں گزر چکا ہے کہ ابن وہب نے ان کے بارے میں لفظی غلطی کی ہے۔"],[10884,"§۱۲۲۷۵ ۔ ام نبیط\n(1) ابن اثیر(2) کا قول ہے، ان کے نام میں اختلاف ہے۔ میں کہتا ہوں: میں نے فاطمہ بنت منجی کے سامنے بحوالہ سلیمان بن حمزہ اور ابو نصر بن شیرازی پڑھا۔ نبیط بن جابر اپنی دادی ام نبیط سے روایت کرتے ہیں، فرماتی ہیں کہ ہم نے بنو نجار کی ایک لڑکی کو تیار کر کے اس کے خاوند کی طرف رخصت کیا، میں بنو نجار کی عورتوں کے ساتھ تھی، میرے ساتھ ڈفلی تھی جسے بجا کر میں کہہ رہی تھی: 'ہم تمہارے پاس آئے، ہم تمہارے پاس آئے، تم ہمیں سلام کرو، ہم تمہیں سلام کرتے ہیں، اگر سرخ سونا نہ ہوتا تو یہ تمہاری وادی میں نہ اترتی۔' فرماتی ہیں رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس کھڑے ہو کر فرمانے لگے: 'ام نبیط یہ کیا کہہ ہے؟' میں نے عرض کی: میرے ماں باپ آپ پر قربان ہوں، اللہ کے نبی صلی اللہ علیہ وسلم ہمارے بنی نجار کی ایک لڑکی کی رخصتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'تم کیا کہہ رہی تھی؟' تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یوں کہو! 'اگر سفید گندم نہ ہوتی تو تمہاری لڑکیاں موٹی نہ ہوتیں۔' میں کہتا ہوں: یہ حدیث غریب ہے، اسے ابن مندہ نے بحوالہ ..........  اسے ابن اثیر نے بحوالہ ابو قاسم بن ابو علاء نقل کیا ہے، گویا ہمارے شیخ نے ان سے سنا، ابو نعیم کا قول ہے: ان کے سوانح میں ان کا ذکر گزر چکا ہے۔ میں کہتا ہوں: ابو نعیم نے ذکر کیا ہے کہ ان کا نام نائلہ بنت حسحاس ہے، میں نے اسے حرف نون میں ذکر کیا ہے، یہ ان کی شرط کے مطابق ہے پھر بھی انہوں نے ان کا ذکر چھوڑ دیا۔","",{"fn":"(1) اسد الغابہ (۷۶۰۸) تجرید (۳۳۶/۲)\n(2) اسد الغابہ (۴۹۹/۵) بیاض فی الأصل"}],[10885,"§۱۲۲۷۶ ۔ ام نصر محاربیہ\n(1) ابن اسحاق نے ان کی حدیث بحوالہ ابو نصر محاربی نقل کیا ہے، فرماتی ہیں: ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پالتو گدھوں کے گوشت کے بارے میں سوال کیا، فرماتے ہیں: 'کیا وہ چارہ اور درخت کے پتے نہیں کھاتے؟' انہوں نے کہا: جی ہاں! آپ صلی اللہ علیہ وسلم نے فرمایا: 'تو ان کا گوشت کھاؤ۔' اسے طبرانی(2) اور ابن مندہ نے نقل کیا ہے۔ ابو عمر کا قول ہے: ابراہیم بن مختار رازی بحوالہ محمد بن اسحاق ان کے ذکر میں تنہا ہیں، یہ ان لوگوں میں سے نہیں ہیں جن کی حدیث بطور دلیل لی جاتی ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۰۹) تجرید (۳۳۶/۲)\n(2) المعجم الکبیر (۳۹۰/۲۵)"}],[10886,"§۱۲۲۷۷ ۔ ام نعمان بنت رواحہ\nیہ عمرہ ہیں، صحیح ابو عوانہ میں اس حدیث میں ان کی کنیت ہے جسے مسلم نے ان کے نام سے نقل کیا ہے۔"],[10887,"§۱۲۲۷۸ ۔ ام نہشل بنت عبیدہ\nابن سعید بن العاص بن امیہ، ان کے والد بدر میں قتل ہوئے۔ وہ مکہ میں تھیں اور سیدنا عمر رضی اللہ عنہ کی خلافت میں سیلاب سے غرق ہوئیں۔ یہ اس کتاب کی شرط کے مطابق ہیں، جبکہ حجتہ الوداع کے موقع پر مکہ میں کوئی ایسا موجود نہ تھا جو اسلام نہ لایا ہو۔ فاکہی نے کتاب مکہ میں فرمایا: اسلام کے زمانے میں مکہ میں جو سیلاب آیا وہ سیلان ام نہشل تھا۔ وہ سیدنا عمر رضی اللہ عنہ کے زمانے میں آیا۔ مکہ کے بلند حصے سے آیا یہاں تک کہ مسجد حرام میں داخل ہو گیا۔ اس کا بہاؤ دو حویلیوں کے درمیان تھا۔ ام نہشل بنت عبیدہ بن سعید بن العاص بن امیہ اس میں بہہ گئیں۔ پھر مکہ کے زیریں حصے سے انہیں نکالا گیا، اس سیلاب کا نام سیلاب ام نہشل رکھا گیا۔"],[10888,"§۱۲۲۷۹ ۔ ام نیار بنت زید\n(1) بن مالک بن عدی بن کعب بن عبد اشہل انصاریہ، پھر اشہلیہ جو سعد بن زید کی بہن ہیں، واقدی نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(2) کا قول ہے: ہمیں انصار کے نسب میں ان کا ذکر نہیں ملا۔ نوٹ: قسم ثانی، ثالث اور رابع خالی ہیں۔","",{"fn":"(1) تجرید (۳۳۶/۲)\n(2) طبقات کبریٰ (۲۲۴/۸)"}],[10889,"§۱۲۲۸۰ ۔ ام ہاشم\n(1) ام ہشام میں ان کا ذکر آئے گا۔ ابن عبد البر(2) کا قول ہے، ان سے خبیب بن عبد الرحمن بن یساف نے روایت کی ہے۔ ابن فتحون نے ان کا تعاقب کیا ہے کہ خبیب نے ان کے واسطے سے روایت کی ہے، ایسا ہی ہے جو انہوں نے کہا۔","",{"fn":"(1) الاستيعاب (۳۶۵۴)\n(2) الاستيعاب (۱۹۶۳/۴)"}],[10890,"§۱۲۲۸۱ ۔ ام ہانی بنت ابو طالب\n(1) بن عبد المطلب بن ہاشم ہاشمیہ، نبی کریم صلی اللہ علیہ وسلم کی چچا زاد ہیں، بعض نے کہا: ان کا نام فاختہ ہے، ایک قول ہے کہ ان کا نام فاطمہ ہے۔ ایک قول کے مطابق ان کا نام ہند ہے۔ پہلا قول زیادہ مشہور ہے۔ بہیرہ بن عمرو بن عائذ بن عمران مخزوم مخزومی کی زوجہ ہیں۔ ابن کلبی رحمہ اللہ نے بحوالہ ابن عباس رضی اللہ عنہما ذکر کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ابو طالب کے پاس ام ہانی کے نکاح کا پیغام بھیجا، اور ہبیرہ نے بھی نکاح کا پیغام دیا، انہوں نے بہیرہ سے ان کا نکاح کر دیا۔ تو نبی کریم صلی اللہ علیہ وسلم نے ان سے عتاب کیا، تو ابو طالب کہنے لگے: اے میرے بھتیجے! ہم نے انہیں رشتہ دیا ہے، شریف آدمی، شریف آدمی کو بدلہ دیتا ہے۔ پھر اسلام نے ام ہانی اور ہبیرہ کے درمیان تفریق کر دی تو نبی کریم صلی اللہ علیہ وسلم نے انہیں نکاح کا پیغام دیا۔ وہ کہنے لگیں: اللہ کی قسم! میں آپ سے جاہلیت میں محبت رکھتی تھی اب اسلام میں کیسے نہ رکھوں! لیکن میں ایک مصیبت زدہ عورت ہوں، مجھے نا پسند ہے کہ آپ کو ایذاء پہنچاؤں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'عورتوں میں سے بہتر عورتیں، اونٹوں پر سوار ہونے والی قریش کی عورتیں ہیں، اولاد پر شفقت کرتی ہیں.... (الحدیث)'(2) ابن سعد رحمہ اللہ نے صحیح سند سے بحوالہ شعبی نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے سیدہ ام ہانی کو نکاح کا پیغام دیا، انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! میں اپنی آنکھ اور کان سے زیادہ آپ کو محبوب رکھتی ہوں۔ شوہر کا حق بہت بڑا ہے، مجھے یہ خوف ہے کہ شوہر کا حق ادا نہ کر سکوں..... پھر حدیث ذکر کی۔ ابو فل بن ابو عقرب کے طریق سے ہے۔ فرماتے ہیں: ان کو نکاح کا پیغام دیا تو آپ نے اپنے سامنے موجود دونوں بچوں سے کہا: 'دودھ پینے کے لیے یہ کافی ہے اور ساتھ لیٹنے کے لیے یہ کافی ہے۔' پھر حدیث ذکر کی۔ یہ دونوں مرسل ہیں۔ سدی کے طریق سے بحوالہ ابو صالح مولیٰ ام ہانی مروی ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ام ہانی کو نکاح کا پیغام دیا، تو وہ کہنے لگیں: میں عیال دار ہوں۔ جب ان کے بیٹے بڑے ہو گئے تو انہوں نے اپنے نفس کو آپ صلی اللہ علیہ وسلم پر ہبہ کر دیا، تو کہا: اب ایسا نہیں ہو سکتا، کیونکہ اللہ تعالیٰ نے آپ پر یہ آیت اتاری ﴿آپ کی پھوپھی زاد اور آپ کی ماموں زاد اور آپ کی خالہ زاد اور جنہوں نے آپ کے ساتھ ہجرت کی﴾(3) ابو عمر کا قول ہے: جب مکہ فتح ہوا تو بہیرہ نجران کی طرف بھاگ گیا، اس بارے میں شعر کہے اور اپنے فرار کے بارے میں معذرت کی، جب اسے یہ معلوم ہوا کہ ام ہانی اسلام لے آئی ہیں تو ان کے بارے میں شعر کہے، اس کا ان سے ایک بیٹا عمرو جس پر اس کی کنیت تھی، اور بہیرہ اور ان دونوں کے علاوہ ام ہانی نے نبی کریم صلی اللہ علیہ وسلم سے احادیث روایت کیں، جو کتب ستہ وغیرہ میں ہیں۔ ان سے ان کے بیٹے جعدہ، ان کے بیٹے بیٹی اور ان کے پوتے ہارون نے روایت کی، ان کے موالی ابو مرہ، ابو صالح، ان کے چچا زاد عبد اللہ بن عباس، عبد اللہ بن حارث بن نوفل ہاشمی، ان کے بیٹے عبد اللہ، عبد الرحمن بن ابو لیلیٰ، مجاہد، عروہ، اور دوسرے لوگوں نے روایت کی، ترمذی وغیرہ کا قول ہے: سیدنا علی رضی اللہ عنہ کے بعد زندہ رہیں۔","",{"fn":"(1) اسد الغابہ (۷۶۱۲) الاستيعاب (۳۶۵۴) تجرید (۳۳۷/۲)\n(2) بخاری (۵۳۶۵) مسلم (۶۴۰۳) مسند (۲۶۹/۲)\n(3) سورۃ الاحزاب الآیۃ (۵۰)"}],[10891,"§۱۲۲۸۲ ۔ ام ہانی انصاریہ\n(1) ابو عمر کا قول ہے: ابن لہیعہ کے پاس ان کی روایت بحوالہ ابو اسود مروی ہے کہ انہوں نے درہ بنت معاذ سے بحوالہ ام ہانی انصاریہ حدیث روایت کرتے ہوئے سنا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا، فرمانے لگیں: جب ہم مر جائیں کیا ایک دوسرے سے ملاقات کریں گے اور ایک دوسرے کو دیکھیں گے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'روح پرندے میں درخت کے ساتھ لٹکی ہوئی ہے۔ حتیٰ کہ جب قیامت کا دن ہو گا تو ہر روح اپنے جسم میں داخل ہو جائے گی۔'(2) اسے ابو بکر بن ابو شیبہ اور ابن سعد، ابن ابو خیثمہ نے بحوالہ اشعث روایت کیا ہے۔ اسی طرح حسن بن سفیان نے بحوالہ حسن اسے نقل کیا ہے۔ ابو عمر کا قول ہے(3)، اس کے بارے میں اختلاف ہے، بعض کا قول ہے: بحوالہ ام ہانی اور بعض فرماتے ہیں: ام قیس۔ میں کہتا ہوں: ام قیس میں گزر چکا ہے کہ عقیلی نے حدیث کو انہی الفاظ میں ابن لہیعہ کے طریق سے نقل کیا ہے، فرماتے ہیں: بحوالہ ام قیس ابو نعیم نے ان کا ذکر کیا ہے، ابو موسیٰ نے ان کی پیروی ضعیف حدیث سے کی ہے، بروایت حسن بن ابو جعفر بحوالہ ام ہذیل کہ رسول اللہ صلی اللہ علیہ وسلم کسی زمین میں تشریف لے گئے تو چرواہے کو کپڑوں کے بغیر دیکھا۔ تو فرمایا: 'اے فلاں! کوئی جگہ دیکھو، اور وہاں یہ بکریاں چھوڑ دو، اپنی مزدوری پوری لے کر اپنے گھر چلے جاؤ۔' وہ کہنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم! کیا میں جائیداد کا نظام و انصرام اچھے طریقے سے نہیں کر سکتا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: 'کیوں نہیں! ہمیں ایسے شخص کی ضرورت نہیں جسے تنہائی میں بھی اللہ سے حیا نہ ہو۔'(4) ذہبی کا قول ہے: حدیث مرسل ہے، اس کی اسناد ضعیف ہیں۔ میں کہتا ہوں: رہی اس کی ضعیف سند تو وہ واضح ہے، کیونکہ لیث ضعیف ہے اور حسن متروک ہیں۔ مسلم اور ان کی والدہ دونوں مجہول ہیں، کیونکہ ابونعیم کے شیخ اور ان کے شیخ کے شیخ میں اختلاف ہے۔ رہا مرسل ہونا تو اگر ام ہذیل، حفصہ بنت سیرین ہیں تو اس کا احتمال ہے، لیکن اس کے ارادے میں ان کا کلام واضح نہیں، اگر وہ اس کے علاوہ ہیں تو گویا اس پر تنبیہ ہونی چاہیے۔","",{"fn":"(1) اسد الغابہ (۷۶۱۱) الاستيعاب (۳۶۸۵) تجرید (۳۳۷/۲)\n(2) مسند احمد (۴۲۵/۶) مجمع الزوائد (۳۲۹/۲) اتحاف السادۃ المتقین (۳۸۷/۱۰) کنز الاعمال (۳۲۵۴)\n(3) الاستيعاب (۱۹۶۴/۴)\n(4) جامع المسانید والسنن (۵۸۹/۱۶) اسد الغابہ (۵۰۳/۵)"}],[10892,"§۱۲۲۸۴ ۔ ام ابوہریرہ\n(1) ان کا نام امینہ ہے، ان کا ذکر پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۱۴) تجرید (۳۳۷/۲)"}],[10893,"§۱۲۲۸۵ ۔ ام ہشام بنت حارثہ\n(1) بن نعمان انصاریہ۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر کا قول ہے، ام ہاشم، بعض نے کہا: ام ہشام، احمد بن زہیر نے فرمایا: میں نے اپنے والد کو بحوالہ ام ہشام بنت حارثہ فرماتے ہوئے سنا، میں نے بیعت رضوان میں بیعت کی۔ مسلم نے حبیب بن عبد الرحمن کے طریق سے بحوالہ حارثہ نقل کیا ہے، فرماتی ہیں: ہمارا اور رسول اللہ صلی اللہ علیہ وسلم کا تنور ایک تھا، میں نے سورۃ ق ﴿وَالْقُرْآنِ الْمَجِید﴾(2) رسول اللہ صلی اللہ علیہ وسلم سے سن کر یاد کی.... (الحدیث)(3) اسے اصحاب سنن نے دوسرے طریق سے بحوالہ ام ہشام بنت حارثہ بن نعمان نقل کیا ہے۔ ان میں سے بعض نے دوسرے قصے کو مختصر کیا ہے۔ ام ہاشم کے حالات میں گزر چکا ہے جو کچھ ابن عبد البر نے اس بارے میں لکھا، ابن سعد کا قول ہے: ام ہشام بنت حارثہ، بنو مالک بن نجار سے ہیں، ان کی والدہ ام خالد بنت خالد بن یعیش بن قیس بن زید مناہ ہیں، ان سے عمارہ بن حجاب بن سعد بن قیس نے نکاح کیا، اسلام لائیں اور بیعت کی، اور حدیث سنور، بحوالہ واقدی ان کی سند سے جو ان تک پہنچتی ہے روایت کی ہے، اور ابن اسحاق کے طریق سے طویل حدیث اپنی سند سے جو یحییٰ بن عبد اللہ تک پہنچتی ہے ان کے حوالے سے نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۱۵) تجرید (۳۳۷/۲)\n(2) سورۃ ق الآیۃ (۱)\n(3) مسلم (۲۰۱۲) ابوداؤد (۱۱۰۰) نسائی (۹۴۸)"}],[10894,"§۱۲۲۸۶ ۔ ام ابوہیثم بن تیہان انصاری\n(1) مسند بزار میں ان کا ذکر آیا ہے۔","",{"fn":"(1) تجرید (۳۳۷/۲)"}],[10895,"§۱۲۲۸۷ ۔ ام ہلال بنت بلال\n(1) ابن مندہ نے ان کا ذکر کیا ہے، اور مسلم کے لیے نقل کیا ہے، ابو نعیم نے اس پر عیب لگایا ہے۔ پھر فرمایا، صحیح یہ ہے: ام بلال بنت بلال۔","",{"fn":"(1) اسد الغابہ (۷۶۱۶) تجرید (۳۳۷/۲)"}],[10896,"§۱۲۲۸۸ ۔ ام وائل بنت معمر جمحیہ\nجمیل بن معمر کی بہن ہیں، بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے۔"],[10897,"§۱۲۲۸۹ ۔ ام ورقہ بنت حمزہ\n(1) بن عبد المطلب، ابو موسیٰ نے بحوالہ مستغفری ان کا ذکر کیا ہے۔ اور بحوالہ ابن حبان نقل کیا ہے کہ انہوں نے ان کے نام میں اختلاف کیا ہے۔ بعض کا قول ہے: امامہ۔ بعض نے کہا: اس کے علاوہ ہیں، اور ان کی کنیت ام ورقہ کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۷۶۱۷) تجرید (۳۳۷/۲)"}],[10898,"§۱۲۲۹۰ ۔ ام ورقہ بنت عبداللہ\n(1) بن حارث بن عویمر بن نوفل انصاریہ، بعض کا قول ہے: ام ورقہ بنت نوفل ان کے جد اعلیٰ کی طرف ان کی نسبت کی گئی۔ ابو داؤد(2) نے وکیع کے طریق سے بحوالہ ام ورقہ بنت نوفل حدیث نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب بدر میں جہاد کیا تو انہوں نے آپ صلی اللہ علیہ وسلم سے فرمایا: مجھے اجازت دیجئے کہ میں آپ کے ساتھ آؤں، میں مریضوں کی دوا کروں گی، ہو سکتا ہے کہ اللہ مجھے شہادت عطا فرمائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اپنے گھر میں قرار پکڑو، اللہ تمہیں شہادت دے گا'۔ اس لیے انہیں شہیدہ کہا جاتا تھا۔ انہوں نے قرآن پڑھ لیا تھا اور نبی کریم صلی اللہ علیہ وسلم سے اجازت مانگی کہ اپنے گھر میں اذان دینے کے لیے مؤذن رکھیں۔ آپ صلی اللہ علیہ وسلم نے انہیں اجازت دے دی۔ انہوں نے اپنے ایک غلام اور لونڈی کو مدبر بنایا ہوا تھا۔ ایک رات وہ دونوں ان کے پاس آئے، اور ان کا گلا گھونٹ کر قتل کر دیا۔ وہ فوت ہو گئیں تو یہ دونوں چلے گئے۔ صبح کے وقت سیدنا عمر رضی اللہ عنہ لوگوں سے خطاب کر کے کہنے لگے، کسے ان دونوں کے بارے میں علم ہے؟ یا جس نے انہیں دیکھا ہے وہ انہیں لے آئے۔ آپ رضی اللہ عنہ نے دونوں کو سولی دینے کا حکم دیا، وہ مدینہ میں سب سے پہلے سولی دیئے گئے۔(3) محمد بن فضیل کے طریق سے بحوالہ ام ورقہ بنت عبد اللہ بن حارث یہ نقل کیا گیا ہے، پہلی روایت زیادہ مکمل ہے۔ اسے ابن سکن نے محمد بن فضیل کے طریق سے نقل کیا ہے، اس کے الفاظ ہیں، انہوں نے فرمایا: یا رسول اللہ صلی اللہ علیہ وسلم! اگر آپ اجازت دیں تو میں آپ کے ساتھ جہاد کروں، میں مریضوں کا علاج اور زخمیوں کو دوا دوں گی، ہو سکتا ہے اللہ تعالیٰ مجھے شہادت عطا فرمائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: 'اے ام ورقہ! اپنے گھر میں بیٹھ جاؤ اللہ تعالیٰ تمہیں گھر میں شہادت عطا فرمائے گا۔ رسول اللہ صلی اللہ علیہ وسلم ان کے گھر تشریف لائے، اور آپ کے لیے ایک مؤذن مقرر کر دیا تھا۔ فرماتے ہیں: ان کا ایک غلام اور لونڈی تھی، انہوں نے ان دونوں کو مدبر بنایا تھا۔ ایک رات وہ دونوں اٹھے اور ان کا گلا گھونٹ کر انہیں قتل کر دیا۔ جب صبح ہوئی تو سیدنا عمر رضی اللہ عنہ نے فرمایا: اللہ کی قسم! میں نے اپنی خالہ ام ورقہ کی رات کو قراءت نہیں سنی۔ وہ گھر میں داخل ہوئے تو کچھ نہ تھا۔ وہ اندر گئے تو وہ چادر پر لپٹی ہوئی گھر کی ایک جانب پڑی تھیں۔ کہنے لگے: اللہ اور اس کے رسول صلی اللہ علیہ وسلم نے سچ کہا، پھر منبر پر چڑھ گئے۔ پھر اس بات کا ذکر کیا اور کہا: ان دونوں کو میرے پاس لے آؤ۔ ان دونوں کو لایا گیا، آپ نے ان سے پوچھا، ان دونوں نے اقرار کیا کہ انہوں نے انہیں قتل کیا ہے۔ آپ رضی اللہ عنہ نے انہیں سولی پر چڑھانے کا حکم دے دیا۔ ولید کی دادی کے متعلق بعض کا قول ہے کہ ان کا نام سلمیٰ ہے، ان کے اور ام ورقہ کے درمیان واسطہ ہے۔ اسے ابن سکن نے عبد اللہ بن داؤد کے طریق سے بحوالہ ام ورقہ نقل کیا ہے۔ وہ ابن مندہ کے ہاں عالی سند سے بحوالہ عبد اللہ بن داؤد مروی ہے۔ اسی طرح بعض نے کہا کہ عبد الرحمن بن خلاد اور ام ورقہ کے درمیان واسطہ ہے۔ اسے ابو نعیم نے ابو نعیم کی روایت سے بحوالہ ام ورقہ نقل کیا ہے اور کئی کی روایت کی طرح حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۷۶۱۸) الاستيعاب (۳۶۸۶) تجرید (۳۳۷/۲)\n(2) ابوداؤد (۵۹۱)\n(3) الاستيعاب (۱۹۶۵/۴)"}]])